            session = args[0]
            # Determine transaction mode; default to write_transaction
            txn_func = getattr(session, "write_transaction", None) or getattr(session, "read_transaction", None)
            if txn_func is None:
                raise AttributeError("Provided session does not support transaction functions")
            try:
                # Pass through additional arguments to the transaction function
                return txn_func(
                    func,
                    *args[1:],
                    timeout=timeout,
                    tx_metadata=metadata,
                    **kwargs
                )
            except Exception as exc:
                raise RuntimeError("Error executing transaction via unit_of_work") from exc
        return wrapper
    return decorator

