def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure the record has the expected attributes
    if not hasattr(self, "_names") or not hasattr(self, "_values"):
        raise AttributeError("Record missing '_names' or '_values' attributes")
    names_attr = getattr(self, "_names")
    values_attr = getattr(self, "_values")

    # Normalize names to a mapping of name -> index
    if isinstance(names_attr, dict):
        name_to_idx = names_attr
    else:
        try:
            name_to_idx = {name: i for i, name in enumerate(names_attr)}
        except TypeError as exc:
            raise TypeError(f"_names must be a list, tuple or dict, got {type(names_attr).__name__}") from exc

    # Ensure values is a sequence of the same length
    if not isinstance(values_attr, (list, tuple)):
        raise TypeError(f"_values must be a list or tuple, got {type(values_attr).__name__}")
    if len(values_attr) != len(name_to_idx):
        raise ValueError("Length of _values and _names must match")

    result = {}
    if not keys:
        # No specific keys requested – return all
        for name, idx in name_to_idx.items():
            result[name] = values_attr[idx]
        return result

    for key in keys:
        if isinstance(key, int):
            # Index lookup
            if key < 0 or key >= len(values_attr):
                raise IndexError(
                    f"Index {key} out of bounds for record of length {len(values_attr)}"
                )
            # Find corresponding name
            # Since dict is name->index, reverse mapping
            for name, idx in name_to_idx.items():
                if idx == key:
                    result[name] = values_attr[key]
                    break
        elif isinstance(key, str):
            # Name lookup
            idx = name_to_idx.get(key)
            if idx is not None:
                result[key] = values_attr[idx]
            else:
                result[key] = None
        else:
            raise TypeError(f"Invalid key type {type(key).__name__}; expected int or str")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate input types
        if not isinstance(n, int):
            raise TypeError(f"'n' must be an integer, got {type(n).__name__}")
        if not isinstance(qid, int):
            raise TypeError(f"'qid' must be an integer, got {type(qid).__name__}")
        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict or None")
        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict or None")

        # Build the discard message payload
        message = {
            "type": "DISCARD",
            "n": n,
            "qid": qid,
        }

        # Attach hooks if provided
        if dehydration_hooks:
            message["dehydration_hooks"] = dehydration_hooks
        if hydration_hooks:
            message["hydration_hooks"] = hydration_hooks

        # Store handlers for the response
        message["handlers"] = handlers

        # Append the message to the output queue
        outq = getattr(self, "_outqueue", None)
        if outq is None:
            raise AttributeError("No output queue '_outqueue' attribute found.")
        # Prefer list-style queue
        if hasattr(outq, "append"):
            outq.append(message)
        # Prefer asyncio-like queue
        elif hasattr(outq, "put_nowait"):
            try:
                outq.put_nowait(message)
            except Exception as e:
                raise RuntimeError(f"Failed to enqueue DISCARD message: {e}") from e
        else:
            raise TypeError("Output queue must support append() or put_nowait()")

        # Return a Response object wrapping the message, passing in handlers
        # Assume Response is defined elsewhere in this class/module.
        try:
            return Response(message, **handlers)
        except Exception as e:
            raise RuntimeError(f"Failed to create Response object: {e}") from e

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Build the discard request dictionary
        request = {
            'cmd': 'DISCARD',
            'qid': qid,
            'n': n
        }

        # Attach hooks if provided
        if dehydration_hooks is not None:
            request['dehydration_hooks'] = dehydration_hooks
        if hydration_hooks is not None:
            request['hydration_hooks'] = hydration_hooks

        # Ensure we have an output queue or transport available
        try:
            # The library providing the queue may expose a method like push, send,
            # put or append. We try a few common names and fall back to raising.
            if hasattr(self, 'output_queue'):
                queue = self.output_queue
            elif hasattr(self, 'q'):
                queue = self.q
            else:
                raise AttributeError("No output queue available on instance")

            # Different queue APIs may expect different interface
            if hasattr(queue, 'put'):
                queue.put(request)
            elif hasattr(queue, 'append'):
                queue.append(request)
            elif hasattr(queue, 'send'):
                queue.send(request)
            else:
                raise AttributeError("Queue object does not support put/append/send")
        except Exception as exc:
            # Log and propagate the exception with context
            if hasattr(self, 'log'):
                self.log.exception("Failed to enqueue DISCARD request: %s", exc)
            raise RuntimeError(f"Unable to enqueue DISCARD request: {exc}") from exc

        # Return a Response object that will handle the server's reply
        # We assume Response accepts the request dict and keyword handlers
        if hasattr(self, 'Response'):
            ResponseCls = self.Response
        else:
            # Fallback minimal Response implementation
            class ResponseCls:
                def __init__(self, request, **h):
                    self.request = request
                    self.handlers = h

                def __repr__(self):
                    return f"<Response {self.request} handlers={self.handlers}>"

        return ResponseCls(request, **handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # validate mode
    if mode is None:
        mode = "WRITE"
    else:
        mode = mode.upper()
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")

    # convert bookmarks to a list
    if bookmarks is None:
        bookmarks_list = []
    else:
        try:
            bookmarks_list = list(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable")

    # ensure metadata is a dict
    if metadata is None:
        metadata_dict = {}
    else:
        if not isinstance(metadata, dict):
            raise TypeError("metadata must be a dict")
        metadata_dict = metadata

    # store hooks if provided
    if dehydration_hooks is not None:
        self._dehydration_hooks = dehydration_hooks
    if hydration_hooks is not None:
        self._hydration_hooks = hydration_hooks

    # build the begin message
    message = {
        "type": "BEGIN",
        "mode": mode,
        "bookmarks": bookmarks_list,
        "metadata": metadata_dict,
    }
    if timeout is not None:
        message["timeout"] = timeout
    if db is not None:
        message["db"] = db
    if imp_user is not None:
        message["imp_user"] = imp_user

    # append the message to the output queue
    if hasattr(self, "_output_queue"):
        self._output_queue.append(message)
    else:
        # fallback: try a generic send method
        if hasattr(self, "send"):
            self.send(message)
        else:
            raise AttributeError("no outlet for BEGIN message")

    # return a Response instance, passing any handlers
    return Response(**handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """Append a BEGIN message to the output queue and return a Response object.

    This method constructs the options dictionary for a BEGIN message,
    validates the mode, normalises bookmark and timeout values, merges any
    dehydration/hydration hooks supplied by the caller with those already
    registered on the driver instance, enqueues the message, and finally
    returns a Response object that will hold the reply for this transaction.

    If the driver does not expose an ``_output_queue`` attribute or if the
    message cannot be enqueued, a ``RuntimeError`` will be raised.

    The ``Response`` constructor is expected to accept the message type,
    the options dict, the dehydration and hydration hooks, along with any
    additional keyword handlers supplied by the caller.

    """
    # Normalise the mode argument – default to WRITE
    if mode is not None:
        mode = mode.upper()
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be either 'READ' or 'WRITE'")
    else:
        mode = "WRITE"

    # Build the BEGIN options dictionary
    begin_opts = {"mode": mode}
    if bookmarks:
        try:
            begin_opts["bookmarks"] = list(bookmarks)
        except TypeError as exc:
            raise ValueError("bookmarks must be an iterable") from exc
    if metadata:
        begin_opts["metadata"] = metadata
    if timeout is not None:
        try:
            begin_opts["timeout"] = float(timeout)
        except (TypeError, ValueError) as exc:
            raise ValueError("timeout must be a number") from exc
    if db:
        begin_opts["database"] = db
    if imp_user:
        begin_opts["imp_user"] = imp_user

    # Merge hydration / dehydration hooks – caller hooks override existing ones
    dh_hooks = dict(getattr(self, "_dehydration_hooks", {}))
    hh_hooks = dict(getattr(self, "_hydration_hooks", {}))
    if dehydration_hooks:
        dh_hooks.update(dehydration_hooks)
    if hydration_hooks:
        hh_hooks.update(hydration_hooks)

    # Append the BEGIN message to the output queue
    try:
        # Some drivers use a tuple (message_type, options, dh_hooks, hh_hooks, handlers)
        message = ("BEGIN", begin_opts, dh_hooks, hh_hooks, handlers)
        self._output_queue.append(message)
    except AttributeError as exc:
        raise RuntimeError("Unable to enqueue BEGIN message – output queue not available"
                          ) from exc

    # Return a Response object that will collect the corresponding reply
    # The Response class is assumed to exist in the surrounding context.
    return Response(
        message_type="BEGIN",
        message=begin_opts,
        dehydration_hooks=dh_hooks,
        hydration_hooks=hh_hooks,
        **handlers
    )

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic validation of inputs
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"name must be a valid identifier, got {name!r}")
    if not isinstance(fields, (list, tuple)):
        raise TypeError(f"fields must be a list or tuple, got {type(fields)!r}")
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map)!r}")

    # Prepare namespace for the new class
    namespace: dict = {"SRID_MAP": srid_map, "__slots__": []}
    annotations: dict = {}

    for fld in fields:
        # Accepteither a bare name, a (name, type, default) tuple, or a name without type
        if isinstance(fld, str):
            fname = fld
            ftype = object
            default = None
        elif isinstance(fld, tuple):
            if len(fld) == 1:
                fname, ftype, default = fld[0], object, None
            elif len(fld) == 2:
                fname, ftype = fld
                default = None
            elif len(fld) == 3:
                fname, ftype, default = fld
            else:
                raise ValueError(f"invalid field definition: {fld!r}")
        else:
            raise TypeError(f"field must be str or tuple, got {type(fld)!r}")

        if not isinstance(fname, str) or not fname.isidentifier():
            raise TypeError(f"field names must be valid identifiers, got {fname!r}")
        annotations[fname] = ftype
        namespace["__slots__"].append(fname)
        if default is not None:
            namespace[fname] = default

    namespace["__annotations__"] = annotations

    try:
        base_cls = Point
    except NameError:
        base_cls = object

    # Dynamically create the class
    return type(name, (base_cls,), namespace)

