    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")
    for key, val in srid_map.items():
        if not isinstance(key, (int, str)):
            raise TypeError(f"SRID key {key!r} must be a string or int")
        if not isinstance(val, dict):
            raise TypeError(f"SRID value for {key!r} must be a dict of target SRIDs to transform functions")

    # Base Point class – use a simple one if an external library is not available
    try:
        from shapely.geometry import Point as _BasePoint
    except Exception:  # pragma: no cover
        class _BasePoint:
            def __init__(self, x, y):
                self.x = x
                self.y = y

    # Prepare class dictionary
    attrs = {
        "__slots__": field_names + ("srid",),
        "__doc__": f"Point subclass {name} with fields {field_names}",
    }

    # __init__ that accepts coordinates and optional fields
    def __init__(self, x, y, srid=None, *args, **kwargs):
        # Call base __init__
        super(self.__class__, self).__init__(x, y)
        self.srid = srid

        # Handle positional field values
        if args:
            if len(args) != len(field_names):
                raise TypeError(
                    f"Expected {len(field_names)} positional arguments for fields, "
                    f"got {len(args)}"
                )
            for fname, val in zip(field_names, args):
                setattr(self, fname, val)

        # Handle keyword field values
        for key, value in kwargs.items():
            if key in field_names:
                setattr(self, key, value)
            else:
                raise TypeError(f"Unexpected field name {key!r}")

    attrs["__init__"] = __init__

    # Convenience method to transform to another SRID
    def to_srid(self, target_srid):
        if self.srid is None:
            raise ValueError("Current SRID is not set")
        if target_srid == self.srid:
            return self
        srid_map_entry = srid_map.get(self.srid)
        if srid_map_entry is None:
            raise ValueError(f"No transformation mapping for source SRID {self.srid!r}")
        transform_fn = srid_map_entry.get(target_srid)
        if transform_fn is None:
            raise ValueError(
                f"No transformation function from SRID {self.srid!r} to {target_srid!r}"
            )
        # Apply transformation
        try:
            new_x, new_y = transform_fn(self.x, self.y)
        except Exception as exc:
            raise RuntimeError(
                f"Transform function for SRIDs {self.srid!r}->{target_srid!r} "
                f"raised an exception"
            ) from exc
        return self.__class__(new_x, new_y, srid=target_srid)

    attrs["to_srid"] = to_srid

    # Create the new class
    try:
        new_cls = type(name, (_BasePoint,), attrs)
    except Exception as exc:
        raise TypeError(f"Failed to create class {name!r}") from exc

    return new_cls

