def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""

    from collections.abc import Sequence as _Seq
    if not isinstance(seq, _Seq):
        raise TypeError('seq must be a Sequence')
    try:
        from hashlib import md5
    except Exception as e:
        raise RuntimeError(f'Error importing hashlib: {e}') from e
    try:
        # Use MD5 hash of each string as a deterministic sort key
        return list(sorted(seq, key=lambda s: md5(s.encode("utf-8")).hexdigest()))
    except Exception as e:
        raise ValueError(f'Error shuffling sequence: {e}') from e

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Argument must be a string")
    # Split the input on dots and attempt to extract the numeric components.
    parts = s.split('.')
    nums: list[int] = []
    for part in parts:
        if not part:
            continue
        # Grab the leading digits of each component.
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            try:
                nums.append(int(num_str))
            except ValueError:
                # Skip non-numeric parts that could not be converted.
                continue
    if not nums:
        # Return a single zero to avoid empty tuples in comparisons.
        return (0,)
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    if not isinstance(s, str):
        raise TypeError("input must be a string")
    parts = s.strip().split(".")
    nums: list[int] = []
    for part in parts:
        num_str = ""
        started = False
        for ch in part:
            if ch.isdigit():
                started = True
                num_str += ch
            elif started:
                break
        nums.append(int(num_str) if num_str else 0)
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    This function extracts all integer components from the version string in
    order and returns them as a tuple of ints.  It is intentionally simple and
    tolerant, ignoring any non‑numeric characters (e.g. \"alpha\", \"rc1\").
    """
    if not s:
        return (0,)

    import re
    parts = re.findall(r"\d+", s)
    if not parts:
        # Return a single zero if no numeric parts are found
        return (0,)

    try:
        return tuple(int(p) for p in parts)
    except Exception as exc:
        raise ValueError(f"unable to parse version string: {s!r}") from exc

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    if not s:
        return ()
    result = []

    for part in s.split('.'):
        # Find the first digit in this part
        i = 0
        while i < len(part) and not part[i].isdigit():
            i += 1
        if i == len(part):
            continue  # No digits in this segment

        # Extract the contiguous digits starting at i
        j = i
        while j < len(part) and part[j].isdigit():
            j += 1
        try:
            result.append(int(part[i:j]))
        except ValueError:
            continue

    return tuple(result)

