def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize is not None and maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if ttl <= 0:
        raise ValueError("ttl must be a positive value")

    def decorator(func):
        if not callable(func):
            raise ValueError("ttl_cache can only be applied to callables")
        from collections import OrderedDict
        cache = OrderedDict()

        def make_key(args, kwargs):
            if typed:
                # Include argument types for distinction
                key = args + tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
            else:
                key = args + tuple(sorted(kwargs.items()))
            return key

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, expire = entry
                if expire > now:
                    # Move to end to indicate recent use
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]
            result = func(*args, **kwargs)
            expire_at = now + ttl
            cache[key] = (result, expire_at)
            cache.move_to_end(key)
            if maxsize is not None and len(cache) > maxsize:
                # Pop the least-recently used item
                cache.popitem(last=False)
            return result

        return wrapper

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize <= 0:
        raise ValueError('maxsize must be a positive integer')
    if ttl <= 0:
        # No caching if ttl is zero or negative
        def decorator(func):
            return func
        return decorator

    # For cache ordering we use OrderedDict, lazily import to avoid top-level import
    try:
        from collections import OrderedDict
    except ImportError as exc:
        raise RuntimeError('collections.OrderedDict is required for ttl_cache') from exc

    def _make_key(args, kwargs):
        """Generate a hashable key from arguments."""
        if typed:
            arg_types = tuple(type(v) for v in args)
            return args, arg_types, tuple(sorted(kwargs.items()))
        else:
            return args, tuple(sorted(kwargs.items()))

    def decorator(func):
        # Ensure we wrap a callable
        if not callable(func):
            raise ValueError('ttl_cache can only be applied to callable objects')

        cache = OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            now = timer()
            # Check for cached entry
            entry = cache.get(key)
            if entry is not None:
                value, exp = entry
                if now < exp:
                    # Hit: refresh LRU position
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired: remove entry
                    del cache[key]

            # Compute fresh value
            result = func(*args, **kwargs)
            exp_time = now + ttl
            cache[key] = (result, exp_time)
            cache.move_to_end(key)
            # Evict if over maxsize
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        # Helper to clear the cache
        def clear():
            cache.clear()

        # Helper to forget specific key
        def forget(*f_args, **f_kwargs):
            key = _make_key(f_args, f_kwargs)
            cache.pop(key, None)

        wrapper.clear = clear
        wrapper.forget = forget

        return wrapper

    return decorator

