    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(fn):
        if maxsize <= 0:
            raise ValueError("maxsize must be greater than zero")

        cache = OrderedDict()

        def make_key(*args, **kwargs):
            if typed:
                key = tuple((arg, type(arg)) for arg in args)
                kw_key = tuple((k, kwargs[k], type(kwargs[k])) for k in sorted(kwargs))
                return (key, kw_key)
            else:
                key = args
                kw_key = tuple(sorted(kwargs.items()))
                return (key, kw_key)

        @wraps(fn)
        def wrapper(*args, **kwargs):
            k = make_key(*args, **kwargs)
            if k in cache:
                cache.move_to_end(k, last=True)
                return cache[k]
            result = fn(*args, **kwargs)
            cache[k] = result
            cache.move_to_end(k, last=True)
            if len(cache) > maxsize:
                # Remove the most recently used item
                cache.popitem(last=True)
            return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    def _make_key(args, kwargs):
        # create a tuple that can be hashed
        kw_items = tuple(sorted(kwargs.items()))
        key = args + kw_items
        if typed:
            key += tuple(type(v) for v in args) + tuple(type(v) for _, v in kw_items)
        return key
    def decorator(func):
        cache = {}
        order = []  # keep list of keys in insertion/use order
        from functools import wraps
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                key = _make_key(args, kwargs)
            except Exception:
                # fall back to a simple key that does not cache
                return func(*args, **kwargs)
            if key in cache:
                # move to end to mark as most recently used
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            if len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]
            return result
        return wrapper
    return decorator

