    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(func):
        # No caching if maxsize is non-positive
        if maxsize <= 0:
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        from collections import OrderedDict
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build key based on args and kwargs
            if kwargs:
                kw_items = tuple(sorted(kwargs.items()))
                key = (args, kw_items)
            else:
                key = args

            if typed:
                # Include types of positional and keyword values
                pos_types = tuple(type(v) for v in args)
                if kwargs:
                    kw_types = tuple(type(v) for v in kw_items)
                    key = (key, pos_types, kw_types)
                else:
                    key = (key, pos_types)

            try:
                # Cache hit – move to end to mark as recently used
                result = cache[key]
                cache.move_to_end(key)
                return result
            except KeyError:
                # Cache miss – compute and store result
                result = func(*args, **kwargs)
                cache[key] = result
                # Evict least-recently used item if over maxsize
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result

