def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if not isinstance(maxsize, int):
        raise TypeError('maxsize must be an integer')
    if maxsize <= 0:
        # Treat non‑positive as unlimited
        maxsize = None
    if not isinstance(typed, bool):
        raise TypeError('typed must be a boolean')

    def _make_key(args, kwargs, typed_flag):
        # Build a hashable key from the call arguments
        if kwargs:
            items = tuple(sorted(kwargs.items()))
        else:
            items = ()
        if typed_flag:
            key = args + items + tuple(type(v) for v in args) + tuple(type(v) for k, v in items)
        else:
            key = args + items
        return key

    def decorator(func):
        import functools
        if not callable(func):
            raise ValueError('The @lfu_cache decorator must wrap a callable')
        cache = {}
        freq = {}
        minfreq = None

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal minfreq
            try:
                key = _make_key(args, kwargs, typed)
            except TypeError:
                # Unhashable arguments – fall back to non‑cached call
                return func(*args, **kwargs)

            if key in cache:
                freq[key] += 1
                return cache[key]

            # Cache miss; compute result
            result = func(*args, **kwargs)

            if maxsize is None or len(cache) < maxsize:
                cache[key] = result
                freq[key] = 1
                if minfreq is None or minfreq > 1:
                    minfreq = 1
            else:
                # Eviction required – remove an entry with the lowest frequency
                if minfreq is None:
                    minfreq = min(freq.values())
                evict_key = None
                for k, f in freq.items():
                    if f == minfreq:
                        evict_key = k
                        break
                if evict_key is not None:
                    del cache[evict_key]
                    del freq[evict_key]
                cache[key] = result
                freq[key] = 1
                minfreq = 1

            return result

        # optional helper for inspection
        wrapper.cache_info = lambda: (len(cache), maxsize)
        return wrapper

    return decorator

