@classmethod
    def _reset_logging(cls):
        """
        Reset the logging configuration to the default state.
        """
        import logging
        try:
            root = logging.getLogger()
            # Remove all handlers from the root logger
            for handler in root.handlers[:]:
                try:
                    handler.close()
                except Exception:
                    pass
                root.removeHandler(handler)
            # Reconfigure basic logging to default level (INFO)
            logging.basicConfig(level=logging.INFO)
        except Exception as exc:
            # If resetting fails, try to log the error
            try:
                logging.getLogger().error(f"Failed to reset logging: {exc}")
            except Exception:
                # Swallow any further exceptions to avoid propagation
                pass

@classmethod
    def _reset_logging(cls):
        """Reset the class's logger to its default state."""
        try:
            logger = logging.getLogger(cls.__name__)
            # Remove all existing handlers to avoid duplicate logs
            if logger.handlers:
                for handler in logger.handlers[:]:
                    logger.removeHandler(handler)
            # Reset log level to the default warning level
            logger.setLevel(logging.WARNING)
            # Ensure that at least a console handler is present
            if not logger.handlers:
                console_handler = logging.StreamHandler()
                console_handler.setFormatter(
                    logging.Formatter(
                        '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
                    )
                )
                logger.addHandler(console_handler)
        except Exception:
            # Silently ignore any errors during reset
            pass

