    without the 'Py' or 'Fallback' suffix.
    """
    # Identify the base class name by stripping known suffixes
    cls = type(self)
    base_name = cls.__name__
    for suffix in ('Py', 'Fallback'):
        if base_name.endswith(suffix):
            base_name = base_name[:-len(suffix)]
            break

    # Attempt to retrieve the class from its module
