def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    result = []
    for c in classes:
        # Skip non‑class items
        if not isinstance(c, type):
            continue
        # Skip duplicates
        if c in result:
            continue
        # If an already kept class is a subclass of c, c is redundant
        redundant = False
        for r in result:
            try:
                if issubclass(r, c):
                    redundant = True
                    break
            except Exception:
                redundant = True
                break
        if redundant:
            continue
        # Remove any classes that are subclasses of c (they are more derived)
        cleaned = []
        for r in result:
            try:
                if not issubclass(r, c):
                    cleaned.append(r)
            except Exception:
                cleaned.append(r)
        result = cleaned
        # Append the current class
        result.append(c)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple")
    minimal = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"expected a class, got {type(cls)!r}")
        # Skip if this class is a subclass of any already kept base
        if any(issubclass(cls, m) for m in minimal):
            continue
        # Remove any bases already kept that are subclasses of this class
        minimal = [m for m in minimal if not issubclass(m, cls)]
        minimal.append(cls)
    return tuple(minimal)

