def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    try:
        if not isinstance(separator, str) or separator == "":
            raise ValueError("separator must be a non‑empty string")
        csv_lines = []
        if header is not None:
            csv_lines.append(str(header))
        for point, value in self:
            # Convert coordinate(s)
            coord_parts = []
            if isinstance(point, (list, tuple)):
                for c in point:
                    coord_parts.append(str(c))
            else:
                coord_parts.append(str(point))
            coord_str = separator.join(coord_parts)

            # Convert value(s)
            val_parts = []
            if isinstance(value, (list, tuple)) and not isinstance(value, (str, bytes)):
                for v in value:
                    val_parts.append(str(v))
            else:
                val_parts.append(str(value))

            csv_lines.append(separator.join([coord_str] + val_parts))
        return "\n".join(csv_lines)
    except Exception as e:
        # Return empty string or raise a custom error as appropriate
        raise RuntimeError(f"Failed to convert graph to CSV: {e}") from e

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    import io
    csv_buffer = io.StringIO()

    # Write header if provided
    if header is not None:
        if isinstance(header, (list, tuple)):
            for h in header:
                csv_buffer.write(f"{h.rstrip(chr(10)).rstrip(chr(13))}\n")
        else:
            csv_buffer.write(f"{header.rstrip(chr(10)).rstrip(chr(13))}\n")

    # Iterate over points in the graph.
    # A point is expected to be either a tuple (coords, value)
    # or an object with `coords` and `value` attributes.
    for point in self:
        try:
            if hasattr(point, "coords") and hasattr(point, "value"):
                coords, value = point.coords, point.value
            elif isinstance(point, tuple) and len(point) == 2:
                coords, value = point
            else:
                # Skip unexpected point format
                continue
        except Exception as e:
            raise RuntimeError(f"Failed to unpack point {point!r}: {e}") from e

        # Convert coordinates to string
        try:
            coord_str = separator.join(map(str, coords))
        except Exception as e:
            raise RuntimeError(f"Failed to stringify coordinates {coords!r}: {e}") from e

        # Convert value to string / list of strings
        if value is None:
            val_parts = []
        elif isinstance(value, (list, tuple)):
            val_parts = [str(v) for v in value]
        else:
            val_parts = [str(value)]

        # Combine coordinates and value parts
        line = separator.join([coord_str] + val_parts)
        csv_buffer.write(line + "\n")

    # Return CSV content as a string
    return csv_buffer.getvalue()

