def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    bins_arr = np.asarray(bins)
    # If edges is a single array (1-D histogram)
    if np.ndim(edges) == 1:
        edges_arr = np.asarray(edges)
        if edges_arr.ndim != 1:
            raise ValueError("edges must be a 1-D array for a 1D histogram")
        if bins_arr.ndim != 1:
            raise ValueError("bins and edges dimensionalities do not match")
        if len(edges_arr) != len(bins_arr) + 1:
            raise ValueError("number of edges must be one more than number of bins")
        width = np.diff(edges_arr)
        if np.any(width <= 0):
            raise ValueError("edges must be strictly increasing")
        return float(np.sum(bins_arr * width))

    # If edges is a list or tuple of arrays (multi-dimensional histogram)
    if isinstance(edges, (list, tuple)):
        edge_arrays = [np.asarray(e) for e in edges]
        if len(edge_arrays) != bins_arr.ndim:
            raise ValueError("number of edge arrays must match number of dimensions of bins")
        # Validate each edge array
        for i, e in enumerate(edge_arrays):
            if e.ndim != 1:
                raise ValueError(f"edge array at dimension {i} must be 1-D")
            if len(e) != bins_arr.shape[i] + 1:
                raise ValueError(f"edge array at dimension {i} must have length {bins_arr.shape[i] + 1}")
        # Compute widths for each dimension
        width_arrays = [np.diff(e) for e in edge_arrays]
        # Broadcast widths to match bin shape
        for i, w in enumerate(width_arrays):
            shape = [1] * bins_arr.ndim
            shape[i] = w.size
            width_arrays[i] = w.reshape(shape)
        # Multiply widths across all dimensions
        width_product = width_arrays[0]
        for w in width_arrays[1:]:
            width_product = width_product * w
        # Ensure widths are positive
        if np.any(width_product <= 0):
            raise ValueError("edge arrays must be strictly increasing in all dimensions")
        return float(np.sum(bins_arr * width_product))

    # Unsupported edges format
    raise TypeError("edges must be a 1-D array or a sequence of 1-D arrays")

