def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise TypeError("coord must be array‑like") from exc

    if coord_arr.ndim != 1:
        raise ValueError("coord must be a 1‑D array matching the histogram dimensions")

    n_dims = len(self.edges)
    if coord_arr.size != n_dims:
        raise ValueError(f"coord length {coord_arr.size} does not match histogram dimensions {n_dims}")

    # Determine bin indices; ignore if any coordinate is out of bounds
    idxs = []
    for dim, c in enumerate(coord_arr):
        edges = self.edges[dim]
        if c < edges[0] or c >= edges[-1]:
            return  # Outside histogram bounds; ignore
        idx = np.searchsorted(edges, c, side='right') - 1
        idxs.append(idx)

    # Update the corresponding bin
    try:
        self.values[tuple(idxs)] += weight
    except Exception as exc:
        raise RuntimeError("Failed to update histogram bin") from exc

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    import numpy as np
    # Validate coordinates
    try:
        coord_arr = np.asarray(coord)
    except Exception as exc:
        raise TypeError("coord must be array-like") from exc
    if coord_arr.ndim != 1:
        raise ValueError("coord must be 1D array of length equal to number of dimensions")
    if len(coord_arr) != len(self.edges):
        raise ValueError("coord length must match number of histogram dimensions")
    # Find bin indices for each dimension
    indices = []
    for dim, edge in enumerate(self.edges):
        # searchsorted gives position where coord would be inserted on the right
        # Subtract 1 to get the bin index (0-based)
        i = np.searchsorted(edge, coord_arr[dim], side='right') - 1
        # Check bounds: valid indices are 0 <= i < len(edge)-1
        if i < 0 or i >= len(edge) - 1:
            return  # coordinate outside histogram bounds; ignore
        indices.append(i)
    # Increment corresponding bin by weight
    try:
        self.weights[tuple(indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Error updating histogram bin: {exc}") from exc

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure `coord` is array‑like and has the correct dimensionality
    try:
        coord = np.asarray(coord)
    except Exception as exc:
        raise TypeError("`coord` must be array‑like") from exc

    # Normalize 0‑D input to 1‑D for consistent processing
    if coord.ndim == 0:
        coord = np.array([coord])

    # Validate that the coordinate has the right number of dimensions
    if coord.ndim != 1:
        raise ValueError(
            f"Expected a 1‑D coordinate, got array with shape {coord.shape}"
        )
    if len(coord) != len(self.edges):
        raise ValueError(
            f"Coordinate dimensionality {len(coord)} does not match histogram "
            f"dimensionality {len(self.edges)}"
        )

    # Find the bin index for each coordinate dimension, ignoring out‑of‑range
    bin_indices = []
    for dim, val in enumerate(coord):
        edges = self.edges[dim]
        # Outside the valid range: ignore the fill request
        if val < edges[0] or val >= edges[-1]:
            return
        # Find the bin index using binary search
        idx = np.searchsorted(edges, val, side="right") - 1
        bin_indices.append(idx)

    # Clip any potential off‑by‑one errors due to rounding
    bin_indices = tuple(max(0, min(idx, len(edges) - 2)) for idx, edges in zip(bin_indices, self.edges))

    # Increment the histogram bin by the specified weight
    try:
        self.hist[bin_indices] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram bin {bin_indices}") from exc

    # Track the total weight (if an attribute exists)
    if hasattr(self, "total"):
        self.total += weight
    else:
        self.total = weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    messages = []

    # Regular expression for valid label keys and values.
    KEY_REGEX = re.compile(r'^[a-zA-Z0-9_-]{1,63}$')
    VALUE_REGEX = re.compile(r'^[a-zA-Z0-9_-]{1,255}$')

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            messages.append({str(key): 'expected string or bytes-like object'})
        else:
            if not KEY_REGEX.match(key):
                messages.append(
                    {key: f"Label key '{key}' does not match the regex [{KEY_REGEX.pattern}]"}
                )

        # Validate value
        if not isinstance(value, (str, bytes)):
            messages.append({str(value): 'expected string or bytes-like object'})
        else:
            if not VALUE_REGEX.match(value):
                messages.append(
                    {value: f"Label value '{value}' does not match the regex [{VALUE_REGEX.pattern}]"}
                )

    if messages:
        raise ValidationError(messages)

