def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Ensure we have a string to validate
    if not isinstance(value, (str, bytes)):
        raise ValidationError("Value must be a string or bytes instance")

    # Convert bytes to string if necessary
    if isinstance(value, bytes):
        try:
            value = value.decode("utf-8")
        except Exception as exc:
            raise ValidationError(f"Unable to decode bytes value: {exc}")

    # Define the regular expression to match allowed characters.
    # Here we use a generic pattern that matches alphanumeric characters and underscores.
    # Change this pattern if a more specific validation is required.
    regex_str = r"^\w+$"
    try:
        pattern = re.compile(regex_str)
    except re.error as exc:
        raise ValidationError(f"Invalid regex pattern '{regex_str}': {exc}")

    # Perform the match; raise if it doesn't conform.
    if not pattern.fullmatch(value):
        raise ValidationError(
            f"Value '{value}' does not match the required pattern '{regex_str}'"
        )

    return value

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial observer_schema dict from a Kubernetes resource fragment.
    All non-dict and non-list leaf values are replaced with ``None``.  When
    the input dictionary represents the full top‑level observer_schema
    (``first_level=True``), the identifying fields are preserved from the
    source manifest.  Unknown or unsupported keys are ignored.

    Args:
        manifest_dict (dict): Partial Kubernetes resource.
        first_level (bool, optional): ``True`` if this call corresponds to the
            top‑level observer_schema of a Kubernetes resource.

    Returns:
        dict: A new dictionary with the same structure as ``manifest_dict`` but
        with primitive values replaced by ``None``.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    # Keys that identify a Kubernetes resource and should be copied when creating
    # a full observer_schema.  Only copied at the top level.
    id_keys = {"apiVersion", "kind", "metadata"}

    for key, value in manifest_dict.items():
        # Preserve identifying fields unchanged at the top level
        if first_level and key in id_keys:
            result[key] = value
            continue

        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Primitive value – replace with None
            result[key] = None

    # In case some identifying keys are missing from the source dict but are
    # expected in the observer_schema, ensure they are present with a ``None``
    # value when at the top level.
    if first_level:
        for key in id_keys:
            if key not in result:
                result[key] = None

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``. In case of ``first_level`` dictionary
    (i.e. complete ``observer_schema`` for a resource), the values of the identifying
    fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Preserve scalar values in top‑level metadata
            if first_level and key == "metadata":
                processed = {}
                for k2, v2 in value.items():
                    if isinstance(v2, dict):
                        processed[k2] = generate_default_observer_schema_dict(v2, first_level=False)
                    elif isinstance(v2, list):
                        processed[k2] = [
                            generate_default_observer_schema_dict(e, first_level=False)
                            if isinstance(e, dict) else None
                            for e in v2
                        ]
                    else:
                        processed[k2] = v2
                result[key] = processed
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = [
                generate_default_observer_schema_dict(e, first_level=False)
                if isinstance(e, dict) else None
                for e in value
            ]
        else:
            # Scalar value: keep if at top level, otherwise replace with None
            result[key] = value if first_level else None
    return result

