def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application has the expected attributes
    try:
        manifest = app.spec.manifest
    except AttributeError as exc:
        raise ValueError(
            "The provided application does not expose a 'spec.manifest' attribute"
        ) from exc

    # Use existing observer schemas if present, otherwise start with an empty dict
    observer_schemas = getattr(app.spec, "observer_schemas", {})
    if observer_schemas is None:
        observer_schemas = {}

    # Compile a set of kinds already handled by custom schemas
    handled_kinds = set(observer_schemas.keys())

    # Iterate through each resource in the manifest
    for resource in manifest:
        # Handle dictionary resources that contain a 'kind' field
        if isinstance(resource, dict) and "kind" in resource:
            kind = resource["kind"]
        else:
            # If the entry is not in the expected format, skip it
            continue

        if not kind or kind in handled_kinds:
            continue

        # Assemble a very basic default observer schema
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"},
                    },
                },
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
        }

        # Register the default schema for this kind
        observer_schemas[kind] = default_schema

    # Persist the updated schema mapping back to the spec if it exists
    if hasattr(app.spec, "observer_schemas"):
        app.spec.observer_schemas = observer_schemas

    return observer_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Try to get the application's spec object, falling back to attributes
        spec = getattr(app, "spec", {})
    except Exception:
        return

    # Retrieve the existing observer schema, if any
    try:
        existing_schema = getattr(spec, "observer_schema", {})
    except Exception:
        existing_schema = {}

    if not isinstance(existing_schema, dict):
        existing_schema = {}

    # Fetch the manifest of resources
    try:
        manifest = getattr(spec, "manifest", {})
    except Exception:
        manifest = {}

    # Build a list of resource objects from the manifest
    resources = []
    if isinstance(manifest, list):
        resources = manifest
    elif isinstance(manifest, dict):
        for value in manifest.values():
            if isinstance(value, list):
                resources.extend(value)
            else:
                resources.append(value)

    # Helper to map Python types to JSON Schema types
    def _json_type(py_val):
        if isinstance(py_val, bool):
            return "boolean"
        if isinstance(py_val, (int, float)):
            return "number"
        if isinstance(py_val, dict):
            return "object"
        if isinstance(py_val, list):
            return "array"
        return "string"

    # Generate defaults for each resource missing a custom schema
    for res in resources:
        try:
            kind = res.get("kind") if isinstance(res, dict) else getattr(res, "kind", None)
            if not kind or kind in existing_schema:
                continue

            spec_obj = res.get("spec") if isinstance(res, dict) else getattr(res, "spec", {})
            properties = {}
            if isinstance(spec_obj, dict):
                for k, v in spec_obj.items():
                    properties[k] = {"type": _json_type(v)}

            default_schema = {
                "type": "object",
                "properties": properties,
                "required": list(properties.keys()),
            }
            existing_schema[kind] = default_schema
        except Exception:
            # Skip any resource that raises an unexpected error
            continue

    # Store the updated schema back to the spec
    try:
        setattr(spec, "observer_schema", existing_schema)
    except Exception:
        pass

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        manifest = app.spec.manifest
    except AttributeError:
        # Application spec does not contain a manifest; nothing to do
        return

    # Ensure the manifest is a mapping; if it is a sequence wrap it in a dict
    if isinstance(manifest, list):
        resources = {str(index): item for index, item in enumerate(manifest)}
    elif isinstance(manifest, dict):
        resources = manifest
    else:
        # Unknown format; cannot process
        return

    # Ensure there is an observer_schema mapping on the spec
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}

    for _, res in resources.items():
        if not isinstance(res, dict):
            continue

        kind = res.get("kind")
        if not kind:
            continue

        # Skip resources that already have a custom observer schema
        if kind in app.spec.observer_schema:
            continue

        # Build a very simple default schema that mirrors the top‑level keys of the resource
        properties = {}
        for field_name, field_value in res.items():
            field_type = type(field_value)
            if field_type is dict:
                properties[field_name] = {"type": "object"}
            elif field_type is list:
                properties[field_name] = {"type": "array"}
            elif field_type is bool:
                properties[field_name] = {"type": "boolean"}
            elif field_type is int:
                properties[field_name] = {"type": "integer"}
            elif field_type is float:
                properties[field_name] = {"type": "number"}
            else:
                properties[field_name] = {"type": "string"}

        default_schema = {"type": "object", "properties": properties}
        app.spec.observer_schema[kind] = default_schema

    return app.spec.observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    import copy
    # Ensure the necessary attributes exist
    spec = getattr(app, "spec", None)
    if spec is None:
        return
    manifest = getattr(spec, "manifest", [])
    # Use a simple default schema: metadata.name is required
    _default_schema = {
        "metadata": {
            "name": {"type": "string"}
        }
    }
    # Initialize observer_schemas dict if missing
    observer_schemas = getattr(spec, "observer_schemas", None)
    if observer_schemas is None:
        observer_schemas = {}
        setattr(spec, "observer_schemas", observer_schemas)
    # Build default schemas for each resource kind
    for resource in manifest:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        if kind not in observer_schemas:
            observer_schemas[kind] = copy.deepcopy(_default_schema)

def format(self, sql, params):
    """Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (str or bytes) is the SQL query.

    *params* (Mapping or Sequence) contains the set of in-style parameters.
    It maps each parameter (str or int) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style, then *params* must be a Mapping.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a Sequence.

    Returns a tuple containing:

    - The formatted SQL query (str or bytes).
    - The set of converted out-style parameters (dict or list).
    """
    import re
    from collections.abc import Mapping, Sequence

    # Preserve original type of sql (bytes or str)
    is_bytes = isinstance(sql, bytes)
    sql_text = sql.decode('utf-8') if is_bytes else sql

    # Ensure SQLParams attributes exist
    if not hasattr(self, 'SQLParams'):
        raise ValueError('Missing SQLParams attribute on instance')
    in_style = getattr(self.SQLParams, 'in_style', None)
    out_style = getattr(self.SQLParams, 'out_style', None)
    if in_style is None or out_style is None:
        raise ValueError('SQLParams must define in_style and out_style')

    # Helper to convert placeholders
    if isinstance(params, Mapping):
        # Named style placeholder detection
        named_patterns = [
            (r':([A-Za-z_][A-Za-z0-9_]*)', ':', 'NAME'),                # :name
            (r'%\(([A-Za-z_][A-Za-z0-9_]*)\)s', r'%(\1)s', 'NAMED_PERC')  # %(name)s
        ]
        pattern = None
        for pat, repl, typ in named_patterns:
            if re.search(pat, sql_text):
                pattern = pat
                break
        if pattern is None:
            raise ValueError('No named placeholders found in SQL')
        # Find all placeholder keys in order
        placeholders = [m.group(1) for m in re.finditer(pattern, sql_text)]
        if len(placeholders) == 0:
            # No placeholders found; return as is
            return (sql, dict(params))
        # Build output parameters list
        output_params = [params[key] for key in placeholders]
        # Replacement counter for numeric/named outputs
        counter = 0
        def repl_func(match):
            nonlocal counter
            counter += 1
            if out_style == 'qmark':
                return '?'
            elif out_style == 'numeric':
                return f'${counter}'
            elif out_style == 'named':
                key = match.group(1)
                return f':{key}'
            else:
                # Fall back to original placeholder
                return match.group(0)
        new_sql = re.sub(pattern, repl_func, sql_text)
        result_sql = new_sql.encode('utf-8') if is_bytes else new_sql
        return (result_sql, output_params)

    elif isinstance(params, Sequence) and not isinstance(params, (str, bytes)):
        # Ordinal style placeholder detection
        ord_patterns = {
            'numeric': r'\$[1-9][0-9]*',
            'qmark'  : r'\?',
        }
        if in_style not in ord_patterns:
            raise ValueError(f'Unsupported in_style for sequence: {in_style}')
        pattern = ord_patterns[in_style]
        # Count placeholders
        placeholder_matches = list(re.finditer(pattern, sql_text))
        if len(placeholder_matches) != len(params):
            raise ValueError('Number of params does not match number of placeholders')
        counter = 0
        def repl_func(match):
            nonlocal counter
            counter += 1
            if out_style == 'qmark':
                return '?'
            elif out_style == 'numeric':
                return f'${counter}'
            elif out_style == 'named':
                return f':param{counter}'
            else:
                return match.group(0)
        new_sql = re.sub(pattern, repl_func, sql_text)
        result_sql = new_sql.encode('utf-8') if is_bytes else new_sql
        return (result_sql, list(params))
    else:
        raise TypeError('params must be mapping for named styles or sequence for ordinal styles')

