def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Ensure prefix is a string
    try:
        prefix_str = str(prefix)
    except Exception:
        prefix_str = ''
    # Attempt to locate the log attribute
    log = None
    for attrs in ('validation_log', 'log', '_validation_log', '_log'):
        if hasattr(self, attrs):
            log = getattr(self, attrs)
            break
    if log is None:
        return prefix_str
    # If log is a simple string or bytes, return it directly
    if isinstance(log, (str, bytes)):
        try:
            log_str = log.decode('utf-8') if isinstance(log, bytes) else log
        except Exception:
            log_str = str(log)
        return f"{prefix_str}{log_str}"
    # If log is not iterable, treat it as a single entry
    try:
        iterator = iter(log)
    except TypeError:
        return f"{prefix_str}{str(log)}"
    lines = []
    for entry in iterator:
        try:
            if isinstance(entry, (dict, list, tuple)):
                import json
                lines.append(json.dumps(entry, default=str))
            else:
                lines.append(str(entry))
        except Exception:
            lines.append(f"<unrepresentable entry {entry!r}>")
    # Add prefix to each line
    prefixed = [f"{prefix_str}{line}" for line in lines]
    return "\n".join(prefixed)

