    try:
        # Attempt to locate a log-like attribute on the instance.
        attr_candidates = ('log', 'messages', 'entries', 'validation_log')
        entries = None
        for attr in attr_candidates:
            if hasattr(self, attr):
                entries = getattr(self, attr)
                break

        # If no log attribute is found, return an empty string.
        if entries is None:
            return ''

        # If the entries attribute is a plain string, prepend the prefix and return.
        if isinstance(entries, str):
            return f"{prefix}{entries}"

        # If the entries attribute is an iterable (excluding bytes-like objects),
        # iterate over it and build the output line by line.
        if hasattr(entries, '__iter__') and not isinstance(entries, (bytes, bytearray)):
            lines = []
            for entry in entries:
                try:
                    line = str(entry)
                except Exception:
                    # Fallback representation if entry cannot be converted to string.
                    line = repr(entry)
                lines.append(f"{prefix}{line}")
            return '\n'.join(lines)

        # Fallback: convert the entries attribute to string and prepend the prefix.
        return f"{prefix}{str(entries)}"

    except Exception:
        # On any unexpected error, return an empty string rather than propagating exceptions.
        return ''

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        log = getattr(self, 'validation_log', None)
    except Exception:
        log = None

    if log is None:
        return prefix.rstrip() + "\n"

    results = []
    for entry in log:
        try:
            if isinstance(entry, dict):
                # Represent dict as key=value pairs
                line = ', '.join(f"{k}={v!r}" for k, v in entry.items())
            else:
                line = str(entry)
        except Exception:
            line = str(entry)
        results.append(f"{prefix}{line}")

    return "\n".join(results) + ("\n" if results else "")

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Ensure inventory is a dictionary
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        # Determine the specification version to use
        spec_version = getattr(self, 'spec_version', None)

        if extract_spec_version:
            try:
                type_value = inventory.get('type')
                # Accept string or integer representation of the version
                if type_value is not None:
                    if isinstance(type_value, str):
                        # Strip leading/trailing whitespace
                        type_str = type_value.strip()
                        # Normalize common prefixes like "v" or "spec"
                        if type_str.lower().startswith('v'):
                            type_str = type_str[1:]
                        if type_str.lower().startswith('spec'):
                            type_str = type_str[4:]
                        # Try integer conversion
                        try:
                            type_int = int(type_str)
                            type_value_to_match = type_int
                        except ValueError:
                            type_value_to_match = type_str
                    elif isinstance(type_value, int):
                        type_value_to_match = type_value
                    else:
                        type_value_to_match = None

                    # Verify that the extracted value matches one of the allowed versions
                    allowed_versions = getattr(self, 'allowed_spec_versions', set())
                    if allowed_versions and type_value_to_match in allowed_versions:
                        spec_version = type_value_to_match
            except Exception:
                # If anything goes wrong during extraction, fall back to the
                # instance's default spec_version (which may already be None)
                pass

        # Perform whatever additional checks are necessary.  If this class
        # implements a helper method called `_validate_inventory`, delegate to
        # it; otherwise simply return the inventory unchanged as a placeholder.
        if hasattr(self, "_validate_inventory") and callable(self._validate_inventory):
            return self._validate_inventory(inventory, spec_version)
        else:
            # If no validation logic exists, return the inventory unchanged.
            return inventory

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # inventory must be a mapping type
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dictionary")

    # Determine which spec version to use
    spec_version = getattr(self, "spec_version", None)
    if spec_version is None:
        raise AttributeError("The validator instance has no 'spec_version' attribute")

    if extract_spec_version:
        inv_type = inventory.get("type")
        if inv_type is None:
            # No type field, fall back to the instance's spec_version
            pass
        else:
            # validate that type is a recognised spec version
            if not isinstance(inv_type, str):
                raise TypeError("inventory['type'] must be a string")
            supported = getattr(self, "SUPPORTED_SPEC_VERSIONS", ())
            if inv_type not in supported:
                raise ValueError(
                    f"Unsupported inventory type '{inv_type}'. "
                    f"Supported types: {supported}"
                )
            spec_version = inv_type

    # Ensure the chosen spec_version is supported
    supported = getattr(self, "SUPPORTED_SPEC_VERSIONS", ())
    if spec_version not in supported:
        raise ValueError(
            f"spec_version '{spec_version}' is not supported. "
            f"Supported versions: {supported}"
        )

    # Delegate to the appropriate version‑specific validator if it exists
    try:
        # The naming convention is _validate_{spec_version lower case}
        validator_name = f"_validate_{spec_version.lower()}"
        validator = getattr(self, validator_name, None)
        if validator is None:
            # Fall back to a generic validation routine
            validator = getattr(self, "_generic_validate", None)
            if validator is None:
                raise NotImplementedError(
                    f"No validator found for spec_version '{spec_version}'"
                )
        # Run the validator; it should raise if invalid
        validator(inventory)
    except Exception as exc:
        raise ValueError(
            f"Failed to validate inventory against spec_version '{spec_version}': {exc}"
        ) from exc

    # If we reach here, validation succeeded
    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine which spec version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get('type')
        if type_val is not None:
            if isinstance(type_val, int):
                spec_version = type_val
            elif isinstance(type_val, str):
                try:
                    spec_version = int(type_val)
                except ValueError:
                    # Attempt to pull a numeric version out of a descriptive string
                    nums = [int(part) for part in type_val.split() if part.isdigit()]
                    if nums:
                        spec_version = nums[0]
            # If type_val is None or unparseable, fall back to self.spec_version

    # Store the inferred spec version for the remainder of validation
    self.spec_version = spec_version

    # Basic structure checks
    resources = inventory.get('resources')
    if resources is None:
        raise ValueError("Inventory missing required 'resources' key.")
    if not isinstance(resources, dict):
        raise ValueError("'resources' must be a dictionary.")

    # Version‑specific requirements
    if spec_version >= 2 and 'metadata' not in inventory:
        raise ValueError(f"Inventory missing required 'metadata' key for spec version {spec_version}.")

    # Validate each contained resource
    for name, definition in resources.items():
        if not isinstance(definition, dict):
            raise ValueError(f"Resource '{name}' must be a dictionary.")
        if 'type' not in definition:
            raise ValueError(f"Resource '{name}' missing required 'type' field.")

    # If all checks pass, return the inventory unchanged
    return inventory

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        if extract_spec_version:
            typ = inventory.get('type')
            if isinstance(typ, str) and typ.lower() in ('dpna', 'dpna2'):
                self.spec_version = typ.lower()

        # Validation based on specification version
        if self.spec_version == 'dpna':
            required_keys = ['id', 'name']
        elif self.spec_version == 'dpna2':
            required_keys = ['id', 'name', 'serial']
        else:
            raise ValueError(f"Unknown specification version: {self.spec_version}")

        missing = [k for k in required_keys if k not in inventory]
        if missing:
            raise ValueError(f"Missing required keys for {self.spec_version}: {missing}")

        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Basic validation
    if manifest_files is None or digests_used is None:
        raise ValueError("manifest_files and digests_used must be provided")
    # Normalize manifest digests to a set
    if isinstance(manifest_files, dict):
        manifest_set = set(manifest_files.keys())
    else:
        try:
            manifest_set = set(manifest_files)
        except TypeError:
            raise TypeError("manifest_files must be a dict or an iterable of digests")
    # Normalize used digests to a set
    if isinstance(digests_used, (set, list, tuple)):
        used_set = set(digests_used)
    else:
        try:
            used_set = set(digests_used)
        except TypeError:
            raise TypeError("digests_used must be a set, list, or tuple of digests")
    # Find missing and unused digests
    missing = manifest_set - used_set
    unused = used_set - manifest_set
    if missing:
        raise ValueError(f"Digests present in manifest but not used: {', '.join(sorted(missing))}")
    if unused:
        raise ValueError(f"Digests used but not present in manifest: {', '.join(sorted(unused))}")
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files:
        raise ValueError("No manifest files provided")
    usable = set(digests_used or [])
    # Convert manifest input into an iterable of (filename, digest) or digest only
    if isinstance(manifest_files, dict):
        iterable = manifest_files.items()
    else:
        try:
            iterable = manifest_files
        except Exception:
            raise TypeError("manifest_files must be a dict or iterable")
    for item in iterable:
        if isinstance(item, tuple) and len(item) == 2:
            filename, expected_digest = item
            digests = self.analyzed_files.get(filename)
            if not digests:
                raise ValueError(f"File '{filename}' missing from analyzed files.")
            if expected_digest not in digests:
                raise ValueError(f"Digest '{expected_digest}' for file '{filename}' not present.")
            if expected_digest not in usable:
                raise ValueError(f"Digest '{expected_digest}' for file '{filename}' not marked as used.")
        else:
            expected_digest = item
            found = any(expected_digest in dlist for dlist in self.analyzed_files.values())
            if not found:
                raise ValueError(f"Digest '{expected_digest}' not found in any analyzed file.")
            if expected_digest not in usable:
                raise ValueError(f"Digest '{expected_digest}' not marked as used.")

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure input is the same type
        if not isinstance(prior, type(self)):
            raise TypeError(f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")

        # Both inventories should expose a 'version' attribute
        if not hasattr(self, "version") or not hasattr(prior, "version"):
            raise ValueError("Both inventories must have a 'version' attribute.")

        # Prior version must be strictly older
        if prior.version >= self.version:
            raise ValueError(f"Prior inventory version ({prior.version}) must be older than current version ({self.version}).")

        # Helper to compare set-like attributes
        def _compare_attrs(attr_name, error_msg):
            current = getattr(self, attr_name, None)
            prior_attr = getattr(prior, attr_name, None)
            if current is None or prior_attr is None:
                # If the attribute is not present, skip check
                return
            if isinstance(current, (set, frozenset)):
                if not isinstance(prior_attr, (set, frozenset)):
                    raise ValueError(error_msg.format(attr_name, type(current).__name__, type(prior_attr).__name__))
                if not prior_attr.issubset(current):
                    missing = current - prior_attr
                    raise ValueError(f"{error_msg.format(attr_name, 'current', 'prior')} Missing: {missing}")
            else:
                # For non-set attributes, require exact equality
                if current != prior_attr:
                    raise ValueError(f"{error_msg.format(attr_name, str(current), str(prior_attr))}")

        # Compare species and parameters (assumed to be set of names)
        _compare_attrs("species", "Attribute '{}' mismatch: current={1}, prior={2}")
        _compare_attrs("parameters", "Attribute '{}' mismatch: current={1}, prior={2}")

        # Ensure all policies in the current inventory are present in the prior
        current_policies = getattr(self, "policies", {})
        prior_policies = getattr(prior, "policies", {})
        if not isinstance(current_policies, dict) or not isinstance(prior_policies, dict):
            raise ValueError("Both inventories must have 'policies' as a dict.")
        missing_policies = set(current_policies) - set(prior_policies)
        if missing_policies:
            raise ValueError(f"Current inventory has policies not present in prior: {missing_policies}")

        # Optionally, check that settings in current are supersets of prior settings
        current_settings = getattr(self, "settings", {})
        prior_settings = getattr(prior, "settings", {})
        if isinstance(current_settings, dict) and isinstance(prior_settings, dict):
            for key, value in prior_settings.items():
                if key not in current_settings or current_settings[key] != value:
                    raise ValueError(f"Setting '{key}' in prior ({value}) not found or differs in current ({current_settings.get(key)!r}).")
        return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an InventoryValidator instance")

    # Species should be identical between current and prior
    if set(self.species) != set(prior.species):
        raise ValueError(f"Species mismatch: current {self.species} vs prior {prior.species}")

    # Parameters should be identical between current and prior
    if set(self.parameters) != set(prior.parameters):
        raise ValueError(f"Parameters mismatch: current {self.parameters} vs prior {prior.parameters}")

    # Stoichiometry matrix shape and value checks
    if self.stoichiometry_matrix.shape != prior.stoichiometry_matrix.shape:
        raise ValueError(f"Stoichiometry matrix shape mismatch: current {self.stoichiometry_matrix.shape} vs prior {prior.stoichiometry_matrix.shape}")

    if not np.array_equal(self.stoichiometry_matrix, prior.stoichiometry_matrix):
        raise ValueError("Stoichiometry matrix values differ between current and prior inventory")

    # Propensity list length and content checks
    if len(self.propensities) != len(prior.propensities):
        raise ValueError(f"Number of propensities differ: current {len(self.propensities)} vs prior {len(prior.propensities)}")

    for i, (p_current, p_prior) in enumerate(zip(self.propensities, prior.propensities)):
        if p_current != p_prior:
            raise ValueError(f"Propensity mismatch at index {i}: current {p_current} vs prior {p_prior}")

    return  # passes silently if no error is raised

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, type(self)):
        raise TypeError(f"Prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")

    # Ensure required attributes exist
    required_attrs = ("version", "inventory")
    for attr in required_attrs:
        if not hasattr(self, attr) or not hasattr(prior, attr):
            raise AttributeError(f"Missing required attribute '{attr}'")

    # Compare version numbers – prior must be older
    try:
        if prior.version >= self.version:
            raise ValueError(
                f"Prior version ({prior.version}) must be older than current version ({self.version})"
            )
    except TypeError:
        # If version objects are not comparable, skip this check
        pass

    self_keys = set(self.inventory.keys())
    prior_keys = set(prior.inventory.keys())

    # Prior inventory should not contain keys absent from current inventory
    missing_keys = prior_keys - self_keys
    if missing_keys:
        raise ValueError(
            f"Prior inventory contains keys not present in current inventory: {missing_keys}"
        )

    # Basic type compatibility check for common keys
    numeric_types = (int, float, complex)
    for key in prior_keys:
        curr_val = self.inventory[key]
        prior_val = prior.inventory[key]
        if type(curr_val) is not type(prior_val):
            if not (isinstance(curr_val, numeric_types) and isinstance(prior_val, numeric_types)):
                raise ValueError(
                    f"Type mismatch for key '{key}': {type(curr_val).__name__} vs {type(prior_val).__name__}"
                )

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Normalise inventory structure
    source = inventory
    if isinstance(inventory, dict) and 'data' in inventory:
        source = inventory['data']

    if not isinstance(source, dict):
        raise TypeError('Inventory must be a dict or dict with a "data" key')

    # Check that the requested version exists
    if version not in source:
        raise ValueError(f'Version {version!r} not found in inventory')

    # Helper to determine if a version should be considered (>= requested)
    def version_ge(v, req):
        try:
            return v >= req
        except Exception:  # e.g., incomparable types
            return False

    logical_map = {}

    for ver, state in source.items():
        # Skip versions that are earlier than requested
        try:
            if not version_ge(ver, version):
                continue
        except Exception:
            # If we cannot compare, skip this entry
            continue

        if not isinstance(state, dict):
            continue

        for logical_path, content in state.items():
            if logical_path not in logical_map:
                logical_map[logical_path] = set()
            # Ensure content is iterable of file paths
            if isinstance(content, (list, tuple, set)):
                logical_map[logical_path].update(content)
            else:
                # Treat non-iterable as single path
                logical_map[logical_path].add(content)

    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version is None:
        raise ValueError("version must be specified")

    # Helper to compare two version strings.  If both look numeric we do a
    # numeric comparison, otherwise fall back to string comparison.
    def _cmp(v1, v2):
        try:
            n1, n2 = float(v1), float(v2)
            return (n1 > n2) - (n1 < n2)
        except Exception:
            return (v1 > v2) - (v1 < v2)

    path_map = {}
    for logical_path, version_map in inventory.items():
        if not isinstance(version_map, dict):
            continue
        files = set()
        for ver, content in version_map.items():
            # decide whether to include this file mapping
            if _cmp(str(ver), str(version)) <= 0:
                # content can be a list, set or a single string
                if isinstance(content, (list, set)):
                    for f in content:
                        if isinstance(f, str):
                            files.add(f)
                elif isinstance(content, str):
                    files.add(content)
        if files:
            path_map[logical_path] = files
    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in later
    versions than the version being described.
    """
    # Basic type checks
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to path maps.")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or integer identifier.")

    # Retrieve the mapping for the given version
    try:
        version_map = inventory[version]
    except KeyError:
        raise ValueError(f"Version '{version}' not found in the inventory.")

    if not isinstance(version_map, dict):
        raise TypeError(f"Inventory entry for version '{version}' must be a dictionary.")

    # Construct the result mapping, ensuring each value is a set
    result = {}
    for logical_path, files in version_map.items():
        if files is None:
            files_set = set()
        elif isinstance(files, set):
            files_set = files
        elif isinstance(files, (list, tuple, set)):
            files_set = set(files)
        else:
            raise TypeError(
                f"Files for logical path '{logical_path}' must be an iterable of filenames."
            )
        result[logical_path] = files_set

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, str) or not version:
        raise ValueError("version must be a non-empty string")

    def _compare_version(v1, v2):
        """
        Compare two version strings.

        Returns:
            1 if v1 > v2
            -1 if v1 < v2
            0 if v1 == v2
        """
        import re

        def _parse(v):
            # Split on non-digits to capture numeric components
            parts = re.split(r'\D+', v)
            return [int(p) for p in parts if p.isdigit()]

        p1 = _parse(v1)
        p2 = _parse(v2)
        # Normalize length
        maxlen = max(len(p1), len(p2))
        p1.extend([0] * (maxlen - len(p1)))
        p2.extend([0] * (maxlen - len(p2)))

        if p1 > p2:
            return 1
        if p1 < p2:
            return -1
        return 0

    result = {}
    for logical_path, data in inventory.items():
        if not isinstance(data, dict):
            # Skip malformed entries
            continue
        file_set = set()
        for ver, files in data.items():
            try:
                if _compare_version(ver, version) >= 0:
                    if isinstance(files, (list, tuple, set)):
                        file_set.update(files)
                    else:
                        # If a single file path given
                        file_set.add(files)
            except Exception:
                # Skip entries where version comparison fails
                continue
        if file_set:
            result[logical_path] = file_set
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version is None:
        raise ValueError("version must be provided")

    result = {}

    # Case 1: inventory is a mapping from version -> mapping of logical_path -> content files
    if version in inventory:
        entry = inventory[version]
        if isinstance(entry, dict):
            for logical_path, files in entry.items():
                if isinstance(files, (set, list, tuple)):
                    result[logical_path] = set(files)
                else:
                    # Single file represented as string
                    result[logical_path] = {files}
            return result

    # Case 2: inventory is a mapping from logical_path -> mapping of version -> content files
    for logical_path, ver_map in inventory.items():
        if isinstance(ver_map, dict) and version in ver_map:
            files = ver_map[version]
            if isinstance(files, (set, list, tuple)):
                result[logical_path] = set(files)
            else:
                result[logical_path] = {files}

    if not result:
        raise KeyError(f"Version '{version}' not found in inventory")

    return result

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError(
                f"Fixity block must be a dict, got {type(fixity).__name__}"
            )
        # Ensure manifest_files is iterable of strings
        try:
            manifest_set = set(str(name) for name in manifest_files)
        except TypeError:
            raise ValueError(
                "manifest_files must be an iterable of file names"
            )
        # Iterate over each entry in the fixity block
        for file_name, entry in fixity.items():
            if file_name not in manifest_set:
                raise ValueError(
                    f"Fixity entry references unknown file '{file_name}'."
                )
            if not isinstance(entry, dict):
                raise ValueError(
                    f"Fixity entry for '{file_name}' must be a dict, "
                    f"got {type(entry).__name__}"
                )
            # Expected keys in each fixity entry
            for key in ("checksum", "algorithm"):
                if key not in entry:
                    raise ValueError(
                        f"Missing '{key}' in fixity entry for '{file_name}'."
                    )
                if not isinstance(entry[key], str):
                    raise ValueError(
                        f"'{key}' for '{file_name}' must be a string."
                    )
        # If all checks pass, return True (optional)
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError('Fixity block must be a dictionary')
    if 'files' not in fixity:
        raise ValueError('Fixity block missing required "files" key')
    if not isinstance(fixity['files'], list):
        raise ValueError('The "files" field in the fixity block must be a list')

    for i, f in enumerate(fixity['files']):
        if not isinstance(f, dict):
            raise ValueError(f'Item #{i} in fixity.files must be a dictionary')
        # Required keys (paths and checksum are mandatory for integrity checks)
        if 'path' not in f:
            raise ValueError(f'File entry #{i} missing required "path" key')
        if 'checksum' not in f:
            raise ValueError(f'File entry #{i} missing required "checksum" key')
        # Ensure no extraneous keys? (allow them, but warn)
        # Validate that referenced file exists in manifest
        path = f['path']
        if path not in manifest_files:
            raise ValueError(f'Fixity block references file "{path}" not found in the manifest')
    # If we reach this point, the fixity block is considered valid
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.

    :param dict fixity: mapping of file names to digest dictionaries
    :param Collection[str] manifest_files: iterable of file names that
        are allowed to appear in the fixity block
    :raises ValueError: if the structure is invalid or an unknown file
        is referenced
    """
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity must be a dict, got {type(fixity).__name__}")

    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError(
            f"manifest_files must be a list, set or tuple, got {type(manifest_files).__name__}"
        )

    manifest_set = set(manifest_files)

    for fname, entry in fixity.items():
        if fname not in manifest_set:
            raise ValueError(f"Fixity references unknown file: '{fname}'")

        if not isinstance(entry, dict):
            raise ValueError(
                f"Entry for '{fname}' must be a dict, got {type(entry).__name__}"
            )

        # Expected keys
        required_keys = {"method", "value"}
        missing_keys = required_keys - entry.keys()
        if missing_keys:
            raise ValueError(
                f"Entry for '{fname}' missing required keys: {', '.join(sorted(missing_keys))}"
            )

        # Ensure values are strings
        method = entry.get("method")
        value = entry.get("value")
        if not isinstance(method, str) or not isinstance(value, str):
            raise ValueError(
                f"Fields 'method' and 'value' for '{fname}' must be strings"
            )

    return True

def validate_fixity(self, fixity, manifest_files):
