def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    packages = {}

    if not os.path.isdir(folder):
        return packages

    try:
        for entry in os.scandir(folder):
            if not entry.is_file():
                continue

            name = entry.name
            base, ext = os.path.splitext(name)
            if base not in packages:
                packages[base] = {}

            ext = ext.lower()
            if ext == ".xml":
                try:
                    tree = ET.parse(entry.path)
                    packages[base]["xml"] = ET.tostring(tree.getroot(), encoding="unicode")
                except Exception as ex:
                    packages[base]["xml"] = None
            else:
                # Store other files as file paths; extension as key without dot
                key = ext.lstrip(".")
                packages[base][key] = entry.path
    except Exception as exc:
        # If an unexpected exception occurs while scanning, return what we have
        return packages

    return packages

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        path completo do arquivo a ser analisado

    Returns
    -------
    dict
        dicionário contendo a chave `prefix` com subchaves `type` (valor
        ``'asset'`` ou ``'rendition'``) e `file` (caminho completo do arquivo).
    """
    import os
    result = {}
    try:
        # Determinar o tipo a partir da extensão, se possível
        _, ext = os.path.splitext(file_path)
        ext = ext.lower()
        if ext in {'.asset'}:
            file_type = 'asset'
        elif ext in {'.rend', '.rendition'}:
            file_type = 'rendition'
        else:
            # Caso a extensão não indique, verificar conteúdo relevante
            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    snippet = f.read(2048).lower()
                    if 'rendition' in snippet:
                        file_type = 'rendition'
                    elif 'asset' in snippet:
                        file_type = 'asset'
                    else:
                        file_type = 'unknown'
            except Exception:
                file_type = 'unknown'

        result[prefix] = {
            'type': file_type,
            'file': os.path.abspath(file_path)
        }
    except Exception as exc:
        # Em caso de erro, registrar informação no resultado
        result[prefix] = {
            'type': 'error',
            'message': str(exc)
        }
    return result

