def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Collect basenames for XML files
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                _, ext = os.path.splitext(info.filename)
                if ext.lower() == '.xml':
                    base = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_basenames.add(base)
            # Initialize result dictionary
            for base in xml_basenames:
                result[base] = {}
            # Group files by matching basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base = os.path.splitext(os.path.basename(info.filename))[0]
                if base in xml_basenames:
                    try:
                        content = zf.read(info.filename)
                    except Exception:
                        content = None
                    result[base][info.filename] = content
    except Exception:
        # If the zip cannot be opened or read, return empty dict
        return {}
    return result

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            # Read all non-directory entries into a map
            file_map = {}
            for info in zin.infolist():
                if info.is_dir():
                    continue
                file_map[info.filename] = zin.read(info.filename)

            # For each XML file, group other files in the same directory
            for path, content in file_map.items():
                if path.lower().endswith('.xml'):
                    basename = os.path.splitext(os.path.basename(path))[0]
                    dirpath = os.path.dirname(path)
                    other_files = {}
                    for p, c in file_map.items():
                        if p == path:
                            continue
                        if os.path.dirname(p) == dirpath and not p.lower().endswith('.xml'):
                            rel_name = os.path.basename(p)
                            other_files[rel_name] = c
                    result[basename] = {
                        'xml': content,
                        'files': other_files
                    }
    except (FileNotFoundError, zipfile.BadZipFile):
        # If the file cannot be opened or is not a zip, return empty dict
        return {}
    return result

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # first gather all xml entries
            xml_infos = [
                inf for inf in zf.infolist()
                if inf.filename.lower().endswith(".xml") and not inf.filename.endswith("/")
            ]
            for xml_info in xml_infos:
                # base name without extension
                base = os.path.splitext(os.path.basename(xml_info.filename))[0]
                try:
                    xml_data = zf.read(xml_info.filename)
                except Exception:
                    continue  # skip unreadable xml
                dirpath = os.path.dirname(xml_info.filename)
                files = []
                for inf in zf.infolist():
                    if inf.filename.endswith("/") or inf.filename == xml_info.filename:
                        continue
                    if os.path.dirname(inf.filename) == dirpath:
                        try:
                            content = zf.read(inf.filename)
                        except Exception:
                            continue
                        files.append((inf.filename, content))
                packages[base] = {"xml": xml_data, "files": files}
    except FileNotFoundError:
        raise
    except (zipfile.BadZipFile, Exception):
        return {}
    return packages

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for zinfo in zf.infolist():
                # skip directories
                if zinfo.is_dir():
                    continue
                # read file content
                try:
                    raw = zf.read(zinfo.filename)
                except Exception:
                    # skip files that cannot be read
                    continue
                # determine base name (basename without extension)
                base = os.path.splitext(os.path.basename(zinfo.filename))[0]
                # For XML files, decode to string
                if zinfo.filename.lower().endswith('.xml'):
                    try:
                        content = raw.decode('utf-8')
                    except Exception:
                        content = raw.decode('latin1', errors='replace')
                else:
                    content = raw
                # initialize group entry if needed
                if base not in packages:
                    packages[base] = {}
                # store content keyed by relative path inside zip
                packages[base][zinfo.filename] = content
    except Exception as e:
        # In case of bad zip or path error, return empty dict
        return {}
    return packages

