def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Number of spaces for indentation of each line (default 0).
    debug : bool, optional
        If True, include type information for each attribute
        (default False).

    Returns
    -------
    str
        Human‑readable representation of the object.
    """
    # Validate arguments
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")

    # Helper to format a single attribute
    def fmt_attr(name, value, level):
        space = " " * (level * 2)
        if debug:
            return f"{space}{name} ({type(value).__name__}): {repr(value)}"
        return f"{space}{name} = {repr(value)}"

    # Gather attributes: prefer __dict__ then slots
    attrs = {}
    if hasattr(self, "__dict__"):
        attrs.update(vars(self))
    if hasattr(self, "__slots__"):
        for slot in getattr(self, "__slots__"):
            if hasattr(self, slot):
                attrs[slot] = getattr(self, slot)

    # Build lines
    lines = [f"{self.__class__.__name__}:"]
    if not attrs:
        lines.append("  (no public attributes)")
    else:
        for name in sorted(attrs):
            lines.append(fmt_attr(name, attrs[name], indent))
    return "\n".join(lines)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Indentation level for the output. If <=0, a compact representation is returned.
    debug : bool, optional
        If True, include the object's type, module, and memory address in the output.

    Returns
    -------
    str
        A human‑readable representation of ``self``.
    """
    import pprint

    try:
        if debug:
            header = f"{type(self).__module__}.{type(self).__qualname__} at {hex(id(self))}"
            body = pprint.pformat(self, indent=indent if indent > 0 else 1, width=80)
            return f"{header}\n{body}"
        else:
            if indent > 0:
                return pprint.pformat(self, indent=indent, width=80)
            else:
                return repr(self)
    except Exception:
        return repr(self)

