def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Use a set to handle circular references
    visited = set()

    def _format(obj, level):
        # Detect circular references
        obj_id = id(obj)
        if obj_id in visited:
            return "<Circular reference>"
        visited.add(obj_id)

        # Basic immutable types
        if isinstance(obj, (int, float, complex, bool, type(None))):
            return repr(obj)
        if isinstance(obj, str):
            return repr(obj)

        # Collections
        if isinstance(obj, (list, tuple, set, frozenset)):
            if isinstance(obj, list):
                open_char, close_char = "[", "]"
            elif isinstance(obj, tuple):
                open_char, close_char = "(", ")"
            elif isinstance(obj, set):
                open_char, close_char = "set({", "})"
            else:  # frozenset
                open_char, close_char = "frozenset({", "})"

            if not obj:
                return f"{open_char}{close_char}"

            ind = "  " * (level + 1)
            inner = ",\n".join(f"{ind}{_format(item, level + 1)}" for item in obj)
            return f"{open_char}\n{inner}\n{'  ' * level}{close_char}"

        if isinstance(obj, dict):
            if not obj:
                return "{}"

            ind = "  " * (level + 1)
            inner = ",\n".join(f"{ind}{repr(k)}: {_format(v, level + 1)}" for k, v in obj.items())
            return f"{{\n{inner}\n{'  ' * level}}}"

        # Objects with attributes
        if hasattr(obj, "__dict__"):
            # Class name (optionally with module when debug)
            cls = obj.__class__
            class_name = f"{cls.__module__}.{cls.__name__}" if debug else cls.__name__
            if not obj.__dict__:
                return f"{class_name}{{}}"

            ind = "  " * (level + 1)
            inner = ",\n".join(f"{ind}{k}={_format(v, level + 1)}" for k, v in obj.__dict__.items())
            return f"{class_name}{{\n{inner}\n{'  ' * level}}}"

        # Fallback for unsupported types
        return repr(obj)

    return _format(self, indent)

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        def decorator(fn):
            # Prefer a dedicated registration method if available
            if hasattr(self, "register_hook"):
                self.register_hook(hook, fn)
            else:
                # Fallback to a simple dictionary-based registry
                if not hasattr(self, "_registry"):
                    self._registry = {}
                self._registry.setdefault(hook, []).append(fn)
            return fn
        return decorator

