def get_versions():
    """Get version information or return default if unable to do so."""
    import os, re
    try:
        # Determine directory of this file
        dir_path = os.path.dirname(__file__)

        # Potential locations that may contain version information
        candidates = [
            os.path.join(dir_path, "version.py"),
            os.path.join(dir_path, "VERSION"),
            os.path.join(dir_path, "setup.py"),
            os.path.join(dir_path, "pyproject.toml"),
            os.path.join(dir_path, "setup.cfg"),
        ]

        for path in candidates:
            if os.path.isfile(path):
                if path.endswith(".py"):
                    # Try to extract __version__ or v assignments from a Python file
                    with open(path, "r", encoding="utf-8") as f:
                        data = f.read()
                    match = re.search(r'__version__\s*=\s*[\'"]([^\'"]+)[\'"]', data)
                    if match:
                        return match.group(1)
                    match = re.search(r'v\s*=\s*[\'"]([^\'"]+)[\'"]', data)
                    if match:
                        return match.group(1)
                else:
                    # For non‑Python files, return the first non‑empty line
                    with open(path, "r", encoding="utf-8") as f:
                        for line in f:
                            value = line.strip()
                            if value:
                                return value
        return "unknown"
    except Exception:
        return "unknown"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, dict):
        raise TypeError("pieces must be a dict")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()
    try:
        major = str(pieces.get("major", 0))
        minor = str(pieces.get("minor", 0))
        patch = str(pieces.get("patch", 0))
        prerelease = pieces.get("prerelease", "")
        build = pieces.get("build", "")
        base = f"{major}.{minor}.{patch}"
        if style == "semver":
            result = base
            if prerelease:
                result += f"-{prerelease}"
            if build:
                result += f"+{build}"
            return result
        if style == "short":
            return f"{major}.{minor}"
        if style == "full":
            return base
        if style == "compact":
            if patch == "0":
                return f"{major}.{minor}"
            return base
        if style == "pre_release":
            if prerelease:
                return f"{base}-{prerelease}"
            return base
        raise ValueError(
            f"Unsupported style '{style}'. Supported styles: semver, short, full, compact, pre_release"
        )
    except Exception as exc:
        raise ValueError("Failed to render version pieces") from exc

