        dictionary, each key/value pair is rendered as `key: value`.
      - 'json': JSON representation of the *pieces* object.
      - 'yaml': YAML representation of the *pieces* object. Falls back to
        JSON if `yaml` is not available.
      - 'repr': Python representation, e.g. ``repr(pieces)``.
    The function is tolerant to a variety of iterable inputs and raises
    a ``ValueError`` for unsupported styles or non-iterable *pieces*.
    """
    # Normalise style to lower‑case string
    try:
        style = str(style).lower()
    except Exception as exc:
        raise ValueError(f"Style must be a string, got {type(style).__name__}") from exc

    # Reject completely empty or None *pieces*
    if pieces is None:
        raise ValueError("No pieces supplied for rendering")

    # Helper to build lines from an iterable
    def _iter_to_lines(it):
        lines = []
        for item in it:
            if isinstance(item, (list, tuple)):
                lines.append(", ".join(str(x) for x in item))
            else:
                lines.append(str(item))
        return lines

    if style in ("text", "plain"):
        if isinstance(pieces, dict):
            lines = [f"{k}: {v}" for k, v in pieces.items()]
        else:
            try:
                lines = _iter_to_lines(pieces)
            except TypeError as exc:
                raise ValueError("Pieces must be an iterable for text style") from exc
        return "\n".join(lines)

    if style == "json":
        try:
            import json
            return json.dumps(pieces, indent=2, sort_keys=True)
        except Exception as exc:
            raise RuntimeError("Failed to serialize to JSON") from exc

    if style == "yaml":
        try:
            import yaml
        except ImportError:
            # Fallback to JSON if YAML support is not available
            try:
                import json
                return json.dumps(pieces, indent=2, sort_keys=True)
            except Exception as exc:
                raise RuntimeError("Failed to serialize to JSON (fallback for YAML)") from exc
        try:
            return yaml.safe_dump(pieces, sort_keys=True)
        except Exception as exc:
            raise RuntimeError("Failed to serialize to YAML") from exc

    if style == "repr":
        return repr(pieces)

    raise ValueError(f"Unsupported style: {style}")

