def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import sys

    # Prepare command line list
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]

    if args:
        if isinstance(args, (list, tuple)):
            cmd_list.extend(args)
        else:
            cmd_list.append(args)

    # Verbose output
    if verbose:
        print('Running command:', ' '.join(cmd_list), file=sys.stderr)

    # Determine stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        output = subprocess.check_output(
            cmd_list,
            cwd=cwd,
            env=env,
            stderr=stderr,
            shell=False
        )
        # Decode output to string
        if isinstance(output, bytes):
            output = output.decode('utf-8')
    except subprocess.CalledProcessError as e:
        # Re-raise the error with a clear message
        raise subprocess.CalledProcessError(e.returncode, e.cmd, output=output if 'output' in dir(e) else None)

    return output.strip() if output is not None else ''

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None:
        raise ValueError("commands must not be None")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a sequence")
    # Build the full command list
    if isinstance(commands, str):
        cmd_list = [commands] + list(args)
    else:
        if not commands:
            raise ValueError("commands list cannot be empty")
        if isinstance(commands[0], str):
            cmd_list = [commands[0]] + list(args)
        else:
            raise TypeError("invalid command format")
    if verbose:
        print("Running command: {}".format(' '.join(cmd_list)))
    # Configure stderr handling
    stderr = subprocess.PIPE if hide_stderr else None
    try:
        proc = subprocess.Popen(
            cmd_list,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr,
            env=env
        )
    except OSError as e:
        raise RuntimeError(f"Failed to start process: {e}")
    out, err = proc.communicate()
    if proc.returncode != 0:
        message = f"Command '{' '.join(cmd_list)}' failed with exit code {proc.returncode}"
        if not hide_stderr and err:
            message += f"\nError output: {err.decode(errors='replace')}"
        raise subprocess.CalledProcessError(proc.returncode, cmd_list, output=out, stderr=err)
    return out.decode(errors='replace')

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    # Normalise commands to a list
    if isinstance(commands, str):
