def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    # Resolve the base command to a list of tokens
    if isinstance(commands, str):
        cmd = shlex.split(commands)
    else:
        try:
            cmd = list(commands)
        except TypeError as exc:
            raise ValueError("commands must be a string or an iterable of strings") from exc

    # Append any additional arguments
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")
        if cwd:
            print(f"  Working directory: {cwd}")
        if env:
            print(f"  Environment variables: {env}")

    # Prepare stderr redirection
    stderr_mode = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_mode,
            text=True,
            check=False
        )
    except OSError as exc:
        raise RuntimeError(f"Failed to execute command: {cmd}") from exc

    # Handle non-zero exit codes
    if result.returncode != 0:
        err_msg = result.stderr.strip() if result.stderr else "Unknown error"
        raise subprocess.CalledProcessError(result.returncode, cmd, output=result.stdout, stderr=err_msg)

    if verbose and result.stdout:
        print("Command output:")
        print(result.stdout)

    return result.stdout.strip()

