def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        import hashlib
        num_objects = 0
        good_objects = 0

        # Determine where the objects are stored; fall back to empty list if not present
        try:
            objects = self.objects
        except AttributeError:
            objects = []

        for obj in objects:
            num_objects += 1
            is_valid = True

            # Optional structural validation
            if validate_objects:
                try:
                    if hasattr(obj, "validate"):
                        obj.validate()
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARNING] Validation error for object {obj}: {exc}")

            # Optional digest validation
            if check_digests and is_valid:
                try:
                    if hasattr(obj, "content") and hasattr(obj, "digest"):
                        content = obj.content
                        if isinstance(content, bytes):
                            computed = hashlib.sha256(content).hexdigest()
                        else:
                            computed = hashlib.sha256(str(content).encode()).hexdigest()
                        if computed != obj.digest:
                            is_valid = False
                            if show_warnings:
                                print(f"[WARNING] Digest mismatch for object {obj}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARNING] Digest check failed for object {obj}: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        Whether to run the object's own ``validate`` method.  If ``False`` the
        hierarchy is presumed correct and only structural checks are
        performed.  Default is ``True``.
    check_digests : bool, optional
        Whether to verify each object's cryptographic digest (if a
        ``digest`` attribute exists).  Default is ``True``.
    show_warnings : bool, optional
        If ``True`` failed checks will be logged with the module's
        ``logger``.  Default is ``False``.

    Returns
    -------
    tuple
        ``(num_objects, good_objects)`` – the total number of objects
        examined and the count of objects that passed all requested checks.

    Raises
    ------
    TypeError
        If any of the arguments is not a boolean.
    RuntimeError
        If the method cannot retrieve the objects to be checked.
    """
    # Validate argument types
    for name, value in (
        ("validate_objects", validate_objects),
        ("check_digests", check_digests),
        ("show_warnings", show_warnings),
    ):
        if not isinstance(value, bool):
            raise TypeError(f"Argument '{name}' must be a bool, got {type(value).__name__}")

    # Retrieve all objects in the hierarchy.  Subclasses may provide
    # a more efficient implementation; this generic fallback looks for
    # an ``objects`` attribute or calls ``_gather_objects`` if present.
    try:
        if hasattr(self, "_gather_objects"):
            objects = self._gather_objects()
        else:
            objects = getattr(self, "objects", [])
    except Exception as exc:
        raise RuntimeError("Unable to gather objects for hierarchy validation") from exc

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        obj_valid = True

        if validate_objects:
            try:
                obj.validate()
            except Exception as e:
                obj_valid = False
                if show_warnings:
                    try:
                        self.logger.warning(f"Validation failed for {obj}: {e}")
                    except Exception:
                        # If the logger itself fails we silently ignore
                        pass

        if check_digests and obj_valid and hasattr(obj, "digest"):
            try:
                # Some objects expose a ``verify_digest`` helper.
                if hasattr(obj, "verify_digest"):
                    obj.verify_digest()
                else:
                    # Fallback: compare the precomputed digest with a recomputed one.
                    import hashlib
                    expected = obj.digest
                    data = getattr(obj, "data", b"")
                    actual = hashlib.sha256(data).hexdigest()
                    if expected != actual:
                        raise ValueError("Digest mismatch")
            except Exception as e:
                obj_valid = False
                if show_warnings:
                    try:
                        self.logger.warning(f"Digest check failed for {obj}: {e}")
                    except Exception:
                        pass

        if obj_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib
    import mimetypes

    # Determine the storage root; raise in case it is not set
    if hasattr(self, "_root"):
        root = self._root
    elif hasattr(self, "root"):
        root = self.root
    else:
        raise AttributeError("The instance does not have a storage root attribute.")

    num_objects = 0
    good_objects = 0

    for dirpath, dirnames, filenames in os.walk(root,
                                                topdown=True,
                                                followlinks=False):
        for name in filenames:
            filepath = os.path.join(dirpath, name)
            num_objects += 1
            is_valid = True

            # Optional basic type validation
            if validate_objects:
                mime, _ = mimetypes.guess_type(filepath)
                if mime is None:
                    if show_warnings:
                        print(f"Warning: unknown MIME type for {filepath}")
                    is_valid = False

            # Optional digest checking
            if check_digests:
                digest_file = filepath + ".sha256"
                if os.path.exists(digest_file):
                    try:
                        with open(filepath, "rb") as f:
                            data = f.read()
                        actual = hashlib.sha256(data).hexdigest()

                        with open(digest_file, "r") as df:
                            expected = df.read().strip()

                        if actual != expected:
                            if show_warnings:
                                print(f"Warning: digest mismatch for {filepath}")
                            is_valid = False
                    except Exception as exc:
                        if show_warnings:
                            print(f"Warning: error validating {filepath}: {exc}")
                        is_valid = False

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    total_objects = 0
    good_objects = 0

    # Assume the instance has an iterable of objects to validate.
    # If not, fall back to an empty list.
    objects = getattr(self, 'objects', getattr(self, 'items', []))
    if objects is None:
        objects = []

    for obj in objects:
        total_objects += 1
