                        is_valid = False
                        if show_warnings:
                            obj_id = getattr(obj, 'id', repr(obj))
                            print(f"[WARNING] Digest mismatch for object {obj_id}: expected {expected}, got {computed}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    obj_id = getattr(obj, 'id', repr(obj))
                    print(f"[WARNING] Digest check failed for object {obj_id}: {exc}")

        if is_valid:
            good_objects += 1

    return total_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    root = self.root_path
    if os.path.exists(root):
        raise ValueError(f"Root {root} already exists.")
    try:
        os.makedirs(root)
        layout_path = os.path.join(root, "ocfl-layout.txt")
        with open(layout_path, "w") as f:
            f.write("Version: 1.0\n")
    except OSError as exc:
        # Clean up partially created directory, if any.
        if os.path.isdir(root):
            try:
                shutil.rmtree(root)
            except Exception:
                pass
        raise ValueError(f"Failed to initialize OCFL root {root}: {exc}") from exc
    return self

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    root = getattr(self, "root", None)
    if root is None:
        raise AttributeError("The instance must have a 'root' attribute set before initialization.")
    if os.path.exists(root):
        raise FileExistsError(f"Root path {root} already exists.")
    try:
        os.makedirs(root)
    except OSError as exc:
        raise RuntimeError(f"Failed to create root directory '{root}': {exc}") from exc
    # Create the primary objects directory
    objects_dir = os.path.join(root, "objects")
    try:
        os.makedirs(objects_dir)
    except OSError as exc:
