    # Create a lock file to signal the repository is initialized
    lock_path = os.path.join(root, "ocfl.lock")
    try:
        with open(lock_path, "w") as f:
            f.write("initialized")
    except OSError as exc:
        raise RuntimeError(f"Failed to create lock file '{lock_path}': {exc}") from exc
    # Persist a minimal root metadata file
    root_json = os.path.join(root, "root.json")
    try:
