                },
                f,
                indent=2,
            )
    except OSError as exc:
        raise RuntimeError(f"Failed to write root metadata file '{root_json}': {exc}") from exc
    # Mark the instance as initialized
    self.initialized = True
    return root_json

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Ensure the root_path attribute is set
    root_path = getattr(self, "root_path", None)
    if not root_path:
        raise ValueError("The storage root path must be set before initialization.")
    root = os.path.abspath(os.path.expanduser(root_path))

    # Handle existing root directory
    if os.path.exists(root):
        if not os.path.isdir(root):
            raise ValueError(f"Root path '{root}' exists but is not a directory.")
        # Accept an empty directory, but complain if it contains files
        if os.listdir(root):
            raise ValueError(f"Root path '{root}' already exists and is not empty.")
    else:
        try:
            os.makedirs(root)
        except OSError as exc:
            raise RuntimeError(f"Failed to create root directory '{root}': {exc}") from exc

    # Create required subdirectories
    subdirs = [
        os.path.join(root, "objects"),
        os.path.join(root, "objects", "manifest"),
    ]
    for sd in subdirs:
        if not os.path.exists(sd):
            try:
                os.makedirs(sd)
            except OSError as exc:
                raise RuntimeError(f"Failed to create subdirectory '{sd}': {exc}") from exc

    # Write a minimal root configuration file
    config_path = os.path.join(root, "ocfl_root.json")
    root_config = {
        "ocfl_version": "1.0",
        "rootid": os.path.basename(root),
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "layout_rules": {"objects": {"layout": "1"}},
    }
    try:
        with open(config_path, "w", encoding="utf-8") as cfg:
            json.dump(root_config, cfg, indent=2)
    except OSError as exc:
        raise RuntimeError(f"Failed to write root configuration file '{config_path}': {exc}") from exc

    # Mark as initialized if the object tracks that
    if hasattr(self, "_initialized"):
        self._initialized = True
    return None

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json

    # Verify that root_path has been set
    if not hasattr(self, "root_path") or not isinstance(self.root_path, str):
        raise ValueError("Attribute 'root_path' must be a non‑empty string")

    root = self.root_path

    # Ensure the root directory exists
    try:
        os.makedirs(root, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Cannot create root directory '{root}': {exc}") from exc

    # Check that this is not already an OCFL root
    ocfl_file = os.path.join(root, ".ocfl.json")
    if os.path.exists(ocfl_file):
        raise FileExistsError(f"OCFL root already initialized at '{root}'")

    # Create a minimal OCFL metadata file
    ocfl_info = {
        "ocflVersion": "2.0",
        "format": "ocfl_1.0"
    }
    try:
        with open(ocfl_file, "w", encoding="utf-8") as fp:
            json.dump(ocfl_info, fp, indent=2)
    except OSError as exc:
        raise OSError(f"Cannot write OCFL metadata file '{ocfl_file}': {exc}") from exc

    # Create required subdirectories
    required_subdirs = ("objects", "meta", "blobs")
    for sub in required_subdirs:
