        except OSError as exc:
            raise OSError(f"Cannot create subdirectory '{sub_path}': {exc}") from exc

    return True

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""

    version = version.strip()
    if not version:
        return ""

    parts = version.split('.')
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        # If any component cannot be parsed as an integer, return original.
        return version

    # Increment the last component
    nums[-1] += 1

    new_parts = []
    for orig, new_val in zip(parts, nums):
        # Preserve leading zeros if the original part had them
        if orig[0] == '0' and len(orig) > 1:
            new_part = str(new_val).zfill(len(orig))
        else:
            new_part = str(new_val)
        new_parts.append(new_part)

    return '.'.join(new_parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    parts = version.split('.')
    if not parts:
        return "1"

    # Validate all parts are numeric
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"Invalid version component: '{p}'")

    # Increment the last part
    last = parts[-1]
    new_num = int(last) + 1
    new_str = str(new_num)

    # Preserve original zero padding if it existed
    if len(new_str) < len(last):
        new_str = last[:len(last)-len(new_str)] + new_str

    parts[-1] = new_str
    return '.'.join(parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    try:
        parts = version.split(".")
        last = parts[-1]
        if last.isdigit():
            inc = int(last) + 1
            # Preserve leading zeros if the increment does not increase width
            new_last = str(inc).zfill(len(last)) if len(str(inc)) <= len(last) else str(inc)
            parts[-1] = new_last
            return ".".join(parts)
        else:
            # If the last component isn't purely numeric, leave it unchanged
            return version
    except Exception:
        # In case of unexpected format, return the original string
        return version

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Ensure we have a place to record differing digests
    self.different_digests = {}

    root_inventory = None
    # Iterate over the versions in order
    for idx, vdir in enumerate(version_dirs):
        # Build the expected path to the inventory file.
        # It is assumed that each vdir is a subdirectory under the same base
        # directory where the version inventories live.
        inv_path = os.path.join(self.base_path, vdir, "inventory.json")

        # Load the inventory JSON file
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inventory = json.load(fh)
        except OSError as exc:
            raise ValueError(f"Could not read inventory at {inv_path!r}: {exc}") from exc
        except json.JSONDecodeError as exc:
            raise ValueError(f"Inventory in {inv_path!r} is not valid JSON: {exc}") from exc

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory at {inv_path!r} must be a mapping, not {type(inventory).__name__}")

        # The first inventory defines the root
        if idx == 0:
            root_inventory = inventory
            continue

        # Every subsequent inventory must contain (or at least preserve) all entries
        # that existed in the root inventory (i.e. our baseline).
        missing_keys = set(root_inventory) - set(inventory)
        if missing_keys:
            sorted_missing = sorted(missing_keys)
            raise ValueError(
                f"Inventory {vdir!r} is missing entries present in the root inventory: {sorted_missing}"
            )

        # Record any differing digests
        for key, root_digest in root_inventory.items():
            if key not in inventory:
                continue  # missing key is already reported
            current_digest = inventory[key]
            if current_digest != root_digest:
                self.different_digests.setdefault(key, []).append(
                    (root_inventory.get(key), inventory.get(key), root_inventory.get(key) != inventory.get(key))
                )

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Determine the root inventory file.  The attribute name may vary in
    # different implementations; we fall back to ``inventory_file`` if necessary.
    root_inventory_file = getattr(self, 'root_inventory', None) or getattr(self, 'inventory_file', None)
    if not root_inventory_file or not os.path.isfile(root_inventory_file):
        raise ValueError('Root inventory file missing or not a regular file.')

    try:
        with open(root_inventory_file, 'r', encoding='utf-8') as f:
            root_inventory = json.load(f)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f'Failed to read root inventory: {exc}') from exc

    # Expect the root inventory to contain a mapping of file -> digest.
    root_digests = root_inventory.get('digests')
    if not isinstance(root_digests, dict):
        raise ValueError('Root inventory must contain a mapping of file digests.')

    # Keep track of mismatched digests encountered in version inventories.
    mismatched = {}

    for vd in version_dirs:
        inv_path = os.path.join(self.root_dir, vd, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise ValueError(f'Inventory missing for version directory {vd!r} (expected at {inv_path!r})')

        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                inv = json.load(f)
        except (OSError, json.JSONDecodeError) as exc:
            raise ValueError(f'Failed to read inventory for {vd!r}: {exc}') from exc

        inv_digests = inv.get('digests')
        if not isinstance(inv_digests, dict):
            raise ValueError(f'Inventory {inv_path!r} does not contain a valid digests mapping.')

        # Compare digests between the root and this version.
        for file_path, digest in inv_digests.items():
            root_digest = root_digests.get(file_path)
            if root_digest is None:
                continue  # skip unknown files that are not in the root inventory
            if digest != root_digest:
                mismatched.setdefault(file_path, []).append((vd, digest))

    # Store mismatches on the instance for later validation steps.
    self.content_digests_mismatch = mismatched
    return mismatched)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Assume self.root_inventory is a dict mapping id -> entry dict
    if not hasattr(self, "root_inventory"):
        raise AttributeError("Instance missing root_inventory attribute")

    root_inventory = self.root_inventory
    root_digests = {entry_id: entry.get("digest") for entry_id, entry in root_inventory.items()}

    cumulative_inventory = {}
    differing_digests = {}

    for idx, dir_name in enumerate(version_dirs, start=1):
        inv_path = os.path.join(dir_name, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file: {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inventory = json.load(fh)
        except Exception as exc:  # catch JSON errors, I/O errors
            raise ValueError(f"Cannot load inventory for version {idx} from {inv_path}: {exc}")

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory in {inv_path} must be a mapping")

        # Verify cumulative items
        for key, value in inventory.items():
            cumulative_inventory[key] = value

        # Each version's inventory SHOULD include all entries from previous versions.
        if set(cumulative_inventory.keys()) != set(inventory.keys()):
            # An inventory might include additional entries as the version evolves,
            # but it must at least contain all keys that were present up to this point.
            missing = set(inventory.keys()) - set(cumulative_inventory.keys())
            if missing:
                raise ValueError(
                    f"Inventory in {inv_path} missing keys from previous version(s): {missing}"
                )

        # Track any digest that differs from the root inventory
        for key, entry in inventory.items():
            root_digest = root_digests.get(key)
            current_digest = entry.get("digest")
            if root_digest is not None and current_digest != root_digest:
                differing_digests.setdefault(key, []).append(current_digest)

    # Store results on self for later use
    self.differing_digests = differing_digests
    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.
    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content."""
    import os, json

    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    root_inventory = {}
    previous_inventory = {}
    differences = {}

    for idx, dir_name in enumerate(version_dirs, start=1):
        if not isinstance(dir_name, str):
            raise ValueError(f"Directory name at position {idx} is not a string: {dir_name}")

        inventory_path = os.path.join(dir_name, "inventory.json")
        try:
            with open(inventory_path, "r", encoding="utf-8") as fp:
                inv = json.load(fp)
        except FileNotFoundError:
            raise ValueError(f"Missing inventory file in '{dir_name}'. Expected '{inventory_path}'.")
        except json.JSONDecodeError as e:
            raise ValueError(f"Inventory in '{dir_name}' is not valid JSON: {e}")
        except Exception as e:
            raise ValueError(f"Error reading inventory from '{dir_name}': {e}")

        # An inventory must be a mapping from file path to digest
        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in '{dir_name}' must be a JSON object mapping paths to digests")

        # Ensure the current inventory contains all entries seen in previous versions
        if prev_entries := set(previous_inventory) - set(inv):
            raise ValueError(
                f"Inventory in '{dir_name}' is missing entries from previous versions: {sorted(prev_entries)}"
            )

        # Record differences from the root inventory
        if idx == 1:
            root_inventory = inv
        else:
            diff = {
                path: inv[path]
                for path in inv
                if root_inventory.get(path) != inv[path]
            }
            if diff:
                differences[dir_name] = diff

        previous_inventory = inv

    # Store differences on the instance for later use
    self._inventory_differences = differences
    return differences

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        import re
    except Exception as exc:
        return f'internal error: {exc}'

    if not isinstance(path, str):
        return f'path must be a string, got {type(path).__name__}'

    if not os.path.exists(path):
        return f'path does not exist: {path}'

    if os.path.isfile(path):
        return 'file'

    if not os.path.isdir(path):
        return f'unsupported path type: {path}'

    try:
        entries = os.listdir(path)
    except Exception as exc:
        return f'cannot list directory {path}: {exc}'

    # look for Namaste files that start with '0='
    namaste_files = [e for e in entries if re.match(r'^0=.*', e)]
    if namaste_files:
        return 'object'

    # if directory contains subdirectories, treat as a storage root
    if any(os.path.isdir(os.path.join(path, d)) for d in entries):
        return 'root'

    # empty directory or only files not matching '0='
    if entries:
        return f'unknown dir content, entries={entries}'
    return f'empty directory: {path}'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import fnmatch

    try:
        if not os.path.lexists(path):
            return f"path does not exist: {path}"
        if os.path.isfile(path):
            return 'file'

        try:
            names = os.listdir(path)
        except OSError as exc:
            return f"cannot list directory: {exc}"

        namaste_files = [n for n in names if n.startswith("0=")]
        if not namaste_files:
            return f"no Namaste file in directory: {path}"

        # An OCFL object directory contains an inventory file
        if 'inventory' in names or any(fnmatch.fnmatch(n, '*inventory.json') for n in names):
            return 'object'
        return 'root'
    except Exception as exc:
        return f"error determining type: {exc}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f"error: path does not exist"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # Find potential Namaste files that start with "0="
            namaste_files = [
                f for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f)) and f.startswith("0=")
            ]

            if not namaste_files:
                return "error: no Namaste file found"

            # If more than one, the type is ambiguous
            if len(namaste_files) > 1:
                return f"error: multiple Namaste files ({len(namaste_files)}) found"

            # Single Namaste file found
            # Try to distinguish root from object by examining the presence of subdirs
            subdirs = [
                name for name in os.listdir(path)
                if os.path.isdir(os.path.join(path, name))
            ]

            # If there are subdirectories whose names are strictly numeric
            # (typical for object version directories), consider it an object.
            if subdirs and all(d.isdigit() for d in subdirs):
                return "object"

            # Otherwise, default to root
            return "root"

        return "error: unknown path type"

    except OSError as exc:
        return f"error: {exc}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Normalize bug_ids to a list
    if isinstance(bug_ids, (list, tuple, set)):
        to_add = list(bug_ids)
    else:
        to_add = [bug_ids]
    # Merge into the 'ids' key
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, (list, tuple)):
            existing_list = list(existing)
        else:
            existing_list = [existing]
        existing_list.extend(to_add)
        params["ids"] = existing_list
    else:
        params["ids"] = to_add
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple, set)):
        # If bug_ids is a single value, wrap it
        bug_ids = [bug_ids]
    # Build ids string
    ids_str = ','.join(str(bid) for bid in bug_ids)
    # If 'ids' already present merge them
    existing = params.get('ids')
    if existing:
        # Handle existing ids being list or string
        if isinstance(existing, str):
            existing_ids = set(existing.split(','))
        else:
            existing_ids = set(existing)
        merged = sorted(existing_ids.union(ids_str.split(',')), key=str)
        params['ids'] = ','.join(merged)
    else:
        params['ids'] = ids_str
    return params

def amend_bzparams(self, params, bug_ids):
    """
    Amend the Bugzilla params
    """
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")
    # Accept a single id as int or str as well as iterables
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    if not hasattr(bug_ids, "__iter__"):
        raise ValueError("bug_ids must be an iterable of ids")
    ids = []
    for bid in bug_ids:
        if bid is None:
            continue
        if not isinstance(bid, (int, str)):
            raise ValueError(f"bug_ids contains an unsupported type: {type(bid)}")
        ids.append(str(bid))
    if not ids:
        return params
    amended = dict(params)
    amended['id'] = ','.join(ids)
    return amended

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:
        [...]
    '''
    # Helper to merge two MappingNode values recursively
    def _merge_mapping_nodes(mn1, mn2):
        # Use the tag from the first mapping node; assume both have same tag
        if not hasattr(mn1, 'tag') or not hasattr(mn1, 'value') or not hasattr(mn2, 'tag') or not hasattr(mn2, 'value'):
            # If either is not a proper MappingNode, fall back to the second one
            return mn2
        merged_dict = {}
        # Insert items from the first mapping
        for key_node, val_node in mn1.value:
            merged_dict[key_node.value] = (key_node, val_node)
        # Merge items from the second mapping
        for key_node, val_node in mn2.value:
            k_val = key_node.value
            if k_val in merged_dict:
                existing_key_node, existing_val_node = merged_dict[k_val]
                if isinstance(existing_val_node, type(mn1)) and isinstance(val_node, type(mn2)):
                    merged = _merge_mapping_nodes(existing_val_node, val_node)
                    merged_dict[k_val] = (existing_key_node, merged)
                else:
                    # On conflict, last value wins
