                merged_entries[k_str] = (k_node, v_node)
            for k_node, v_node in val2.value:
                k_str = k_node.value
                if k_str in merged_entries:
                    _, existing_v = merged_entries[k_str]
                    merged_inner = merge_values(existing_v, v_node)
                    merged_entries[k_str] = (merged_entries[k_str][0], merged_inner)
                else:
                    merged_entries[k_str] = (k_node, v_node)
            # Reconstruct the list keeping original ordering
            rebuilt = []
            seen = set()
            for k_node, v_node in val1.value:
                k_str = k_node.value
                rebuilt.append(merged_entries[k_str])
                seen.add(k_str)
            for k_node, v_node in val2.value:
                k_str = k_node.value
                if k_str not in seen:
                    rebuilt.append(merged_entries[k_str])
            return type(val1)(tag=val1.tag, value=rebuilt)
        # Non‑mapping: last value wins
        return val2

    result = {}
    for key_node, val_node in nodes:
        if not hasattr(key_node, 'value'):
            raise TypeError(f'Key node {key_node!r} lacks .value attribute')
        key_str = key_node.value
        if key_str in result:
            existing_key, existing_val = result[key_str]
            merged_val = merge_values(existing_val, val_node)
            result[key_str] = (existing_key, merged_val)
        else:
            result[key_str] = (key_node, val_node)

    return list(result.values())

