    {'a': 6, 'b': 2}
    """
    from collections import Counter

    if dicts is None:
        raise TypeError("Expected an iterable of dictionaries, got None")

    try:
        counters = [Counter(d) for d in dicts]
    except TypeError as e:
        # Raised when an element in dicts is not iterable or when dicts itself is not iterable
        raise TypeError("All elements in the iterable must be dictionaries") from e
    except Exception as e:
