    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::
        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        if not isinstance(vertices, list):
            raise TypeError("vertices must be a list")
        n = len(vertices)
        if n == 0:
            return []
        res = []
        for i in range(n):
            prev = vertices[i - 1] if i != 0 else vertices[-1]
            curr = vertices[i]
            nxt = vertices[(i + 1) % n]
            res.append((prev, curr, nxt))
        return res
    except Exception as e:
        raise ValueError(f"Error computing vertex triples: {e}")

def vertex3tuple(vertices):
    '''return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    '''
    try:
        n = len(vertices)
    except Exception:
        raise ValueError("vertices must be an iterable with a defined length")
    if n == 0:
        return []
    result = []
    for i in range(n):
        try:
            prev = vertices[i - 1]
            curr = vertices[i]
            nxt = vertices[(i + 1) % n]
        except Exception as exc:
            raise ValueError(f"Error processing vertices at index {i}: {exc}") from exc
        result.append((prev, curr, nxt))
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic type checks
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols")
    if any(not isinstance(ch, str) for ch in alphabet):
        raise TypeError("alphabet elements must be strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet elements must be unique")

    # Validate number
    if number < 0:
        raise ValueError("number must be non‑negative")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()
        result = ''.join(digits)

    # Handle padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non‑negative integer or None")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Input validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("alphabet must be a non-empty list")
    if any(not isinstance(ch, str) or len(ch) != 1 for ch in alphabet):
        raise ValueError("alphabet elements must be single-character strings")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an integer or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    if base == 0:
        raise ValueError("alphabet must contain at least one digit")

    # Convert number to digits in given base
    if number == 0:
        digits = [alphabet[0]]
    else:
        if base == 1:
            # Unary representation: repeat the single character
            digits = [alphabet[0]] * number
        else:
            digits = []
            n = number
            while n:
                n, rem = divmod(n, base)
                digits.append(alphabet[rem])
            digits.reverse()

    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
