            raise ValueError("Padding must be non-negative.")

    # Perform conversion
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])

    # Build string (most significant digit first)
    result = ''.join(reversed(digits))

