def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate input
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list of characters")
    # Ensure all alphabet entries are single character strings
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"alphabet element at index {idx} is not a single character string: {ch!r}")

    base = len(alphabet)
    result_digits = []

    # Special case for zero
    if number == 0:
        result_digits.append(alphabet[0])
    else:
        n = number
        while n:
            n, rem = divmod(n, base)
            result_digits.append(alphabet[rem])

    # Most significant digit first
    result_str = ''.join(reversed(result_digits))

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        if len(result_str) < padding:
            pad_char = alphabet[0]
            result_str = pad_char * (padding - len(result_str)) + result_str

    return result_str

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dict")

    # Ensure register_number is a string key if flow_params keys are strings
    if isinstance(register_number, int):
        register_number = str(register_number)

    def _recurse(obj):
        if isinstance(obj, dict):
            # collect keys to replace to avoid RuntimeError during iteration
            keys_to_replace = [k for k in obj if k == register_value]
            for old_key in keys_to_replace:
                obj[register_number] = obj.pop(old_key)
            for value in obj.values():
                _recurse(value)
        elif isinstance(obj, list):
            for item in obj:
                _recurse(item)
        # other types are ignored

    try:
        _recurse(flow_params)
    except Exception as exc:
        raise RuntimeError(f"Failed to replace register '{register_value}' with '{register_number}': {exc}") from exc

    return flow_params

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

