    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key")

    for flow_name, flow_obj in flow_params.items():
        # Only modify mappings that are dicts
        if isinstance(flow_obj, dict):
            if register_value in flow_obj:
                flow_obj[register_number] = flow_obj.pop(register_value)
