def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    if not isinstance(register_number, (int, float)):
        raise TypeError("register_number must be a numeric value")

    # Helper to replace value in a mapping
    def _replace_in_mapping(mapping):
        if register_value in mapping:
            mapping[register_value] = register_number

    # Iterate over all entries in flow_params
    for item in flow_params.values():
        try:
            if isinstance(item, dict):
                _replace_in_mapping(item)
            elif isinstance(item, (list, tuple)):
                for elem in item:
                    if isinstance(elem, dict):
                        _replace_in_mapping(elem)
            # If there are nested dicts within dict values, handle them recursively
            if isinstance(item, dict):
                for sub in item.values():
                    if isinstance(sub, dict):
                        _replace_in_mapping(sub)
        except Exception as e:
            # Skip problematic entries but log if needed
            pass

    return flow_params

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
