def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        for sub in getattr(current, "__subclasses__", lambda: [])():
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    seen.discard(cls)
    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Argument {cls!r} is not a class")
    seen = set()
    queue = [cls]
    while queue:
        current = queue.pop()
        if current in seen:
            continue
        seen.add(current)
        try:
            direct_subs = current.__subclasses__()
        except Exception:
            continue
        for sub in direct_subs:
            if sub not in seen:
                queue.append(sub)
    seen.discard(cls)
    return {c for c in seen if isinstance(c, type)}

