def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    try:
        seen = set()
        queue = [cls]
        while queue:
            c = queue.pop()
            if c in seen:
                continue
            seen.add(c)
            queue.extend(c.__subclasses__())
        seen.discard(cls)
        return seen
    except Exception:
        return set()

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two characters.")
    # Build a mapping from character to its positional value
    digit_map = {char: idx for idx, char in enumerate(alphabet)}
    number = 0
    for char in string:
        if char not in digit_map:
            raise ValueError(f"Character {char!r} not in alphabet.")
        number = number * base + digit_map[char]
    return number

