        raise ValueError("alphabet must contain at least two distinct characters")

    # ensure all alphabet entries are unique
    if len(set(alphabet)) != base:
        raise ValueError("alphabet must contain unique characters")

    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    if string == "":
        # Empty string can be considered as zero
        return 0

    result = 0
    for idx, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' at position {idx} not found in alphabet")
