    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise OSError(f"Failed to create destination directory '{destination_path}': {e}") from e

    tmp_name = None
    try:
        with requests.get(url, stream=True) as response:
            response.raise_for_status()
            import tempfile
            with tempfile.NamedTemporaryFile(suffix=".tar.gz", delete=False) as tmp_file:
                tmp_name = tmp_file.name
                for chunk in response.iter_content(chunk_size=65536):
                    if chunk:
                        tmp_file.write(chunk)

        import tarfile
        with tarfile.open(tmp_name, mode="r:gz") as tar:
            tar.extractall(path=str(destination_path))
    except Exception as e:
        raise RuntimeError(f"Failed to download or extract archive from {url}: {e}") from e
    finally:
        if tmp_name and os.path.isfile(tmp_name):
            try:
                os.remove(tmp_name)
            except Exception:
                pass

    return destination_path.resolve()

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except Exception:
        return False

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        # On POSIX systems, os.uname() provides the system name.
        return os.uname().sysname.lower() == 'darwin'
    except AttributeError:
        # os.uname() is not available (e.g., on Windows). Fallback to platform system.
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False
    except Exception:
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.
    """
    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")
    regexed = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise TypeError("Dictionary keys must be strings")
        try:
            # Escape regex meta-characters except for glob wildcards
            pattern = re.escape(key)
            # Replace glob wildcards with regex equivalents
            pattern = pattern.replace(r'\*', '.*').replace(r'\?', '.')
            # Anchor pattern to match whole string
            pattern = '^' + pattern + '$'
            regexed[pattern] = value
        except re.error as exc:
            raise ValueError(f"Invalid regex conversion for key '{key}': {exc}") from exc
    return regexed

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError(f"Expected a dict, got {type(item).__name__}")
    result = {}
    for k, v in item.items():
        if isinstance(k, str):
            # Convert wildcard pattern to regex, anchoring to start and end
            pattern = ''.join('.*' if ch == '*' else '.' if ch == '?' else re.escape(ch) for ch in k)
            pattern = f'^{pattern}$'
        else:
            pattern = k  # leave non-string keys unchanged
        result[pattern] = v
    return result

def unquote(name):
    """Remove quote from the given name."""
    if name is None:
        return None
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    # Unescape common escaped quote sequences
    cleaned = name.replace('\\"', '"').replace("\\'", "'").replace('\\\\\\', '\\')
    # Remove surrounding matching quotes if present
    if len(cleaned) >= 2 and cleaned[0] == cleaned[-1] and cleaned[0] in ('"', "'", '<', '>'):
        return cleaned[1:-1]
    return cleaned

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    try:
        # Remove matching leading and trailing quotes
        if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'", "`"):
            return name[1:-1]
        # Fallback to regex if needed
        return re.sub(r'^([\'"`])(.*)\1$', r'\2', name)
    except Exception:
        return name

