        if len(name) > 1:
            if name.startswith('"') and name.endswith('"'):
                return name[1:-1].replace('\\"', '"').replace('\\\\', '\\')
            if name.startswith("'") and name.endswith("'"):
                return name[1:-1].replace("\\'", "'").replace('\\\\', '\\')
            if name.startswith('<') and name.endswith('>'):
                return name[1:-1]
        return name
    except Exception:
        return name

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    return re.sub(r'^["\']|["\']$', '', name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os, sys

    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1
    if not isinstance(s, (str, bytes)):
        raise TypeError(f's must be a string, not {type(s).__name__}')
    if isinstance(s, bytes):
        try:
            s = s.decode(sys.getdefaultencoding())
        except Exception as exc:
            raise ValueError('Cannot decode bytes input') from exc

    if platform == 1:
        # Simplified POSIX split
        if not s:
            return []

        token_re = re.compile(r'''
            (?:                 # start token
                "(?:[^"\\]|\\.)*"   # quoted double
                |'(?:[^'\\]|\\.)*'   # quoted single
                |[^ \t\r\n]+        # unquoted
            )
            ''', re.VERBOSE)
        parts = []
        for match in token_re.finditer(s):
            token = match.group(0)
            if token[0] in ('"', "'"):
                # strip quotes and unescape
                token = token[1:-1]
                token = re.sub(r'\\(.)', r'\1', token)
            parts.append(token)
        return parts

    elif platform == 0:
        # Simplified Windows CMD split
        if not s:
            return []

        win_re = re.compile(r'''
            (?:                           # token
                "(?:[^"\\]|\\.)*"         # quoted
                |[^ \t]+                  # unquoted
            )
            ''', re.VERBOSE)
        parts = []
        for match in win_re.finditer(s):
            token = match.group(0)
            if token[0] == '"':
                # remove surrounding quotes
                token = token[1:-1]
                # unescape \\
                token = re.sub(r'\\(.)', r'\1', token)
            parts.append(token)
        return parts

    else:
        raise ValueError(f'Unsupported platform value: {platform}')

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, shlex, re
    # Resolve platform if auto
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    # POSIX mode
    if platform == 1:
        try:
            return shlex.split(s)
        except Exception as exc:
            # Fallback to simple split on whitespace if shlex fails
            return s.split()
    # Windows CMD mode
    elif platform == 0:
        # Regex to match quoted segments or unquoted words
        pattern = re.compile(r'''
            (?:^|\s)                     # leading whitespace
            (?:
                "([^"]*)"                # double quoted string
              | '([^']*)'                # single quoted string
              | ([^\s]+)                 # unquoted string
            )
        ''', re.VERBOSE)
        parts = []
        for match in pattern.finditer(s):
            # One of the groups will be non-None
            part = match.group(1) or match.group(2) or match.group(3)
            if part is not None:
                parts.append(part)
        # If pattern found no matches because string is empty or only whitespace
        if not parts and s.strip() == '':
            return []
        # Fallback: if we captured nothing, return the original string split by spaces
        if not parts:
            return s.split()
        return parts
    else:
        # Unsupported mode value – raise informative error
        raise ValueError(f"Unsupported platform value: {platform}")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    import os

    if platform == 'this':
        posix = os.name != 'nt'
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError(f"Unsupported platform value: {platform}")

    try:
        return shlex.split(s, posix=posix)
    except Exception as err:
        raise RuntimeError(f"Failed to split command line '{s}': {err}") from err

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import tarfile
    import zipfile
    from pathlib import Path
    from tempfile import mkdtemp

    # Resolve paths
    archive = Path(archive_path).expanduser().resolve()
    if not archive.is_file():
        raise FileNotFoundError(f"Archive path does not exist: {archive}")

    base_dir = Path(tmp_path).expanduser().resolve()
    if not base_dir.is_dir():
        raise NotADirectoryError(f"tmp_path is not a directory: {base_dir}")

    # Determine extraction directory name
    if filename:
        extract_dir_name = Path(filename).name
    else:
        # Use the archive name without extension(s)
        extract_dir_name = archive.stem
    # Ensure unique extraction directory inside tmp_path
    extraction_path = base_dir / extract_dir_name
    counter = 0
    while extraction_path.exists():
        counter += 1
        extraction_path = base_dir / f"{extract_dir_name}_{counter}"
    extraction_path.mkdir(parents=True, exist_ok=False)

    try:
        if archive.suffixes[-1] in {".gz", ".bz2", ".xz"}:
            mode = None
            for ext_suffix in archive.suffixes:
                if ext_suffix == ".tar":
                    mode = "r|*"
                elif ext_suffix == ".gz":
                    mode = "r:gz"
                elif ext_suffix == ".bz2":
                    mode = "r:bz2"
                elif ext_suffix == ".xz":
                    mode = "r:xz"
            if mode is None:
                mode = "r:*"
            with tarfile.open(archive, mode) as tar:
                tar.extractall(path=extraction_path)
        elif archive.suffix.lower() == ".zip":
            with zipfile.ZipFile(archive, "r") as zf:
                zf.extractall(path=extraction_path)
        else:
            # Attempt generic tar extraction with pattern matching
            try:
                with tarfile.open(archive, "r:*") as tar:
                    tar.extractall(path=extraction_path)
            except tarfile.TarError:
                raise ValueError(
                    f"Unsupported archive format for file: {archive}"
                )
    except Exception as exc:
        # Cleanup if extraction failed
        shutil.rmtree(extraction_path, ignore_errors=True)
        raise RuntimeError(
            f"Failed to extract archive '{archive}': {exc}"
        ) from exc

    # Return a file URL suitable as a git origin
    repo_url = f"file://{extraction_path.resolve()}"
    return repo_url

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Resolve the temporary extraction directory
    tmp_root = str(tmp_path)
    if filename is None:
        name = archive_path
        for suffix in ('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.zip'):
            if name.endswith(suffix):
                name = name[: -len(suffix)]
                break
        filename = os.path.basename(name)
    tmp_repo_dir = os.path.join(tmp_root, filename)

    try:
        # Ensure the destination directory exists
        os.makedirs(tmp_repo_dir, exist_ok=True)

        # Determine extraction command based on archive type
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            cmd = ['tar', '-xzf', archive_path, '-C', tmp_repo_dir]
        elif archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2'):
            cmd = ['tar', '-xjf', archive_path, '-C', tmp_repo_dir]
        elif archive_path.endswith('.zip'):
            cmd = ['unzip', '-o', archive_path, '-d', tmp_repo_dir]
        else:
            raise ValueError(f"Unsupported archive type for {archive_path}")

        subprocess.check_call(cmd)

    except FileNotFoundError as exc:
        raise RuntimeError(f"Extraction tool not found: {exc}") from exc
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Failed to extract archive {archive_path}: {exc}") from exc
    except OSError as exc:
        raise RuntimeError(f"Filesystem error while preparing repository: {exc}") from exc

    # Construct a file-based repository URL
    abs_path = os.path.abspath(tmp_repo_dir)
    return f'file://{abs_path}'

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '-i', '--exclude-standard', '-z'],
            capture_output=True,
            text=True,
            check=True
        )
        output = result.stdout
    except subprocess.CalledProcessError:
        return ''
    # Split by null separator to handle filenames with spaces/newlines
    files = [f for f in output.split('\0') if f]
    files.sort()
    return ','.join(files)

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            cwd=ignored,
            text=True,
            stderr=subprocess.STDOUT
        )
    except (subprocess.CalledProcessError, FileNotFoundError) as e:
        # If git is not found or the command fails, return an empty string
        return ''
    # Split into non-empty lines and sort
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Return None for None or “always” (case‑insensitive)
    if frequency is None:
        return None
    if isinstance(frequency, str):
        trimmed = frequency.strip().lower()
        if trimmed == 'always':
            return None
        # Split into number and unit
        parts = trimmed.split()
        if len(parts) != 2:
            raise ValueError(f'Cannot parse frequency: {frequency!r}')
        num_str, unit = parts
        # Parse the numeric part
        try:
            value = int(num_str)
        except ValueError:
            try:
                value = float(num_str)
            except ValueError:
                raise ValueError(f'Invalid number in frequency: {num_str!r}')
        # Map units to timedelta keyword arguments
        unit_map = {
            'second': 'seconds', 'seconds': 'seconds',
            'minute': 'minutes', 'minutes': 'minutes',
            'hour': 'hours', 'hours': 'hours',
            'day': 'days', 'days': 'days',
            'week': 'weeks', 'weeks': 'weeks',
        }
        if unit not in unit_map:
            raise ValueError(f'Unsupported unit in frequency: {unit!r}')
        kwargs = {unit_map[unit]: value}
        return datetime.timedelta(**kwargs)
    # If frequency is neither None, string, or “always”, raise an error
    raise ValueError(f'frequency must be a string, None, or "always" – got {type(frequency).__name__}')

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    # Handle empty or special cases
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip()
        if freq_str.lower() == 'always':
            return None
    else:
        raise ValueError('Frequency must be a string, None, or the literal "always".')

    if not isinstance(freq_str, str):
        raise ValueError('Frequency must be a string.')
    if freq_str == '':
        raise ValueError('Frequency string is empty.')

    # Extract leading integer (allow negative if needed)
    num_part = ''
    idx = 0
    while idx < len(freq_str) and (freq_str[idx].isdigit() or (idx == 0 and freq_str[idx] == '-')):
        num_part += freq_str[idx]
        idx += 1

    if num_part == '' or num_part == '-':
        raise ValueError(f"Frequency '{frequency}' must start with an integer value.")

    try:
        value = int(num_part)
    except ValueError:
        raise ValueError(f"Could not convert '{num_part}' to an integer in frequency '{frequency}'.")

    unit_part = freq_str[idx:].strip().lower()
    if unit_part == '':
        raise ValueError(f"No time unit specified in frequency '{frequency}'.")

    # Normalize unit
    unit_map = {
        ('day', 'days', 'd'): 'days',
        ('hour', 'hours', 'h'): 'hours',
        ('minute', 'minutes', 'min', 'mins'): 'minutes',
        ('second', 'seconds', 's'): 'seconds',
        ('week', 'weeks', 'w'): 'weeks',
        ('month', 'months'): 'months',
        ('year', 'years'): 'years',
    }

    matched_key = None
    for keys, norm in unit_map.items():
        if unit_part in keys:
            matched_key = norm
            break

    if matched_key is None:
        raise ValueError(f"Unsupported time unit '{unit_part}' in frequency '{frequency}'.")

    if matched_key == 'months':
        # Approximate a month as 30 days
        kwargs = {'days': value * 30}
    elif matched_key == 'years':
        # Approximate a year as 365 days
        kwargs = {'days': value * 365}
    else:
        kwargs = {matched_key: value}

    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.lower() == 'always':
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency)}")

    import re
    m = re.fullmatch(r'\s*(\d+)\s*([a-zA-Z_]+)\s*', frequency)
    if not m:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    amount = int(m.group(1))
    unit = m.group(2).lower()

    _unit_map = {
        'day': 'days', 'days': 'days',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'week': 'weeks', 'weeks': 'weeks',
        # common abbreviations
        'w': 'weeks', 'h': 'hours', 'm': 'minutes', 's': 'seconds',
    }

    if unit not in _unit_map:
        raise ValueError(f"Unsupported time unit in frequency: {unit!r}")

    kwargs = { _unit_map[unit]: amount }
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        addr_info = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in addr_info:
        address = sockaddr[0]
        if family == socket.AF_INET:
            if address.startswith("127.") and address != "0.0.0.0":
                return True
        elif family == socket.AF_INET6:
            if address == "::1" or address == "0:0:0:0:0:0:0:1":
                return True
            if address.startswith("::ffff:127."):
                return True
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        if not host:
            return False

        host_lower = host.lower()
        if host_lower in ('localhost', '127.0.0.1', '::1'):
            return True

        for info in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = info
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == '::1':
                    return True
        return False
    except (socket.gaierror, socket.error):
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for info in infos:
        addr = info[4][0]
        # Check IPv4 loopback
        try:
            packed = socket.inet_aton(addr)
            if packed[0] == 127:
                return True
        except OSError:
            # Not IPv4, try IPv6
            try:
                packed6 = socket.inet_pton(socket.AF_INET6, addr)
                # IPv6 loopback can be represented as "::1" or 0:0:0:0:0:0:0:1
                if addr == '::1' or packed6 == b'\x00'*15 + b'\x01':
                    return True
            except OSError:
                continue
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        results = socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
    except (socket.gaierror, TypeError):
        # socket.gaierror if host cannot be resolved, TypeError if host is not a string/bytes
        return False

    for family, _, _, _, sockaddr in results:
        addr = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 localhost range 127.0.0.0/8
            if addr.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback ::1
            if addr == "::1":
                return True
    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # On Windows with Git Bash, the OSTYPE environment variable contains 'msys' or 'cygwin'.
        # The PATH typically contains 'mingw' and the bash executable is named 'git-bash.exe'.
        if os.name != 'nt':
            return False
        ostype = os.getenv('OSTYPE', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True
        path = os.getenv('PATH', '').lower()
        if 'mingw' in path and 'git-bash.exe' in path:
            return True
        return False
    except Exception:
        # If anything unexpected happens, conservatively return False
        return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Windows systems have os.name == 'nt'
        if os.name != 'nt':
            return False
        ostype = os.environ.get('OSTYPE', '')
        # Git Bash sets OSTYPE to something like 'msys' or 'cygwin'
        return ostype.lower().startswith('msys') or ostype.lower().startswith('cygwin')
    except Exception:
        # In case of any unexpected error, assume not gitbash
        return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Git Bash on Windows sets OSTYPE beginning with 'msys'
        if os.name != 'nt':
            return False
        ostype = os.getenv('OSTYPE', '')
        msystem = os.getenv('MSYSTEM', '')
        return bool(
            (ostype and ostype.lower().startswith('msys')) or
            (msystem and msystem.lower().startswith('mingw'))
        )
    except Exception:
        # If any environment lookup fails, conservatively return False
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    config_filename = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_filename):
        return
    config_dir = os.path.dirname(config_filename)
    if config_dir:
        try:
            os.makedirs(config_dir, exist_ok=True)
        except OSError as e:
            # If the directory cannot be created and it does not already exist, re-raise.
            if not os.path.isdir(config_dir):
                raise
    with open(config_filename, 'w', mode=mode) as f:
        f.write(rendered_config)

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    if not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")

    config_path = os.path.expanduser(config_filename)

    if os.path.isfile(config_path) and not overwrite:
        raise FileExistsError(f"File '{config_path}' already exists and overwrite is False")

    config_dir = os.path.dirname(config_path)
    if config_dir:
        os.makedirs(config_dir, exist_ok=True)

    try:
        with open(config_path, "w") as f:
            f.write(rendered_config)
    except OSError as e:
        raise OSError(f"Failed to write configuration to '{config_path}': {e}") from e

    try:
        os.chmod(config_path, mode)
    except OSError:
        # If we can't set permissions, ignore and proceed
        pass
    return config_path

