def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern

    :param pattern: string or compiled pattern
    :param strip: bool indicating whether to strip whitespace
    :return: compiled regex pattern
    """
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as exc:
            raise ValueError(f"Invalid regex pattern: {exc}") from exc
    return pattern

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # Return None unchanged
    if pattern is None:
        return None

    # If we have a string, optionally strip whitespace and compile
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as exc:
            raise ValueError(f"Invalid regex pattern: {exc}") from exc

    # Handle compiled regex objects (Python 3.7+ uses re.Pattern)
    PatternType = getattr(re, "Pattern", None)
    _pattern_type = getattr(re, "_pattern_type", None)
    if PatternType and isinstance(pattern, PatternType):
        return pattern
    if _pattern_type and isinstance(pattern, _pattern_type):
        return pattern

    # If object has a 'pattern' attribute that is a string, compile it
    if hasattr(pattern, "pattern") and isinstance(pattern.pattern, (str, bytes)):
        try:
            return re.compile(pattern.pattern)
        except re.error as exc:
            raise ValueError(f"Invalid regex pattern from object: {exc}") from exc

    raise TypeError(f"Unsupported pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if args is None:
        args = []
    # Helper to run a single command list
    def _run(cmd_list):
        if verbose:
            print("Running:", " ".join(map(str, cmd_list)))
        try:
            result = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                check=True,
                text=True,
            )
            return result
        except subprocess.CalledProcessError as exc:
            raise RuntimeError(
                f"Command '{' '.join(exc.cmd)}' failed with exit code {exc.returncode}"
            ) from exc
    # If commands is an iterable of commands, run them sequentially
    if isinstance(commands, (list, tuple)):
        results = []
        for cmd in commands:
            if isinstance(cmd, (list, tuple)):
                cmd_list = list(cmd) + list(args)
            else:
                cmd_list = [cmd] + list(args)
            results.append(_run(cmd_list))
        return results
    # Otherwise treat as a single command
    cmd_list = [commands] + list(args)
    return _run(cmd_list)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import shlex
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    output = []
    for cmd in commands:
        if isinstance(cmd, str):
            cmd_tokens = shlex.split(cmd)
        else:
            cmd_tokens = list(cmd)
        cmd_tokens.extend(args)
        if verbose:
            print("Running:", " ".join(cmd_tokens))
        stderr = subprocess.DEVNULL if hide_stderr else None
        try:
            result = subprocess.run(
                cmd_tokens,
                cwd=cwd,
                env=env,
                capture_output=True,
                text=True,
                stdout=subprocess.PIPE,
                stderr=stderr,
                check=True,
            )
            output.append(result.stdout)
        except subprocess.CalledProcessError as exc:
            msg = (
                f"Command '{' '.join(exc.cmd)}' failed "
                f"with exit code {exc.returncode}"
            )
            raise ProgramError(msg) from exc
    return output

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
