def run_command(commands, args=None, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalise command to a list of commands
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError(f"commands must be a string or a list/tuple, got {type(commands).__name__}")
    # Normalise args
    if args is None:
        args = [[] for _ in commands]
    elif isinstance(args, str):
        args = [args]
    elif isinstance(args, (list, tuple)):
        # If args is a list of strings but only one command, broadcast
        if all(isinstance(a, str) for a in args) and len(commands) == 1:
            args = [args]
    else:
        raise TypeError(f"args must be None, a string, or a list/tuple, got {type(args).__name__}")
    # Ensure args length matches commands length
    if len(args) != len(commands):
        if len(args) == 1 and len(commands) > 1:
            args = args * len(commands)
        else:
            raise ValueError("Length of commands and args must match")
    stdout_list = []
    for cmd, arg in zip(commands, args):
        if isinstance(arg, str):
            arg = [arg]
        if not isinstance(arg, (list, tuple)):
            raise TypeError(f"Each argument must be a string or a list/tuple of strings, got {type(arg).__name__}")
        full_cmd = [cmd] + list(arg)
        if verbose:
            print("Running command:", " ".join(full_cmd))
        try:
            stderr = subprocess.DEVNULL if hide_stderr else None
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                stdout=subprocess.PIPE,
                stderr=stderr,
                env=env,
                text=True,
                check=True
            )
            stdout_list.append(result.stdout)
        except subprocess.CalledProcessError as exc:
            msg = f"Command {full_cmd!r} failed with exit code {exc.returncode}"
            raise RuntimeError(msg) from exc
    # Return list of outputs if more than one command, otherwise single output
    return stdout_list if len(stdout_list) > 1 else stdout_list[0] if stdout_list else None

