def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """

    mean = 0.2
    sigma = 0.1
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input x must be convertible to a NumPy array.") from e
    factor = 1.0/(sigma*np.sqrt(2*np.pi))
    exponent = -0.5 * ((arr - mean)/sigma)**2
    return factor * np.exp(exponent)

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    # Ensure the input is a NumPy array
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input must be an array-like of numeric values.") from e

    mean = 0.2
    sigma = 0.1
    prefactor = 1.0 / (sigma * np.sqrt(2 * np.pi))
    return prefactor * np.exp(-((arr - mean) ** 2) / (2 * sigma ** 2))

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    x = np.asarray(x)
    return (1/(0.1 * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - 0.2) / 0.1) ** 2)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed
    configuration, and sequence of logging.LogRecord instances containing any parse errors.
    """
    parsed_configs = {}
    error_records = []
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as fd:
                raw = fd.read()
            # Try JSON
            cfg = None
            try:
                cfg = json.loads(raw)
            except Exception:
                try:
                    cfg = yaml.safe_load(raw)
                except Exception:
                    try:
                        cfg = toml.loads(raw)
                    except Exception:
                        # All parsers failed
                        record = logging.LogRecord(
                            name='load_configurations',
                            level=logging.ERROR,
                            pathname=fname,
                            lineno=0,
                            msg=f"Failed to parse configuration file: {fname}",
                            args=None,
                            exc_info=None
                        )
                        error_records.append(record)
                        continue
            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                cfg.update(overrides)
            # Resolve environment variables in string values
            if resolve_env:
                def _expand(obj):
                    if isinstance(obj, dict):
                        return {k: _expand(v) for k, v in obj.items()}
                    elif isinstance(obj, list):
                        return [_expand(v) for v in obj]
                    elif isinstance(obj, str):
                        return os.path.expandvars(obj)
                    else:
                        return obj
                cfg = _expand(cfg)
            parsed_configs[fname] = cfg
        except FileNotFoundError:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Configuration file not found: {fname}",
                args=None,
                exc_info=None
            )
            error_records.append(record)
        except Exception:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Error processing configuration file: {fname}",
                args=None,
                exc_info=None
            )
            error_records.append(record)
    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    configs = {}
    error_records = []

    # Helper to create an error LogRecord
    def _make_error_record(message, filename):
        return logging.makeRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=message,
            args=(),
            exc_info=None)

    # Helper to resolve environment variables in strings like "${VAR}"
    def _resolve_env(value):
        if isinstance(value, str):
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def replacer(match):
                return os.getenv(match.group(1), match.group(0))
            return pattern.sub(replacer, value)
        return value

    # Load parser modules lazily
    json = None
    yaml = None
    toml = None
    try:
        import json as _json
        json = _json
    except Exception:
        pass
    try:
        import yaml as _yaml
        yaml = _yaml
    except Exception:
        pass
    try:
        import toml as _toml
        toml = _toml
    except Exception:
        pass

    for filename in config_filenames:
        if not os.path.exists(filename):
            error_records.append(_make_error_record(f'Configuration file not found: {filename}', filename))
            continue
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            error_records.append(_make_error_record(f'Error reading {filename}: {exc}', filename))
            continue

        parsed = None
        # Try JSON
        if json:
            try:
                parsed = json.loads(content)
            except Exception as exc:
                pass
        # Try YAML
        if parsed is None and yaml:
            try:
                parsed = yaml.safe_load(content)
            except Exception as exc:
                pass
        # Try TOML
        if parsed is None and toml:
            try:
                parsed = toml.loads(content)
            except Exception as exc:
                pass

        if parsed is None:
            error_records.append(_make_error_record(f'Unable to parse configuration file: {filename}', filename))
            continue

        if not isinstance(parsed, dict):
            error_records.append(_make_error_record(f'Parsed configuration is not a dict: {filename}', filename))
            continue

        # Apply overrides
        if overrides:
            try:
                parsed.update(overrides)
            except Exception as exc:
                error_records.append(_make_error_record(f'Error applying overrides to {filename}: {exc}', filename))
                continue

        # Resolve environment variables if requested
        if resolve_env:
            def _recursively_resolve(obj):
                if isinstance(obj, dict):
                    return {k: _recursively_resolve(v) for k, v in obj.items()}
                elif isinstance(obj, list):
                    return [_recursively_resolve(v) for v in obj]
                else:
                    return _resolve_env(obj)
            parsed = _recursively_resolve(parsed)

        configs[filename] = parsed

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    records = []

    def _resolve_env_vars(obj):
        import re
        if isinstance(obj, dict):
            return {k: _resolve_env_vars(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env_vars(v) for v in obj]
        if isinstance(obj, str):
            pattern = re.compile(r'\${([^}]+)}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, obj)
        return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
            ext = os.path.splitext(filename)[1].lower()
            if ext == '.json':
                import json
                parsed = json.loads(raw)
            elif ext in ('.yaml', '.yml'):
                import yaml
                parsed = yaml.safe_load(raw)
            elif ext == '.toml':
                import toml
                parsed = toml.loads(raw)
            else:
                # default to JSON
                import json
                parsed = json.loads(raw)
            if resolve_env:
                parsed = _resolve_env_vars(parsed)
            if overrides:
                parsed.update(overrides)
            configs[filename] = parsed
        except Exception as exc:
            record = logging.makeRecord(
                name='config_loader',
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=str(exc),
                args=(),
                exc_info=exc
            )
            records.append(record)
    return configs, records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    import traceback

    config_by_file = {}
    error_records = []

    def _expand_env(obj):
        """Recursively expand environment variables in strings within obj."""
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        if isinstance(obj, dict):
            return {k: _expand_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_expand_env(v) for v in obj]
        return obj

    for fname in config_filenames:
        try:
            if not os.path.isfile(fname):
                raise FileNotFoundError(f"File not found: {fname}")
            with open(fname, 'r', encoding='utf-8') as fd:
                content = fd.read()
            # Determine the format based on extension
            if fname.lower().endswith('.json'):
                parsed = json.loads(content)
            elif fname.lower().endswith(('.yaml', '.yml')):
                try:
                    import yaml
                except ImportError as e:
                    raise ImportError("yaml module not installed") from e
                parsed = yaml.safe_load(content)
            elif fname.lower().endswith('.toml'):
                try:
                    import toml
                except ImportError as e:
                    raise ImportError("toml module not installed") from e
                parsed = toml.loads(content)
            else:
                # Default to JSON or YAML if no extension; try JSON first
                try:
                    parsed = json.loads(content)
                except ValueError:
                    try:
                        import yaml
                        parsed = yaml.safe_load(content)
                    except Exception as exc:
                        raise ValueError(f"Unsupported configuration format for file {fname}") from exc
            if not isinstance(parsed, dict):
                raise ValueError(f"Configuration {fname} does not contain a dictionary")
            if overrides and isinstance(overrides, dict):
                parsed.update(overrides)
            if resolve_env:
                parsed = _expand_env(parsed)
            config_by_file[fname] = parsed
        except Exception as exc:
            exc_type, exc_value, exc_tb = type(exc), exc, traceback.extract_tb(exc.__traceback__)
            msg = f"Parsing error in '{fname}': {exc}"
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=msg,
                args=(),
                exc_info=(exc_type, exc_value, exc_tb)
            )
            error_records.append(record)

    return config_by_file, error_records

