def protocol_handlers(cls, protocol_version=None):
        """Return a dictionary of available Bolt protocol handlers.

        The dictionary is keyed by a version tuple.  If ``protocol_version`` is
        supplied and is supported, the dictionary will contain exactly that
        one entry; otherwise it will contain all supported entries.

        :param protocol_version: tuple identifying a specific protocol version
                                 (e.g. (3, 5)) or ``None``.
        :return: dictionary mapping version tuples to handler classes.
        :raise TypeError: if ``protocol_version`` is not ``None`` and not a tuple.
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple of (major, minor), got {type(protocol_version).__name__}"
            )

        # Expect a class attribute that holds all protocol handlers.
        # By convention we look for ``_protocol_handlers`` or ``protocol_handlers_dict``.
        registry = getattr(cls, "_protocol_handlers", None) or getattr(
            cls, "protocol_handlers_dict", None
        )
        if registry is None or not isinstance(registry, dict):
            # No handlers registered, return empty dict.
            return {}

        # Optionally filter out handlers that indicate they are not supported.
        # Many handlers will simply not set ``_supported``; in that case we
        # treat them as supported.  This allows the handler class to opt out
        # with an attribute ``_supported = False``.
        filtered = {
            ver: handler
            for ver, handler in registry.items()
            if getattr(handler, "_supported", True)
        }

        if protocol_version is None:
            return dict(filtered)

        # Return only the matched version, if it exists.
        return {protocol_version: filtered[protocol_version]} if protocol_version in filtered else {}

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the mapping of protocol versions to handler classes.
        # Subclasses may define their own mapping or override it.
        handlers = getattr(cls, "_PROTOCOL_HANDLERS", {})

        # Ensure handlers is a dictionary; if not, try to build one from
        # class attributes following a naming convention.
        if not isinstance(handlers, dict):
            handlers = {}
            for name, value in vars(cls).items():
                # Attempt to match attributes like ``PROTOCOL_3_5``.
                if name.upper().startswith("PROTOCOL_"):
                    try:
                        # Extract major and minor from the attribute name.
                        _, major, minor = name.split("_", 2)
                        major = int(major)
                        minor = int(minor)
                        handlers[(major, minor)] = value
                    except Exception:
                        # Ignore attributes that don't follow the convention.
                        continue

        # If a specific protocol version is requested, validate and filter.
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple) or len(protocol_version) != 2:
                raise TypeError(
                    "protocol_version must be a tuple of (major, minor)"
                )
            return (
                {protocol_version: handlers[protocol_version]}
                if protocol_version in handlers
                else {}
            )

        # No specific version requested; return all supported handlers.
        return dict(handlers)

