        if len(protocol_version) != 2:
            raise TypeError(
                f"protocol_version tuple must have 2 elements, got {len(protocol_version)}")

    # Discover all handler classes defined on the class
    handlers = {}
    for name, attr in vars(cls).items():
        # Consider only classes that define a protocol_version attribute
        if isinstance(attr, type) and hasattr(attr, "protocol_version"):
            ver = getattr(attr, "protocol_version")
            if isinstance(ver, tuple) and len(ver) == 2:
                handlers[ver] = attr

    # Filter if a specific protocol_version is requested
    if protocol_version is None:
        return handlers

    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}}

