def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    if seq is None:
        raise TypeError("seq must not be None")

    seq_type = type(seq)

    # If seq is already a list or tuple, use it as is
    if isinstance(seq, (list, tuple)):
        seq_seq = seq
    elif isinstance(seq, (str, bytes)):
        # strings and bytes are iterable but we want a list of characters
        seq_seq = list(seq)
    else:
        try:
            # Try to convert any other iterable to a list
            seq_seq = list(seq)
            # Note: the original type (e.g., generator) is preserved in seq_type
        except Exception as exc:
            raise TypeError(f"Provided sequence {seq!r} is not iterable") from exc

    if bufsize is not None:
        try:
            seq_seq = seq_seq[:bufsize]
        except Exception:
            # If seq_seq is not sliceable we ignore bufsize (unlikely with list)
            pass

    return seq_seq, seq_type

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Strings and bytes should not be treated as generic sequences
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # If we already have a list or tuple, just return it
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # Attempt to turn the given object into a list
    try:
        seq_list = list(seq)
    except Exception:
        # Not iterable – return the object as is
        return seq, type(seq)
    else:
        return seq_list, type(seq_list)  # type will be `list`

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    # If seq is a non-string iterable (e.g., list, tuple), treat it as a
    # sequence directly.
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        return (seq, type(seq))
    # For string or bytes, convert to a python string instance.
    if isinstance(seq, bytes):
        seq_str = seq.decode("utf-8")
    else:
        seq_str = str(seq)
    return (seq_str, type(seq_str))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    # If *seq* is already a list or tuple, use it directly.
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    # Strings, bytes, and bytearrays are already acceptable sequence types.
    if isinstance(seq, (str, bytes, bytearray)):
        return seq, type(seq)
    # For any other iterable, convert to a list.
    try:
        iter(seq)
    except TypeError:
        raise TypeError(f"Object {seq!r} is not iterable")
    # Convert the iterable to a list (use a buffer if given).
    if bufsize is None:
        seq_as_list = list(seq)
    else:
        seq_as_list = []
        it = iter(seq)
        try:
            while True:
                chunk = list()
                for _ in range(int(bufsize)):
                    chunk.append(next(it))
                seq_as_list.extend(chunk)
        except StopIteration:
            pass
    return seq_as_list, type(seq_as_list)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a concrete sequence type
    if isinstance(seq, (list, tuple, set, frozenset)):
        return seq, type(seq)

    # Strings and bytes are treated as atomic sequences
    if isinstance(seq, (str, bytes, bytearray)):
        return seq, type(seq)

    # File-like objects: read their content
    if hasattr(seq, "read"):
        try:
            data = seq.read(bufsize) if bufsize is not None else seq.read()
            return data, type(data)
        except Exception as exc:
            raise ValueError(f"Unable to read sequence from file-like object {seq}") from exc

    # Generic iterables that are not sequences
    if hasattr(seq, "__iter__"):
        try:
            data = list(seq)
            return data, type(data)
        except Exception:
            pass

    # Fallback: treat as a single element sequence
    return [seq], type(seq)

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Helper to fetch current scale
    def _get_current_scale():
        if not hasattr(self, "_scale"):
            raise ValueError("Graph scale is unknown.")
        current_scale = self._scale
        if current_scale == 0 or current_scale is None:
            raise ValueError("Graph scale is zero or undefined.")
        return current_scale

    # Getter
    if other is None:
        return _get_current_scale()

    # Setter
    try:
        target_scale = float(other)
    except Exception:
        raise TypeError("Provided scale must be numeric.")

    current_scale = _get_current_scale()

    # No change needed
    if current_scale == target_scale:
        return self

    # Determine scaling factor
    factor = target_scale / current_scale

    # Find the last coordinate field; assume self._fields holds ordered field names
    if not hasattr(self, "_fields"):
        raise AttributeError("Graph does not have field information.")
    if not self._fields:
        raise ValueError("No fields found to rescale.")
    last_field = self._fields[-1]

    # Rescale the field data
    if hasattr(self, last_field):
        field_data = getattr(self, last_field)
        try:
            if hasattr(field_data, "__array__"):
                # Ensure numpy array if available
                field_data = np.array(field_data, copy=False)
            setattr(self, last_field, field_data * factor)
        except Exception:
            # Fall back to simple multiplication if numpy not available
            setattr(self, last_field, field_data * factor)
    else:
        raise AttributeError(f"Field '{last_field}' not found in the graph object.")

    # Rescale associated errors if present
    if hasattr(self, "_errors") and isinstance(self._errors, dict):
        if last_field in self._errors:
            error_data = self._errors[last_field]
            try:
                if hasattr(error_data, "__array__"):
                    error_data = np.array(error_data, copy=False)
                self._errors[last_field] = error_data * factor
            except Exception:
                self._errors[last_field] = error_data * factor

    # Update the stored scale
    self._scale = target_scale
    return self

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get the current scale
    if other is None:
        return getattr(self, "scale", None)

    # Convert desired scale to a numeric value
    try:
        desired = float(other)
    except Exception as exc:
        raise TypeError("`other` must be a numeric value") from exc

    # Current scale must be known and non‑zero
    current = getattr(self, "scale", None)
    if current is None or current == 0:
        raise LenaValueError("Graph has unknown or zero scale; cannot rescale")

    # Compute scaling factor
    factor = desired / current

    # Rescale the last coordinate of each data field if possible
    if hasattr(self, "coordinates"):
        try:
            import numpy as np
            self.coordinates[:, -1] *= factor
        except Exception:
            # Fallback for non‑NumPy containers
            if isinstance(self.coordinates, (list, tuple)):
                for point in self.coordinates:
                    try:
                        point[-1] *= factor
                    except Exception:
                        pass
            else:
                # Try a generic element‑wise scaling
                try:
                    self.coordinates = self.coordinates * factor
                except Exception:
                    pass

    # Rescale any error fields that follow the same structure
    if hasattr(self, "errors"):
        try:
            import numpy as np
            self.errors[:, -1] *= factor
        except Exception:
            if isinstance(self.errors, (list, tuple)):
                for point in self.errors:
                    try:
                        point[-1] *= factor
                    except Exception:
                        pass
            else:
                try:
                    self.errors = self.errors * factor
                except Exception:
                    pass

    # Store the new scale value
    self.scale = desired
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    allowed_coords = {"left", "right", "middle"}
    if get_coordinate not in allowed_coords:
        raise ValueError(f"get_coordinate must be one of {allowed_coords}")

    # Determine histogram representation
    try:
        if hasattr(hist, "counts") and hasattr(hist, "bin_edges"):
            counts = hist.counts
            edges = hist.bin_edges
        elif isinstance(hist, dict) and "counts" in hist and "bin_edges" in hist:
            counts = hist["counts"]
            edges = hist["bin_edges"]
        elif isinstance(hist, tuple) and len(hist) == 2:
            counts, edges = hist
        else:
            raise TypeError("Unsupported histogram type")
    except Exception as exc:
        raise ValueError("Failed to extract histogram data") from exc

    if len(edges) - 1 != len(counts):
        raise ValueError("Number of edges must be one more than number of counts")

    # Default make_value function
    if make_value is None:
        make_value = lambda bin_: bin_

    # prepare graph points
    points = []
    for i, bin_content in enumerate(counts):
        left = edges[i]
        right = edges[i + 1]
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:  # middle
            coord = (left + right) / 2.0

        try:
            val = make_value(bin_content)
        except Exception as exc:
            raise ValueError(f"make_value failed for bin content {bin_content}") from exc

        # Ensure val is iterable if more than one field
        if isinstance(val, (list, tuple)):
            if len(val) != len(field_names) - 1:
                raise ValueError(
                    f"make_value returned {len(val)} values, "
                    f"expected {len(field_names) - 1}"
                )
            point = {field_names[0]: coord}
            for fn, v in zip(field_names[1:], val):
                point[fn] = v
        else:
            if len(field_names) != 2:
                raise ValueError(
                    f"make_value returned a single value but field_names has "
                    f"{len(field_names)} entries"
                )
            point = {field_names[0]: coord, field_names[1]: val}

        points.append(point)

    # Determine scale
    final_scale = scale
    if scale is True:
        # Try to use histogram's scale if available
        final_scale = getattr(hist, "scale", None)

    # Return a simple graph representation
    return {"points": points, "scale": final_scale}

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Interface provision check
    if not tentative:
        try:
            provides = iface.providedBy(candidate)
        except Exception as exc:
            provides = False
        if not provides:
            errors.append(
                f"{candidate!r} does not provide interface {iface!r}"
            )

    # 2. Check that candidate implements all required methods and attributes
    # Methods
    try:
        method_names = list(iface.getMethodNames())
    except Exception:
        method_names = []

    for name in method_names:
        if not hasattr(candidate, name):
            errors.append(
                f"Candidate {candidate!r} missing required method '{name}' of interface {iface!r}"
            )
            continue
        method = getattr(candidate, name)
        if not callable(method):
            errors.append(
                f"Attribute '{name}' of candidate {candidate!r} is not callable as required by interface {iface!r}"
            )
            continue
        # Signature comparison if possible
        iface_method = iface.__dict__.get(name)
        try:
            iface_sig = getattr(iface_method, "__signature__", None)
        except Exception:
            iface_sig = None
        try:
            cand_sig = inspect.signature(method)
        except Exception:
            cand_sig = None

        if iface_sig is not None and cand_sig is not None:
            # Compare parameter lists
            iface_params = list(iface_sig.parameters.values())
            cand_params = list(cand_sig.parameters.values())
            if len(iface_params) != len(cand_params):
                errors.append(
                    f"Method '{name}' in {candidate!r} has {len(cand_params)} parameters, expected {len(iface_params)} per interface {iface!r}"
                )
            else:
                # Compare parameter kinds and names
                for ip, cp in zip(iface_params, cand_params):
                    if ip.kind != cp.kind:
                        errors.append(
                            f"Method '{name}' in {candidate!r} has differing parameter kind for '{cp.name}' (expected {ip.kind.name}) in interface {iface!r}"
                        )
                    if ip.name != cp.name:
                        errors.append(
                            f"Method '{name}' in {candidate!r} parameter name '{cp.name}' does not match interface expectation '{ip.name}'"
                        )
    # Attributes
    try:
        attr_names = list(iface.getAttributeNames())
    except Exception:
        attr_names = []

    for name in attr_names:
        if not hasattr(candidate, name):
            errors.append(
                f"Candidate {candidate!r} missing required attribute '{name}' of interface {iface!r}"
            )

    # 3. Raise error(s) or return True
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Sanity checks for the provided arguments
    if iface is None or candidate is None:
        raise TypeError("Both 'iface' and 'candidate' must be provided")

    # Determine the class (or module) being checked
    # If candidate is a class, use it directly; otherwise use its type
    candidate_cls = candidate if isinstance(candidate, type) else getattr(candidate, "__class__", candidate)

    # Ensure iface is a class or a module-like object
    if not isinstance(iface, type) and not hasattr(iface, "__dict__"):
        raise TypeError("'iface' must be a class or provide a '__dict__' attribute")

    # Collect any missing or non-callable attributes that are required by iface
    missing = []
    for name, required in iface.__dict__.items():
        # Skip private and special attributes
        if name.startswith("_"):
            continue
        # If the interface has a descriptor or a function, we expect the candidate to provide it
        if callable(required):
            if not hasattr(candidate_cls, name):
                missing.append(name)
            else:
                provided = getattr(candidate_cls, name)
                if not callable(provided):
                    missing.append(name)
        else:
            # For non-callable attributes, we just check presence
            if not hasattr(candidate_cls, name):
                missing.append(name)

    if missing:
        msg = (
            f"Candidate {getattr(candidate_cls, '__name__', repr(candidate_cls))} "
            f"does not provide required members of interface {getattr(iface, '__name__', repr(iface))}: "
            f"{', '.join(missing)}"
        )
        if tentative:
            return False
        raise TypeError(msg)

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    try:
        # Basic sanity checks.
        if iface is None:
            raise ValueError("interface must not be None")
        if candidate is None:
            raise ValueError("candidate must not be None")

        # Gather the interface's public attributes/methods.
        # We ignore special attributes that start with "__".
        iface_attrs = [name for name in dir(iface) if not name.startswith('__')]

        # Check that each interface attribute exists on the candidate.
        for attr in iface_attrs:
            if not hasattr(candidate, attr):
                raise AttributeError(
                    f"Candidate missing attribute '{attr}' required by interface '{iface.__name__}'"
                )

            # If the interface attribute is a callable, ensure
            # the candidate attribute is also callable.
            iface_attr = getattr(iface, attr)
            cand_attr = getattr(candidate, attr)
            if callable(iface_attr) and not callable(cand_attr):
                raise TypeError(
                    f"Attribute '{attr}' should be callable for interface '{iface.__name__}'"
                )

        # If we reach this point, candidate passes the checks.
    except Exception as exc:
        if tentative:
            return False
        else:
            # Re-raise the exception to signal failure
            raise
    if tentative:
        return True
    # If not tentative, no explicit return is needed; success is implied.

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Build a set of required attribute names from the interface.
    required = set()

    # If the interface is given as an iterable of names, use those directly.
    if isinstance(iface, (list, tuple, set)):
        for name in iface:
            if isinstance(name, str) and name:
                required.add(name)

    # Otherwise, try to discover public attributes from a class or other object.
    else:
        # Include abstract methods if the interface is an ABC.
        try:
            abstract_methods = getattr(iface, "__abstractmethods__", set())
            required.update(abstract_methods)
        except Exception:
            pass

        # Include names defined in the interface's __dict__.
        try:
            for name, val in getattr(iface, "__dict__", {}).items():
                if not name.startswith("_"):
                    required.add(name)
        except Exception:
            pass

        # Fallback to dir() to capture other public members.
        try:
            for name in dir(iface):
                if not name.startswith("_"):
                    required.add(name)
        except Exception:
            pass

    # Determine which required attributes are missing from the candidate.
    missing = [name for name in required if not hasattr(candidate, name)]

    if tentative:
        return not missing
    else:
        if missing:
            missing_msg = ", ".join(missing)
            raise TypeError(
                f"Candidate {candidate!r} does not provide required interface {iface!r}. "
                f"Missing attributes: {missing_msg}"
            )
        return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Ensure bases is iterable
    try:
        base_list = list(bases)
    except Exception as exc:
        raise TypeError(f"bases must be an iterable of base classes, got {bases!r}") from exc

    # Default candidate metaclass
    candidate = type

    # Handle explicit metaclass first
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit __metaclass__ must be a type, got {explicit_mc!r}")
        candidate = explicit_mc

    # Process each base to find the most derived metaclass
    for b in base_list:
        # Attempt to obtain a metaclass; skip non-classes gracefully
        try:
            meta = type(b)
        except Exception:
            continue

        if not isinstance(meta, type):
            # In rare cases where meta is not a type, ignore
            continue

        # Resolve the most derived metaclass among candidate and meta
        if issubclass(meta, candidate):
            candidate = meta
        elif not issubclass(candidate, meta):
            raise TypeError(f"metaclass conflict: {meta.__name__} and {candidate.__name__}")

    return candidate

def determineMetaclass(bases, explicit_mc=None):
        """Determine metaclass from 1+ bases and optional explicit __metaclass__

        The rules implemented are a simplified version of CPython's metaclass
        resolution.  If ``explicit_mc`` is supplied it is returned after
        validating that it is a subclass of all base metaclasses.
        Otherwise the most derived common metaclass of the bases is found.
        If no bases are supplied the builtin ``type`` is returned.

        ``bases`` must be an iterable of classes.
        """
        # Validate bases iterable
        if bases is None:
            bases = []
        try:
            iter(bases)
        except TypeError as exc:
            raise TypeError("bases must be an iterable of classes") from exc

        # Convert to list to iterate multiple times
        bases_list = list(bases)

        # If explicit metaclass is given, use it after validation
        if explicit_mc is not None:
            if not isinstance(explicit_mc, type):
                raise TypeError("explicit __metaclass__ must be a class")
            # Validate compatibility with bases
            for base in bases_list:
                base_meta = type(base)
                if not issubclass(explicit_mc, base_meta):
                    raise TypeError(
                        "explicit __metaclass__ is not a subclass "
                        f"of the metaclass {base_meta.__name__!r} of base {base.__name__!r}"
                    )
            return explicit_mc

        # No explicit metaclass: compute from bases
        if not bases_list:
            return type

        # Start with the metaclass of the first base
        try:
            chosen = type(bases_list[0])
        except Exception as exc:
            raise TypeError("cannot determine metaclass of base") from exc

        for base in bases_list[1:]:
            try:
                m = type(base)
            except Exception as exc:
                raise TypeError("cannot determine metaclass of base") from exc

            if m is chosen:
                continue

            # What is the more derived metaclass?
            if issubclass(m, chosen):
                chosen = m
                continue
            if issubclass(chosen, m):
                continue

            # No direct subclass relationship – find first common ancestor
            common = None
            for cls in m.mro():
                if issubclass(cls, chosen):
                    common = cls
                    break
            if common is None:
                # Try the opposite direction
                for cls in chosen.mro():
                    if issubclass(cls, m):
                        common = cls
                        break
            if common is None:
                raise TypeError(
                    "metaclass conflict: cannot find a common metaclass for "
                    f"{[c.__name__ for c in bases_list]}"
                )
            chosen = common

        return chosen

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Helper to find a common metaclass that is a subclass of all given metaclasses
    def _find_common_metaclass(metaclasses):
        # Iterate over the MRO of the first metaclass to find a suitable common ancestor
        for candidate in metaclasses[0].mro():
            if all(issubclass(candidate, mc) for mc in metaclasses):
                return candidate
        # If no common ancestor is found, fall back to the default Python behaviour
        return type

    # If an explicit metaclass is provided, use it
    if explicit_mc is not None:
        # If the explicit metaclass is a tuple/list of metaclasses, resolve the common one
        if isinstance(explicit_mc, (tuple, list)):
            try:
                return _find_common_metaclass(list(explicit_mc))
            except Exception:
                # Fallback to first in list if resolution fails
                return explicit_mc[0]
        return explicit_mc

    # Gather metaclasses from each base. Skip bases that are not types.
    metaclasses = []
    for base in bases:
        try:
            mc = type(base)
            if isinstance(mc, type):
                metaclasses.append(mc)
        except Exception:
            # If the base is not a type, ignore for metaclass determination
            continue

    # If no bases provide a metaclass, default to 'type'
    if not metaclasses:
        return type

    # If all metaclasses are the same, return it
    first_mc = metaclasses[0]
    if all(mc is first_mc for mc in metaclasses):
        return first_mc

    # Attempt to find a common metaclass
    try:
        return _find_common_metaclass(metaclasses)
    except Exception:
        # As a last resort, return the default metaclass 'type'
        return type

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default
    for _map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap, self._pb.BoolMap]:
        if key in _map:
            return _map.pop(key)

