    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        # When no default is passed, raise KeyError
        if default is not __marker:
            return default
        raise KeyError(key)
    for map_obj in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                    self._pb.BoolMap]:
        if key in map_obj:
            return map_obj.pop(key)

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    if key in self:
        value = self[key]
        del self[key]
        return value
    if default is not __marker:
        return default
    raise KeyError(key)

