    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default
    # key exists, remove and return
    return super().pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Resolve the actual cache dictionary
    cache = getattr(self, "_cache", getattr(self, "cache", None))
    if cache is None:
        raise AttributeError("Cache attribute not found. Expected either '_cache' or 'cache'.")
    if not cache:
        raise KeyError("No items to pop; cache is empty")

    # Frequency tracking structures
    freq = getattr(self, "_freq", getattr(self, "freq", {}))
    freq_buckets = getattr(self, "_freq_buckets", getattr(self, "freq_buckets", {}))

    # Determine the minimum frequency present
    min_freq = getattr(self, "_minfreq", None)
    if min_freq is None:
        if freq:
            min_freq = min(freq.values())
        else:
            raise KeyError("No frequency data available; cache is empty")

    # Identify the key to remove
    bucket = freq_buckets.get(min_freq, {})
    if bucket:
        # Preserve insertion order: pop the first key
        key = next(iter(bucket))
    else:
        # Fallback: key with the smallest frequency count
        key = min(freq.items(), key=lambda kv: kv[1])[0]

    # Extract the value and update all structures
    value = cache.pop(key)
    freq.pop(key, None)
    if bucket:
        bucket.pop(key, None)
        if not bucket:
            freq_buckets.pop(min_freq, None)

    # Update the global minimum frequency if needed
    if freq:
        new_min = min(freq.values())
        setattr(self, "_minfreq", new_min)
    else:
        setattr(self, "_minfreq", None)

    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Retrieve the internal cache and frequency map if they exist
    cache = getattr(self, "_cache", None) or getattr(
        self, "cache", dict()
    ) or getattr(self, "_store", dict())
    freq_map = getattr(self, "_freq", dict())

    if not cache:
        # No items to pop
        raise KeyError("Cache is empty")

    # Find the key with the lowest frequency
    min_key = None
    min_freq = None
    for key, value in cache.items():
        key_freq = freq_map.get(key, 0)
        if min_freq is None or key_freq < min_freq:
            min_freq, min_key = key_freq, key
            if min_freq == 0:
                break  # can't get lower than zero

    if min_key is None:
        # This should never happen if cache is non-empty
        raise KeyError("Unable to determine least frequently used item")

    # Remove the identified item from the cache and frequency map
    try:
        removed_value = cache.pop(min_key)
        freq_map.pop(min_key, None)
    except Exception as exc:
        # If any issue happens during removal, raise KeyError with context
        raise KeyError(f"Failed to remove item {min_key!r}: {exc}") from exc

    # Return the removed key-value pair
    return (min_key, removed_value)

