def isoparse(self, dt_str):
    """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    The parser accepts many common ISO‑8601 date and time formats,
    including partial dates, ISO week dates, and a variety of time‑
    zone specifications.  Unspecified components default to their
    lowest values.
    """
    try:
        if not isinstance(dt_str, (str, bytes)):
            raise ValueError("Input must be a string or bytes")
        if isinstance(dt_str, bytes):
            dt_str = dt_str.decode('ascii')
        original_str = dt_str

        # Split into date/time and optional timezone
        date_part = dt_str
        time_part = ''
        tzinfo = None

        if 'T' in dt_str:
            date_part, rest = dt_str.split('T', 1)
            # Detect timezone at end of rest
            if rest.endswith('Z'):
                tzinfo_part = 'Z'
                time_part = rest[:-1]
            else:
                m = re.search(r'[+-]\d{2}(:?\d{2})?$', rest)
                if m:
                    tzinfo_part = m.group(0)
                    time_part = rest[:m.start()]
                else:
                    tzinfo_part = None
                    time_part = rest
        else:
            # No time separator; timezone may follow date
            m = re.search(r'(?P<tz>Z|[+-]\d{2}(:?\d{2})?)$', dt_str)
            if m:
                tzinfo_part = m.group('tz')
                date_part = dt_str[:m.start()]
                time_part = ''
            else:
                tzinfo_part = None
                time_part = ''

        # ---------- Parse timezone ----------
        if tzinfo_part is not None:
            if tzinfo_part == 'Z':
                tzinfo = dateutil.tz.tzutc()
            else:
                sign = 1 if tzinfo_part[0] == '+' else -1
                # Remove sign
                tz_num = tzinfo_part[1:]
                if ':' in tz_num:
                    h, m = tz_num.split(':')
                else:
                    if len(tz_num) == 2:
                        h, m = tz_num, '0'
                    elif len(tz_num) > 2:
                        h, m = tz_num[:2], tz_num[2:]
                    else:
                        h, m = tz_num, '0'
                h = int(h)
                m = int(m) if m else 0
                offset_seconds = sign * (h * 3600 + m * 60)
                if offset_seconds == 0:
                    tzinfo = dateutil.tz.tzutc()
                else:
                    tzinfo = dateutil.tz.tzoffset(None, offset_seconds)

        # ---------- Parse date ----------
        # ISO week dates
        week_match = re.match(r'(\d{4})-?W(\d{2})-?(\d{1})?$', date_part)
        if week_match:
            year = int(week_match.group(1))
            week = int(week_match.group(2))
            day_iso = int(week_match.group(3)) if week_match.group(3) else 1
            try:
                y, m, d = datetime.date.fromisocalendar(year, week, day_iso).timetuple()[:3]
            except ValueError as e:
                raise ValueError(f"Invalid ISO week date: {date_part}") from e
        else:
            # Regular date with optional month/day
            parts = re.split(r'-', date_part)
            year = int(parts[0])
            month = int(parts[1]) if len(parts) > 1 and parts[1] else 1
            day = int(parts[2]) if len(parts) > 2 and parts[2] else 1
            # Allow no separators (YYYYMMDD or YYYYMM)
            if len(parts) == 1:
                s = parts[0]
                if len(s) == 8:
                    year = int(s[:4]); month = int(s[4:6]); day = int(s[6:8])
                elif len(s) == 6:
                    year = int(s[:4]); month = int(s[4:6]); day = 1
                elif len(s) == 4:
                    year = int(s); month = 1; day = 1
                else:
                    raise ValueError(f"Unknown date format: {date_part}")
        # ---------- Parse time ----------
        hour = minute = second = microsecond = 0
        if time_part:
            # Handle separators or compact numeric form
            if any(c in time_part for c in ':.,'):
                sep = ':' if ':' in time_part else ',' if ',' in time_part else '.'
                time_parts = re.split(f'[{sep}]+', time_part)
                if len(time_parts) > 0:
                    hour = int(time_parts[0])
                if len(time_parts) > 1:
                    minute = int(time_parts[1])
                if len(time_parts) > 2:
                    sec_frac = time_parts[2]
                    if '.' in sec_frac or ',' in sec_frac:
                        # Already split, no
                        pass
                    second = int(sec_frac)
                if len(time_parts) > 3:
                    # Fraction of second
                    frac = time_parts[3]
                    microsecond = int((frac + '000000')[:6])
            else:
                # Compact form like hhmmss or hhmm
                tlen = len(time_part)
                if tlen == 2:
                    hour = int(time_part)
                elif tlen == 4:
                    hour = int(time_part[:2]); minute = int(time_part[2:])
                elif tlen == 6:
                    hour = int(time_part[:2]); minute = int(time_part[2:4]); second = int(time_part[4:])
                else:
                    raise ValueError(f"Unknown time format: {time_part}")

        # Validate time ranges
        if not (0 <= hour <= 24):
            raise ValueError(f"Hour out of range: {hour}")
        if not (0 <= minute < 60):
            raise ValueError(f"Minute out of range: {minute}")
        if not (0 <= second < 60):
            raise ValueError(f"Second out of range: {second}")
        if microsecond >= 1_000_000:
            raise ValueError(f"Microsecond out of range: {microsecond}")

        # Handle midnight-24:00 edge case
        midnight_next = False
        if hour == 24:
            if minute != 0 or second != 0 or microsecond != 0:
                raise ValueError("24 hour must not have non‑zero minutes, seconds or microseconds")
            hour = 0
            midnight_next = True

        dt = datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)
        if midnight_next:
            dt += datetime.timedelta(days=1)
        return dt
    except Exception as exc:
        raise ValueError(f"Invalid ISO‑8601 datetime '{original_str}': {exc}") from exc

def parse(self, timestr, default=None,
