def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    import re
    from urllib.parse import urlparse
    # Regular expression to match http, https, or ftp URLs
    url_pattern = re.compile(r'\b((?:https?|ftp)://[^\s<>"\'\]]+)')
    def _replace(match):
        url = match.group(0)
        try:
            parsed = urlparse(url)
            if parsed.scheme not in ('http', 'https', 'ftp'):
                return url
            # Add typical security and usability attributes
            attrs = ' target="_blank" rel="noopener noreferrer"'
            return f'<a href="{url}"{attrs}>{url}</a>'
        except Exception:
            # If parsing fails, return the original text unchanged
            return url
    try:
        return url_pattern.sub(_replace, text)
    except Exception as exc:
        raise RuntimeError(f"Error while processing links: {exc}") from exc

