    url_re = re.compile(r'(https?://[^\s<]+)')
    def repl(match):
        url = match.group(0)
        return (
            f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
        )
    try:
        return url_re.sub(repl, text)
    except Exception as exc:
        raise RuntimeError(f"Failed to process links: {exc}") from exc

