    _URL_RE = re.compile(r'\b(https?://[^\s<>"\'`]+)', re.IGNORECASE)

    def _replace(match):
        url = match.group(0)
        # Wrap the URL in a link with common attributes for external links
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    return _URL_RE.sub(_replace, text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        scheme, netloc, _, _, _ = urlparse.urlsplit(url)
        if scheme not in ('http', 'https', 'ftp', 'ftps'):
            # Unsupported scheme
            return None
        req = Urllib2HeadRequest(url, headers={'Host': netloc})
        resp = urlopen(req)
        try:
            # For HTTP/HTTPS, a non-200 response may indicate an error
            if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
                return None
            content_type = resp.info().get('content-type')
            return content_type  # may be None if header missing
        finally:
            resp.close()
    except Exception:
        # Any network or parsing error results in a None
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        scheme = urlparse.urlsplit(url).scheme.lower()
        if scheme not in ("http", "https"):
            return None
        req = urllib.request.Request(url, method="HEAD")
        with urllib.request.urlopen(req) as resp:
            status = getattr(resp, "status", getattr(resp, "code", None))
            if status and status >= 400 and scheme not in ("ftp", "ftps"):
                return None
            return resp.getheader("Content-Type")
    except Exception:
        return None

