def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON first
        import json
        parsed = json.loads(document)
        return parsed
    except Exception:
        # Fallback to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            root = ET.fromstring(document)

            result: Dict[str, object] = {}

            # Extract <Link> elements
            for link in root.findall(".//xrd:Link", ns):
                rel = link.attrib.get("rel")
                href = link.attrib.get("href")
                if rel and href:
                    # If multiple links with same rel, store as list
                    if rel in result:
                        if isinstance(result[rel], list):
                            result[rel].append(href)
                        else:
                            result[rel] = [result[rel], href]
                    else:
                        result[rel] = href

            # Extract <Subject>
            subject = root.find(".//xrd:Subject", ns)
            if subject is not None and subject.text:
                result["subject"] = subject.text

            # Extract other useful elements if needed
            # e.g., <DisplayName> or <Expires>
            for tag in ["DisplayName", "Expires"]:
                element = root.find(f".//xrd:{tag}", ns)
                if element is not None and element.text:
                    result[tag.lower()] = element.text

            return result
        except Exception:
            # If parsing fails, return None to indicate failure
            return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        logger.warning(
            "parse_diaspora_webfinger: no document provided"
        )
        return None

    try:
        # Strip leading whitespace to detect format
        stripped = document.lstrip()
        if stripped.startswith("{"):
            # Modern JSON format
            data = json.loads(document)
            # Extract hcard URL if present
            links = data.get("links", [])
            for link in links:
                if link.get("rel") == "hcard":
                    data["hcard_url"] = link.get("href")
                    break
            return data

        # Assume old XRD / XML format
        root = ET.fromstring(document)

        result: Dict = {}
        # Get subject
        subject = root.findtext("./{*}Subject")
        if subject:
            result["subject"] = subject

        # Get aliases if any
        aliases = [elem.text for elem in root.findall("./{*}Alias")]
        if aliases:
            result["aliases"] = aliases

        # Get hcard link
        hcard_link = None
        for link in root.findall(".//{*}Link"):
            if link.get("rel") == "hcard":
                hcard_link = link.get("href")
                break
        if hcard_link:
            result["hcard_url"] = hcard_link

        # If we got nothing, return None
        if not result:
            logger.warning(
                "parse_diaspora_webfinger: no recognizable data found in XRD"
            )
            return None

        return result

    except Exception as exc:
        logger.warning(
            "parse_diaspora_webfinger: failed to parse document: %s", exc
        )
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not isinstance(document, str):
        return {}

    # Attempt to parse as JSON first
    try:
        return json.loads(document)
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except Exception:
        return {}

    ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
    result: Dict = {}

    # Subject
    subject_elem = root.find("xrd:Subject", ns)
    result["subject"] = subject_elem.text if subject_elem is not None else None

    # Aliases
    aliases = [e.text for e in root.findall("xrd:Alias", ns) if e.text]
    result["aliases"] = aliases

    # Properties
    properties: Dict[str, str] = {}
    for prop in root.findall("xrd:Property", ns):
        term = prop.attrib.get("term")
        if term and prop.text:
            properties[term] = prop.text
    result["properties"] = properties

    # Links
    links: Dict[str, list] = {}
    for link in root.findall("xrd:Link", ns):
        rel = link.attrib.get("rel")
        if not rel:
            continue
        link_info: Dict[str, str] = {}
        href = link.attrib.get("href")
        template = link.attrib.get("template")
        if href:
            link_info["href"] = href
        if template:
            link_info["template"] = template
        if rel not in links:
            links[rel] = []
        links[rel].append(link_info)
    result["links"] = links

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # First attempt JSON parsing
    try:
        data = json.loads(document)
        links = data.get("links", [])
        if not isinstance(links, list):
            links = []
        return {"subject": data.get("subject"), "links": links}
    except (ValueError, TypeError):
        pass

    # Fallback to XRD parsing
    try:
        root = ElementTree.fromstring(document)
        # Find subject (may be namespaced)
        subject = None
        for elem in root.iter():
            if elem.tag.endswith("Subject"):
                subject = elem.text
                break
        # Collect link entries
        links = []
        for link in root.findall(".//Link"):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            # Template attribute may be named 'templ' or 'tpl' depending on server
            templ = link.attrib.get("templ")
            if templ is None:
                templ = link.attrib.get("tpl")
            links.append(
                {
                    "rel": rel,
                    "href": href,
                    "href_template": templ,
                }
            )
        return {"subject": subject, "links": links}
    except Exception:
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    result: Dict[str, str] = {}

    # First try JSON
    try:
        wf_json = json.loads(document)
        links = wf_json.get("links", [])
        for link in links:
            rel = link.get("rel")
            href = link.get("href") or link.get("template")
            if rel == "hcard" and href:
                result["hcard_url"] = href
            elif rel == "lrdd" and href:
                result["lrdd"] = href
        if result:
            return result
    except Exception:
        # Not JSON, fall back to XRD parsing
        pass

    # Try XRD (XML Resource Descriptor)
    try:
        root = ET.fromstring(document)
        # Namespace may be present
        ns = {"xrd": root.tag.split("}")[0].strip("{")} if "}" in root.tag else {}
        for link in root.findall("xrd:Link", ns):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href") or link.attrib.get("template")
            if rel == "hcard" and href:
                result["hcard_url"] = href
            elif rel == "lrdd" and href:
                result["lrdd"] = href
        if result:
            return result
    except Exception:
        # If parsing fails, return None
        pass

    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        # Extract host from handle
        host = handle.split("@")[1]
    except Exception:
        return None
    # Encode the resource parameter
    try:
        resource = urllib.parse.quote(f"acct:{handle}")
    except Exception:
        return None
    # Construct the webfinger URL
    url = f"https://{host}/.well-known/webfinger?resource={resource}"
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            if response.status != 200:
                return None
            # Decode as UTF-8, replace errors
            return response.read().decode('utf-8', errors='replace')
    except Exception:
        # Any error (e.g., network, HTTP error) results in no document
        return None

