def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        # Normalise settings_dirs to a list of directories
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            try:
                dirs = list(settings_dirs)
            except TypeError:
                dirs = [settings_dirs]

        # Normalise spec_option to a list of patterns
        if isinstance(spec_option, str):
            patterns = [spec_option]
        else:
            try:
                patterns = list(spec_option)
            except TypeError:
                patterns = [spec_option]

        result = []

        for d in dirs:
            if not isinstance(d, str) or not d:
                continue
            if not os.path.isdir(d):
                continue
            for root, _, files in os.walk(d):
                for fname in files:
                    if any(fnmatch.fnmatch(fname, p) for p in patterns):
                        result.append(os.path.join(root, fname))

        return sorted(result)
    except Exception:
        # In case of any error, return an empty list
        return []

def list_of_file_names(settings_dirs, spec_option):
