def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import copy
    def _merge_include(section, name, visited=None):
        """
        Recursively merge included sections into the current section.
        """
        if visited is None:
            visited = set()
        if not isinstance(section, dict):
            return
        includes = section.pop('include', None)
        if includes is None:
            return
        if isinstance(includes, str):
            includes = [includes]
        for inc_name in includes:
            # Detect circular references
            cycle_key = f"{name}:{inc_name}"
            if cycle_key in visited:
                raise RuntimeError(f"Circular include detected: {cycle_key}")
            visited.add(cycle_key)
            inc_section = parser_dict.get(inc_name)
            if inc_section is None:
                raise KeyError(f"Included group '{inc_name}' not found in parser_dict")
            # Perform a shallow copy of the included section to avoid mutating the original spec
            for k, v in inc_section.items():
                if k not in section:
                    section[k] = copy.deepcopy(v)
            # After merging the root two levels, dive into any nested includes
            _merge_include(section, f"{name}->{inc_name}", visited)
    # Process every top-level entry in parser_dict
    for key, val in list(parser_dict.items()):
        _merge_include(val, key)

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # To avoid modifying the original dict, create a new dictionary
        resolved = {}
        # Keep track of groups that are currently being resolved to
        # detect circular includes
        resolving = set()

        def _resolve_group(name):
            if name in resolving:
                raise ValueError(f'Circular include detected for group {name}')
            resolving.add(name)

            if name not in parser_dict:
                raise KeyError(f'Group "{name}" not found in parser_dict')
            # Make a shallow copy so we do not mutate the original
            grp = dict(parser_dict[name])

            # Handle 'include' directives if present
            includes = grp.pop('include', None)
            if includes is not None:
                if not isinstance(includes, (list, tuple)):
                    includes = [includes]
                merged = {}
                for inc_name in includes:
                    inc_group = _resolve_group(inc_name)
                    merged.update(inc_group)
                # Merge the current group's own entries after includes
                merged.update(grp)
                resolving.remove(name)
                return merged
            else:
                resolving.remove(name)
                return grp

        for group_name in parser_dict:
            resolved[group_name] = _resolve_group(group_name)
        return resolved

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    resolved = {}
    visited = set()
    stack = []

    def _resolve_group(group_name):
        if group_name in resolved:
            return  # already processed
        if group_name in stack:
            raise ValueError(f"Circular include detected for group {group_name}")
        if group_name not in parser_dict:
            raise KeyError(f"Group '{group_name}' not found in parser dictionary")
        stack.append(group_name)
        content = parser_dict[group_name]
        if not isinstance(content, dict):
            raise TypeError(f"Content of group '{group_name}' must be a dict")
        include = content.pop('include', None)
        merged = {}
        if include:
            if isinstance(include, str):
                include = [include]
            for inc_group in include:
                _resolve_group(inc_group)
                merged.update(resolved[inc_group])
        merged.update(content)
        resolved[group_name] = merged
        stack.pop()

    for grp in list(parser_dict.keys()):
        _resolve_group(grp)
    return resolved

