    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dictionary")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dictionary")
    # Mapping from deprecated argument names to updated names.  Read from
    # an attribute so callers can define their own mapping.
    deprecation_map = getattr(self, "deprecated_arg_mapping", None)
    if not deprecation_map:
        return
    # Combine the two sources so we can warn about any use of deprecated
    # arguments regardless of origin.
    all_args = {**answer_file_args, **cli_args}
    for old_arg, new_arg in deprecation_map.items():
        if old_arg in all_args:
            warnings.warn(
                f"Argument '{old_arg}' is deprecated; use '{new_arg}' instead.",
                DeprecationWarning,
                stacklevel=2,
            )
    # If a caller supplies both the old and new names, raise an error
    # so they can resolve the conflict immediately.
    for old_arg, new_arg in deprecation_map.items():
        if old_arg in cli_args and new_arg in cli_args:
            raise ValueError(
                f"Both deprecated argument '{old_arg}' and updated "
                f"argument '{new_arg}' supplied."
            )

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if command_name is None:
        raise ValueError("command_name must not be None")
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if command_name.strip() == "":
        raise ValueError("command_name must not be an empty string")

    # Retrieve the internal registry of options if it exists
    registry = getattr(self, "_command_options", None)
    if registry is None:
        raise RuntimeError("Command options registry not initialized")
    if not isinstance(registry, dict):
        raise RuntimeError("Command options registry should be a dict mapping names to option lists")

    # Attempt to find the exact key
    if command_name in registry:
        opts = registry[command_name]
    else:
        # Try a case-insensitive match as a fallback
        matched_key = None
        for key in registry:
            if key.lower() == command_name.lower():
                matched_key = key
                break
        if matched_key is not None:
            opts = registry[matched_key]
        else:
            # No match found
            raise KeyError(f"Command '{command_name}' not found in options registry")

    # Ensure the returned value is a list; if it's a tuple or set, convert to list
    if isinstance(opts, (tuple, set)):
        opts = list(opts)
    if not isinstance(opts, list):
        raise RuntimeError("Options for command should be a list or tuple in the registry")

    # Return a shallow copy to prevent accidental modification of the registry
    return list(opts)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")

        # A mapping from command names to list of option specifications.
        # The attribute name may vary – adjust if different in the actual class.
        options_map = getattr(self, "_command_options", None)
        if options_map is None:
            raise AttributeError("Missing '_command_options' attribute on the object")

        opts = options_map.get(command_name)
        if opts is None:
            raise KeyError(f"No options defined for command '{command_name}'")

        # Return a shallow copy to avoid accidental mutation by callers
        return list(opts)

    except Exception as exc:
        # If a logger is available, log the error; otherwise, just re‑raise.
        logger = getattr(self, "logger", None)
        if logger is not None:
            logger.error(f"Failed to retrieve parser options for '{command_name}': {exc}")
        raise

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc…)
    :return: a list of dictionaries describing each option
    """
    # Validate the command name
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    command_name = command_name.strip()
    if not command_name:
        raise ValueError("command_name cannot be empty")

    # Ensure the instance has a mapping of command names to ArgumentParser objects
    if not hasattr(self, "_cmd_parsers"):
        raise AttributeError("Instance missing '_cmd_parsers' attribute")
    parser = self._cmd_parsers.get(command_name)
    if parser is None:
        raise KeyError(f"Unknown command '{command_name}'")

    # Extract option information from argparse actions
    options = []
    for action in parser._actions:
        if action.option_strings:
            options.append(
                {
                    "option_strings": action.option_strings,
                    "help": action.help,
                    "default": action.default,
                    "dest": action.dest,
                    "metavar": action.metavar,
                }
            )
    return options

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")
    # Retrieve the command specification; raise if missing
    try:
        command_spec = self.commands[command_name]
    except AttributeError:
        raise AttributeError("The object does not have a 'commands' attribute")
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found")
    # The command spec may be a dict of options or an object with an 'options' dict
    if isinstance(command_spec, dict):
        options = command_spec.get("options", command_spec)
    else:
        options = getattr(command_spec, "options", None)
        if options is None:
            # fall back to treating the command spec itself as the options mapping
            options = command_spec
    # Ensure we have a mapping to index by argument_name
    if not isinstance(options, dict):
        raise TypeError(f"Options for command '{command_name}' are not a dictionary")
    # Retrieve the argument specification; raise if missing
    try:
        arg_spec = options[argument_name]
    except KeyError:
        raise KeyError(f"Argument '{argument_name}' not found in command '{command_name}'")
    return arg_spec

def get_option_spec(self, command_name, argument_name):
