        if not isinstance(cmd_specs, dict):
            return None
        # retrieve the command-specific spec
        command_spec = cmd_specs.get(command_name)
        if not isinstance(command_spec, dict):
            return None
        # return the specific argument's spec if present
        return command_spec.get(argument_name)
