        # swallow unexpected errors and return None as a safe fallback
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if not args:
        return []

    # determine the source of arguments
    if hasattr(args, "__dict__"):
        arg_dict = vars(args)
    elif isinstance(args, dict):
        arg_dict = args
    else:
        # try to interpret as an iterable of items (name, value) or names
        arg_dict = {}
        for item in args:
            if isinstance(item, tuple) and len(item) == 2:
                name, val = item
                arg_dict[name] = val
            else:
                arg_dict[item] = None

    silent = []

    for name, val in arg_dict.items():
        # consider silent if:
        # 1. the value is None or False
        # 2. or the argument name starts with an underscore
        if val is None or val is False or name.startswith("_"):
            silent.append(name)

    return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    try:
        for arg in args:
            # consider string arguments that look like options
            if isinstance(arg, str) and arg.startswith('-'):
                silent.append(arg)
    except Exception:
        # If args is not iterable or other unexpected type, return empty list
        return []
    return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    try:
        # args could be a dict or argparse.Namespace or similar
        if isinstance(args, dict):
            arg_dict = args
        else:
            arg_dict = vars(args)
    except Exception:
        return []

    silent = [name for name, value in arg_dict.items() if value is None]
    return silent[:]  # Return a copy to avoid accidental mutation.

def get_silent_args(self, args):
    """
    Return a list of argument names that are considered "silent".

    "Silent" arguments are those that start with a dash ('-') or double-dash ('--')
    and contain the substring "silent" in a case‑insensitive manner (e.g. '--silent',
    '-s', '--no-silent-output', etc.).

    :param args: Iterable of received command‑line arguments (typically a list of strings).
    :return: List[str] – argument names that are flagged as silent.
    """
    silent_args = []
    try:
        for arg in args:
            if not isinstance(arg, str):
                continue
            if arg.startswith('-') and 'silent' in arg.lower():
                silent_args.append(arg)
    except Exception:
        # In case args is None or not iterable, return an empty list
        return []
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, 'required', [])
    if not required:
        return
    if isinstance(args, dict):
        missing = [name for name in required
                   if name not in args or args[name] is None]
    else:
        # Assume a positional sequence, missing arguments are those beyond the
        # supplied count.
        missing = [required[i] for i in range(len(args), len(required))]
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not hasattr(self, "required_args"):
        raise AttributeError("The instance does not have a 'required_args' attribute.")
    missing = []
    for key in getattr(self, "required_args"):
        if key not in args or args[key] is None:
            missing.append(key)
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, "_required_args", [])
    if not isinstance(required, (list, set, tuple)):
        raise TypeError("_required_args must be an iterable of argument names.")
    missing = []
    for name in required:
        if isinstance(args, dict):
            if name not in args or args[name] is None:
                missing.append(name)
        else:
            # Assume args is a sequence; try to map to names if available
            if hasattr(self, "_required_arg_positions") and isinstance(self._required_arg_positions, dict):
                index = self._required_arg_positions.get(name)
                if index is None or index >= len(args) or args[index] is None:
                    missing.append(name)
            else:
                raise TypeError("args must be a dict or a sequence with positional mapping.")
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Validate that args is a mapping (e.g., dict)
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping type (e.g., dict)")

    # Determine which arguments are required.
    required = getattr(self, "required", None)

    if not required:
        # Nothing to validate
        return True

    missing = []
    for name in required:
        # A key is considered missing if it is not present or its value is None
        if name not in args or args[name] is None:
            missing.append(name)

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Acceptable inputs: dict or mapping of argument name to value
    try:
        if args is None:
            raise ValueError("Provided args cannot be None")
        if not isinstance(args, dict):
            raise TypeError("Provided args must be a mapping (dict) of argument names to values")
        # Determine the list of required argument names.  The subclass
        # may expose them via `required` or `_required` attributes.
        required = getattr(self, "required", None)
        if required is None:
            required = getattr(self, "_required", None)
        if required is None:
            # No required arguments defined – nothing to validate
            return True
        # Ensure required is iterable
        try:
            iterator = iter(required)
        except TypeError:
            raise TypeError("Required arguments must be an iterable of argument names")
        missing = []
        for name in iterator:
            if name not in args or args[name] is None:
                missing.append(name)
        if missing:
            raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
        return True
    except Exception as err:
        # Preserve the original traceback for debugging
        raise ValueError(f"Argument validation failed: {err}") from err

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = set()
    # Normalize inputs
    if options_spec is None:
        return list(required)
    for opt in options_spec:
        # Each option expected to be a mapping
        if not isinstance(opt, dict):
            continue
        req_when = opt.get('required_when')
        if not req_when:
            continue
        # Determine option name
        opt_name = opt.get('arg') or opt.get('name') or opt.get('id')
        if not opt_name:
            continue  # skip if no identifiable name
        try:
            # If callable, invoke with command_name and args
            if callable(req_when):
                if req_when(command_name, args):
                    required.add(opt_name)
                continue
            # If dict, interpret common patterns
            if isinstance(req_when, dict):
                # pattern { 'command': ['cmd1', 'cmd2'] }
                cmd_list = req_when.get('command') or req_when.get('commands')
                if cmd_list:
                    if command_name in cmd_list:
                        required.add(opt_name)
                        continue
                # fallback: if key matches command_name
                if command_name in req_when:
                    required.add(opt_name)
                    continue
            # If iterable of conditions
            if isinstance(req_when, (list, tuple, set)):
                for cond in req_when:
                    if callable(cond):
                        if cond(command_name, args):
                            required.add(opt_name)
                            break
                    elif isinstance(cond, dict):
                        cmd_list = cond.get('command') or cond.get('commands')
                        if cmd_list and command_name in cmd_list:
                            required.add(opt_name)
                            break
        except Exception:
            # silently ignore any mis-evaluated condition
            continue
    return list(required)

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """

    # Normalise options_spec to an iterable of option dicts
    if isinstance(options_spec, dict):
        options_iterable = options_spec.values()
    else:
        options_iterable = options_spec

    required_when_names = []
    for opt in options_iterable:
        # Skip if no required_when
        if 'required_when' not in opt:
            continue

        condition = opt['required_when']
        matched = False
        try:
            if callable(condition):
                matched = bool(condition(args))
            else:
                # Treat as string expression, evaluate with args in context
                matched = bool(eval(condition, {'args': args}))
        except Exception:
            # If evaluation fails, treat as not matched
            matched = False

        if matched:
            # Get the command line argument name
            # Prefer 'name', fall back to 'arg', otherwise None
            opt_name = opt.get('name') or opt.get('arg')
            if opt_name:
                required_when_names.append(opt_name)

    return required_when_names

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Basic validation
        if not isinstance(options_spec, list):
            raise TypeError("options_spec must be a list of option specs")
        if not isinstance(args, dict):
            raise TypeError("args must be a dict of received arguments")

        required = []
        for opt in options_spec:
            if not isinstance(opt, dict):
                continue
            if 'required_when' not in opt:
                continue
            conditions = opt['required_when']
            matched = True

            # Support either a dict (single condition) or a list of dicts
            if isinstance(conditions, dict):
                for k, v in conditions.items():
                    if args.get(k) != v:
                        matched = False
                        break
            elif isinstance(conditions, list):
                # At least one condition in the list must match
                matched = False
                for cond in conditions:
                    if not isinstance(cond, dict):
                        continue
                    ok = True
                    for k, v in cond.items():
                        if args.get(k) != v:
                            ok = False
                            break
                    if ok:
                        matched = True
                        break
            else:
                # Unsupported condition format
                matched = False

            if matched:
                # Prefer the key used for dest (arg) over name
                arg_name = opt.get('arg') or opt.get('name')
                if arg_name:
                    required.append(arg_name)
        return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    req_args = []
    for opt in options_spec:
        cond = opt.get('required_when')
        if cond is None:
            continue
        # Determine the argument name to be returned
        opt_name = opt.get('arg') or opt.get('name') or opt.get('dest')
        if not opt_name:
            continue

        match = False
        # Callable condition: execute with args
        if callable(cond):
            try:
                match = bool(cond(args))
            except Exception:
                match = False
        # List/tuple/set of option names – required if any present
        elif isinstance(cond, (list, tuple, set)):
            match = any(item in args for item in cond)
        # Dictionary of more complex conditions
        elif isinstance(cond, dict):
            match = True
            for key, val in cond.items():
                if key not in args:
                    match = False
                    break
                # If value is callable, apply to the arg value
                if callable(val):
                    try:
                        if not val(args[key]):
                            match = False
                            break
                    except Exception:
                        match = False
                        break
                else:
                    if args[key] != val:
                        match = False
                        break
        # String condition – treat it as a command name comparison
        elif isinstance(cond, str):
            match = (cond == command_name)
        # Any truthy value means always required
        elif cond:
            match = True

        if match:
            req_args.append(opt_name)
    return req_args

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for spec in options_spec:
        # Determine the option name; keys might be 'arg', 'name' or 'option'
        name = spec.get('arg') or spec.get('name') or spec.get('option')
        if not name:
            continue
        condition = spec.get('required_when')
        if condition is None:
            continue

        matched = False
        try:
            if callable(condition):
                matched = bool(condition(command_name, args))
            elif isinstance(condition, bool):
                matched = condition
            elif isinstance(condition, str):
                # Treat string as a dependent option name
                matched = bool(args.get(condition))
            elif isinstance(condition, dict):
                # All key/value pairs must match the args
                matched = all(args.get(k) == v for k, v in condition.items())
            else:
                # Unsupported condition type; treat as not matched
                matched = False
        except Exception:
            matched = False

        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument name to attributes")

    for name, attrs in args.items():
        # Expect attrs to be a mapping containing 'value' and 'max_length'
        if not isinstance(attrs, dict):
            continue
        if 'value' not in attrs or 'max_length' not in attrs:
            continue
        value = attrs['value']
        max_len = attrs['max_length']
        try:
            length = len(value)
        except (TypeError, AttributeError):
            # Value is not a sized object; skip validation
            continue
        if length > max_len:
            raise ValueError(
                f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Validate args structure
    if not isinstance(args, (dict, list)):
        raise TypeError(f"args must be dict or list, got {type(args).__name__}")

    def _validate_one(arg_name, attr):
        if not isinstance(attr, dict):
            raise TypeError(f"Argument {arg_name} attributes must be dict, got {type(attr).__name__}")
        expected_len = attr.get('length')
        if expected_len is None:
            return
        if not isinstance(expected_len, int):
            raise TypeError(f"Argument {arg_name} length must be int, got {type(expected_len).__name__}")
        value = attr.get('value')
        if value is None:
            return  # no value to check
        try:
            actual_len = len(value)
        except TypeError:
            raise TypeError(f"Argument {arg_name} value of type {type(value).__name__} has no len()")
        if actual_len > expected_len:
            raise ValueError(f"Argument {arg_name} is too long: {actual_len} > {expected_len}")

    if isinstance(args, dict):
        for name, attrs in args.items():
            _validate_one(name, attrs)
    else:  # list
        for arg in args:
            if not isinstance(arg, dict):
                raise TypeError(f"List item must be dict, got {type(arg).__name__}")
            if len(arg) != 1:
                raise ValueError(f"Argument dict must contain a single item, got {len(arg)}")
            name, attrs = next(iter(arg.items()))
            _validate_one(name, attrs)

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Expected format is either a dict
    where each key is an argument name and each value is a dict of
    attributes (must include 'value' and optionally 'max_length' and/or
    'min_length'), or a list of such dicts.

    The method will raise a ValueError if any argument's value exceeds
    the specified maximum length. If 'min_length' is supplied it will
    also validate the lower bound.
    """
    # normalize input: if list, iterate items
    items = args
    if isinstance(args, list):
        items = enumerate(args)
    elif not isinstance(args, dict):
        raise TypeError("args must be a dict or list of dicts")
    for key, argattrs in items:
        if isinstance(key, int) and isinstance(argattrs, dict):
            # in list case, key is index, value contains attrs dict
            name = f"arg[{key}]"
            attrs = argattrs
        elif isinstance(argattrs, dict):
            name = key
            attrs = argattrs
        else:
            # skip invalid entry
            continue
        # Only proceed if attrs is a dict
        if not isinstance(attrs, dict):
            continue
        # Retrieve the value to be checked
        val = attrs.get('value')
        if val is None:
            continue  # Nothing to validate
        # Determine the kind of validation to perform
        max_len = attrs.get('max_length')
        min_len = attrs.get('min_length')
        # Validate max_length if specified
        if max_len is not None:
            if not isinstance(max_len, int):
                raise TypeError(f"max_length for {name} must be an int, got {type(max_len).__name__}")
            if max_len < 0:
                raise ValueError(f"max_length for {name} must be non-negative, got {max_len}")
            try:
                val_len = len(val)
            except Exception as exc:
                raise TypeError(f"Value for {name} has no length: {exc}") from exc
            if val_len > max_len:
                raise ValueError(f"Value for {name} exceeds maximum length {max_len} (actual length {val_len})")
        # Validate min_length if specified
        if min_len is not None:
            if not isinstance(min_len, int):
                raise TypeError(f"min_length for {name} must be an int, got {type(min_len).__name__}")
            if min_len < 0:
                raise ValueError(f"min_length for {name} must be non-negative, got {min_len}")
            try:
                val_len = len(val)
            except Exception as exc:
                raise TypeError(f"Value for {name} has no length: {exc}") from exc
            if val_len < min_len:
                raise ValueError(f"Value for {name} is shorter than minimum length {min_len} (actual length {val_len})")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    arg_specs = self.parsed_yaml.get('args', {})
    # Resolve list-based args to a list of (name, value) tuples
    if isinstance(args, dict):
        items = list(args.items())
    elif isinstance(args, list):
        items = []
        for item in args:
            if not isinstance(item, dict):
                raise TypeError(
                    f"List items must be dicts; got {type(item).__name__}")
            if len(item) != 1:
                raise ValueError(
                    f"Argument list item must contain exactly one key-value "
                    f"pair; got {item}")
            name, value = next(iter(item.items()))
            items.append((name, value))
    else:
        raise TypeError(f"args must be a dict or list; got {type(args).__name__}")

    # Validate each argument against its max_length spec if present
    for name, value in items:
        spec = arg_specs.get(name, {})
        max_len = spec.get('max_length')
        if max_len is None:
            # No length constraint defined for this argument; skip validation
            continue
        if not isinstance(max_len, int):
            raise TypeError(
                f"max_length for argument '{name}' must be an integer; "
                f"got {type(max_len).__name__}")
        try:
            length = len(value)
        except Exception:
            # If value has no length, skip the check
            continue
        if length > max_len:
            raise ValueError(
                f"Argument '{name}' has length {length} which exceeds "
                f"the maximum allowed ({max_len}).")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Accept either a dict or a list of (name, value) tuples.
    if isinstance(args, list):
        try:
            args = dict(args)
        except Exception:
            raise ValueError("args list must contain key/value pairs")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict or list of tuples")

    # Determine the argument specification.  A concrete subclass might
    # provide it under a known attribute; fall back to a generic name.
    arg_spec = getattr(self, "argument_spec", None)
    if arg_spec is None:
        arg_spec = getattr(self, "parsed_yaml", {}).get("args", {})
    if not isinstance(arg_spec, dict):
        # The spec is malformed; nothing to validate.
        return

    for name, spec in arg_spec.items():
        if not isinstance(spec, dict):
            # Malformed spec entry; skip.
            continue
        choices = spec.get("choices")
        if not choices:
            continue
        if name not in args:
            # Argument not supplied; nothing to check.
            continue
        value = args[name]
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{name}': {value!r}. "
                f"Expected one of: {choices}"
            )
    # If we get here, all choice arguments are valid. No return value needed.

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a mapping; nothing to validate if it is not.
    if args is None:
        return
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary, got %s" % type(args).__name__)

    # The class is expected to define a `choices` mapping:
    #   {arg_name: iterable_of_allowed_values}
    # If none is defined, we simply skip validation.
    choices_map = getattr(self, 'choices', None)
    if choices_map is None:
        return
    if not isinstance(choices_map, dict):
        raise TypeError("self.choices should be a dict mapping argument names to allowed values")

    for arg_name, value in args.items():
        # Only validate when a choice set exists for this argument.
        if arg_name not in choices_map:
            continue

        allowed = choices_map[arg_name]
        # Guarantee that allowed is iterable.
        try:
            iterable = iter(allowed)
        except TypeError:
            raise TypeError("allowed choices for argument '%s' must be iterable, got %s"
                            % (arg_name, type(allowed).__name__))

        # For None values, allow only if None is part of allowed set.
        if value not in allowed:
            msg = ("Invalid value for choice argument '%s': %r. "
                   "Expected one of %r" % (arg_name, value, allowed))
            raise ValueError(msg)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("Expected args to be a dict")
    # Retrieve mapping of argument names to allowed choice lists
    choices_map = getattr(self, 'choices', getattr(self, '_choices', None))
    if not isinstance(choices_map, dict):
        # No explicit choices map defined; nothing to validate
        return
    for arg_name, arg_value in args.items():
        if arg_name in choices_map:
            allowed = choices_map[arg_name]
            # If allowed is a callable (e.g. a function returning a list), call it
            if callable(allowed):
                try:
                    allowed = allowed()
                except Exception as exc:  # pragma: no cover
                    raise RuntimeError(
                        f"Error retrieving valid choices for argument '{arg_name}': {exc}"
                    ) from exc
            if arg_value not in allowed:
                raise ValueError(
                    f"Invalid value for choice argument '{arg_name}': "
                    f"{arg_value!r}. Allowed values are: {allowed!r}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises TypeError: If ``args`` is not a dict or a sequence of length 3.
    :raises ValueError: If the value is not within the specified bounds.
    :return: The original value if it is within bounds.
    """
    # Extract the value, minimum and maximum from various possible arg formats
    if isinstance(args, dict):
        value = args.get('value')
        min_val = args.get('min')
        max_val = args.get('max')
        # allow alternative key names
        if min_val is None and 'min_' in args:
            min_val = args['min_']
        if max_val is None and 'max_' in args:
            max_val = args['max_']
        if value is None:
            raise TypeError(
                "Dictionary 'args' must contain a 'value' key to validate")
    else:
        # Assume a sequence of length three: (value, min, max)
        try:
            value, min_val, max_val = args
        except Exception as exc:
            raise TypeError(
                "args must be a dict with 'value' or a sequence of "
                "length three (value, min, max)"
            ) from exc

    # If bounds were not provided, nothing to validate
    if min_val is None and max_val is None:
        return value

    # Validate that min <= max when both are defined
    if min_val is not None and max_val is not None:
        try:
            if min_val > max_val:
                raise ValueError(
                    f"minimum ({min_val}) must not be greater than maximum ({max_val})")
        except TypeError as exc:
            raise TypeError(
                "minimum and maximum must be comparable values"
            ) from exc

    # Perform boundary checks
    if min_val is not None:
        try:
            if value < min_val:
                raise ValueError(
                    f"value ({value}) is less than minimum ({min_val})")
        except TypeError as exc:
            raise TypeError(
                "value and minimum must be comparable"
            ) from exc

    if max_val is not None:
        try:
            if value > max_val:
                raise ValueError(
                    f"value ({value}) is greater than maximum ({max_val})")
        except TypeError as exc:
            raise TypeError(
                "value and maximum must be comparable"
            ) from exc

    return value

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure we have min_ and max_ attributes to compare against
    if not hasattr(self, 'min_') or not hasattr(self, 'max_'):
        raise AttributeError(
            "Object must have 'min_' and 'max_' attributes to validate arguments")

    min_val = getattr(self, 'min_')
    max_val = getattr(self, 'max_')

    # Validate that min_val and max_val are comparable types (numbers)
    if not (
        isinstance(min_val, (int, float))
        and isinstance(max_val, (int, float))
    ):
        raise TypeError("'min_' and 'max_' must be numeric types")

    if min_val > max_val:
        raise ValueError("'min_' must be less than or equal to 'max_")

    # Try to convert args into an iterable of values
    try:
        # If it's a string, treat it as a single argument (not iterable of chars)
        if isinstance(args, (str, bytes)):
            values = [args]
        else:
            values = list(args)
    except TypeError:
        # Not iterable
        raise TypeError("'args' must be an iterable of values")

    # Validate each argument
    for idx, val in enumerate(values):
        try:
            if not (min_val <= val <= max_val):
                raise ValueError(
                    f"Argument at position {idx} ({val}) is out of range "
                    f"[{min_val}, {max_val}]"
                )
        except TypeError:
            raise TypeError(
                f"Argument at position {idx} ({val}) is not comparable "
                f"to numeric bounds {min_val} and {max_val}"
            )

    # If everything is fine, return the original args (or a list copy)
    return values

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError(f"'args' must be an iterable, got {type(args).__name__}")

    # Iterate over each argument item
    for idx, item in enumerate(iterator):
        # Accept a tuple/list of exactly three elements (value, min, max)
        if isinstance(item, (list, tuple)):
            if len(item) != 3:
                raise ValueError(f"Argument at index {idx} must be a 3-element tuple/list (value, min, max), got {item!r}")
            value, min_, max_ = item
        # Accept a mapping with keys 'value', 'min', 'max'
        elif isinstance(item, dict):
            try:
                value = item["value"]
                min_ = item["min"]
                max_ = item["max"]
            except KeyError as exc:
                raise ValueError(f"Argument at index {idx} must contain 'value', 'min', and 'max' keys: missing {exc.args[0]!r}") from None
        else:
            raise TypeError(f"Argument at index {idx} must be a 3-element tuple/list or a dict with 'value', 'min', 'max' keys, got {type(item).__name__}")

        # Validate that min and max are numeric
        if not isinstance(min_, (int, float)):
            raise TypeError(f"Argument at index {idx}: 'min' must be numeric, got {type(min_).__name__}")
        if not isinstance(max_, (int, float)):
            raise TypeError(f"Argument at index {idx}: 'max' must be numeric, got {type(max_).__name__}")

        if min_ > max_:
            raise ValueError(f"Argument at index {idx}: 'min' ({min_}) is greater than 'max' ({max_})")

        # Validate that value is numeric
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument at index {idx}: 'value' must be numeric, got {type(value).__name__}")

        # Check value is within inclusive range
        if not (min_ <= value <= max_):
            raise ValueError(f"Argument at index {idx}: 'value' ({value}) is outside the range [{min_}, {max_}]")

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Each argument is expected to be an
        iterable of three elements: (value, minimum, maximum).
    """
    # Ensure args is a list or tuple
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of argument specifications")

    validated = []
    for idx, arg in enumerate(args):
        # Check that each argument is iterable and not a string/bytes
        if not isinstance(arg, (list, tuple)) or isinstance(arg, (str, bytes)):
            raise TypeError(f"Argument at position {idx} must be an iterable of length 3 (value, min, max)")

        if len(arg) != 3:
            raise TypeError(f"Argument at position {idx} must contain exactly three elements (value, min, max)")

        value, minimum, maximum = arg

        # Minimum and maximum must be provided
        if minimum is None or maximum is None:
            raise ValueError(f"Minimum and maximum values must be supplied for argument at position {idx}")

        # Ensure minimum is less than or equal to maximum
        if minimum > maximum:
            raise ValueError(f"Maximum value must be greater than or equal to minimum for argument at position {idx}")

        # Check that the value lies within the bounds
        if not (minimum <= value <= maximum):
            raise ValueError(
                f"Value {value} at position {idx} is outside the range [{minimum}, {maximum}]"
            )

        validated.append((value, minimum, maximum))

    return validated

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, (list, tuple, set)):
        raise TypeError(f"args must be a list, tuple, or set, got {type(args).__name__}")

    # Retrieve minimum and maximum bounds from self
    # The bounds may be attributes named 'min_value', 'max_value', 'min', or 'max'
    try:
        min_value = getattr(self, 'min_value')
    except AttributeError:
        try:
            min_value = getattr(self, 'min')
        except AttributeError:
            min_value = None
    try:
        max_value = getattr(self, 'max_value')
    except AttributeError:
        try:
            max_value = getattr(self, 'max')
        except AttributeError:
            max_value = None

    if min_value is None and max_value is None:
        raise AttributeError(
            "self must have at least one of 'min_value', 'max_value', 'min', or 'max' attributes to validate against")

    # Validate each argument
    for value in args:
        if min_value is not None and value < min_value:
            raise ValueError(
                f"Argument {value} is less than minimum allowed {min_value}")
        if max_value is not None and value > max_value:
            raise ValueError(
                f"Argument {value} is greater than maximum allowed {max_value}")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications (dict)
    :return: the complex type instance
    """
    # Input validation
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("`subcommand` must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("`type_name` must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("`option_name` must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("`spec_option` must be a dictionary")

    # Prepare attributes for the new type
    attrs = {
        'subcommand': subcommand,
        'option_name': option_name,
    }
    attrs.update(spec_option)

    # Construct and return the new type/class
    try:
        complex_type = type(type_name, (object,), attrs)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to construct complex type '{type_name}': {exc}"
        ) from exc
    return complex_type

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        if not isinstance(subcommand, str):
            raise TypeError('subcommand must be a string')
        if not isinstance(type_name, str):
            raise TypeError('type_name must be a string')
        if not isinstance(option_name, str):
            raise TypeError('option_name must be a string')
        if not isinstance(spec_option, dict):
            raise TypeError('spec_option must be a dict')
        complex_type = {
            'subcommand': subcommand,
            'type_name': type_name,
            'option_name': option_name,
            'specication': spec_option
        }
        return complex_type
    except Exception as exc:
        raise RuntimeError(f'Failed to create complex argument type: {exc}') from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                   spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary")

    # Resolve the factory (class or callable) for the complex type
    try:
        factory = self.load_name(type_name)
    except Exception as exc:
        raise ImportError(f"Unable to load type '{type_name}': {exc}") from exc

    # Prepare arguments for the factory; add the option name if useful
    # Some factories expect a name parameter, so we include it when present
    factory_kwargs = dict(spec_option)  # copy to avoid side‑effects
    if "name" in factory_kwargs:
        # Do not overwrite an explicit name
        pass
    else:
        factory_kwargs["name"] = option_name

    # Instantiate the complex type
    try:
        complex_type = factory(**factory_kwargs)
    except TypeError:
        # If the factory does not accept keyword arguments, fall back to positional
        try:
            complex_type = factory(*spec_option.get("args", ()))
        except Exception as exc:
            raise TypeError(f"Failed to instantiate complex type '{type_name}': {exc}") from exc
    except Exception as exc:
        raise TypeError(f"Failed to instantiate complex type '{type_name}': {exc}") from exc

    # Attach descriptor metadata for easier debugging and introspection
    if not hasattr(complex_type, "__dict__"):
        # If the resulting object is immutable (e.g., a namedtuple), create a wrapper
        class _ComplexTypeWrapper:
            def __init__(self, obj):
                self.__dict__.update({"obj": obj,
                                      "subcommand": subcommand,
                                      "option_name": option_name,
                                      "type_name": type_name})
            def __getattr__(self, name):
                return getattr(self.obj, name)
            def __repr__(self):
                return f"<{type_name} wrapper for {subcommand}:{option_name}>"
        complex_type = _ComplexTypeWrapper(complex_type)
    else:
        setattr(complex_type, "subcommand", subcommand)
        setattr(complex_type, "option_name", option_name)
        setattr(complex_type, "type_name", type_name)

    return complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Accept both dicts and iterable of pairs
    if args is None:
        raise ValueError("args must not be None")
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception as exc:  # pragma: no cover
            raise TypeError("args must be a dict or an iterable of (key, value) pairs") from exc

    # Determine control keys: first look for a predefined set on the instance
    control_keys = set()
    if hasattr(self, "control_keys") and isinstance(self.control_keys, (set, list)):
        control_keys.update(self.control_keys)
    if hasattr(self, "control_args") and isinstance(self.control_args, (set, list)):
        control_keys.update(self.control_args)

    # By convention a leading underscore marks a control argument
    for k in list(args):
        if isinstance(k, str) and k.startswith("_"):
            control_keys.add(k)

    # Split into control and nested (including custom) dictionaries
    control_args = {}
    nested_args = {}
    for k, v in args.items():
        if k in control_keys:
            control_args[k] = v
        else:
            nested_args[k] = v

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    if args is None:
        return control_args, nested_args
    if not isinstance(args, Mapping):
        raise TypeError("args must be a mapping of key/value pairs")

    for key, value in args.items():
        if key is None:
            continue
        try:
            str_key = str(key)
        except Exception:
            # skip non‐string keys
            continue
        if str_key.startswith("control_"):
            control_args[str_key[8:]] = value
        elif str_key.startswith("custom_"):
            # Custom ansible variables are included in the nested dict
            # but with the custom prefix stripped so they behave like
            # normal nested args.
            nested_args[str_key[7:]] = value
        else:
            nested_args[str_key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Validate input
        if args is None:
            return {}, {}
        if not isinstance(args, dict):
            raise TypeError("Argument 'args' must be a dict")
        control_args = {}
        nested_args = {}
        for key, value in args.items():
            if isinstance(key, str) and key.lower().startswith("control_"):
                control_args[key] = value
            else:
                nested_args[key] = value
        return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    elif not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list or dictionary")

    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("each extra_var must be a dictionary")
        vars_dict.update(item)

    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into.
    :param extra_vars: List (or single) of extra-vars (dicts).
    :return: Updated dictionary.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict

    # Normalize to list
    extra_list = extra_vars if isinstance(extra_vars, (list, tuple)) else [extra_vars]

    for item in extra_list:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, str):
            try:
                # Attempt to parse JSON string
                import json
                obj = json.loads(item)
                if isinstance(obj, dict):
                    vars_dict.update(obj)
            except Exception:
                continue
        else:
            # Unsupported type; skip
            continue

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    merged = vars_dict.copy()
    if not extra_vars:
        return merged
    if not isinstance(extra_vars, (list, tuple)):
        raise ValueError("extra_vars must be a list or tuple of dictionaries")
    for ex in extra_vars:
        if not isinstance(ex, dict):
            raise ValueError("each extra_var must be a dictionary")
        merged.update(ex)
    return merged

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: Iterable of extra-vars (either dict or sequence of (key, value) tuples)
    :return: New dictionary containing merged values
    """
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
    result = vars_dict.copy()
    if not extra_vars:
        return result
    # Handle a single dictionary
    if isinstance(extra_vars, dict):
        result.update(extra_vars)
        return result
    # Handle an iterable of dictionaries or key/value pairs
    if isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                result.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                result[key] = value
            else:
                raise ValueError("each item in extra_vars must be a dict or a two-element sequence")
        return result
    raise TypeError(f"extra_vars must be a dict or an iterable of dicts/tuples, got {type(extra_vars).__name__}")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    if not isinstance(playbook_path, str) or not playbook_path:
        raise ValueError("playbook_path must be a non-empty string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    cmd = ["ansible-playbook"]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append("-" + "v" * min(verbose, 5))
        else:
            # Accept strings like 'v', 'vv', '3', etc.
            v_str = str(verbose).lstrip("-")
            if v_str.isdigit():
                v_lvl = min(int(v_str), 5)
                cmd.append("-" + "v" * v_lvl)
            else:
                # Strip leading hyphens if any and ensure at least one v
                v_clean = v_str.replace(" ", "").replace("-", "")
                if v_clean == "":
                    v_clean = "v"
                cmd.append("-" + v_clean)
    else:
        cmd.append("-v")

    # Append extra vars as JSON
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_vars = json.dumps(extra_vars, separators=(",", ":"))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Could not JSON‑serialize extra_vars: {exc}") from exc
        cmd.extend(["--extra-vars", json_vars])

    # Append custom ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, val in ansible_args.items():
            if isinstance(val, bool):
                if val:
                    cmd.append(key)
            else:
                cmd.extend([key, str(val)])

    cmd.append(playbook_path)

    # Execute
    logger.debug("Executing ansible-playbook: %s", " ".join(cmd))
    try:
        process = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            universal_newlines=True,
        )
    except OSError as exc:
        raise RuntimeError(f"Failed to start ansible-playbook: {exc}") from exc

    stdout, stderr = process.communicate()
    if process.returncode != 0:
        # Include stdout and stderr in the error for easier debugging
        errmsg = (
            f"ansible-playbook exited with code {process.returncode}\n"
            f"stdout:\n{stdout}\n"
            f"stderr:\n{stderr}"
        )
        raise RuntimeError(errmsg)

    return stdout

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Resolve verbosity flag
    if verbose is None:
        verbosity = "-v"
    else:
        # ensure integer, clamp to reasonable range
        try:
            vcount = int(verbose)
            if vcount < 1:
                vcount = 1
        except Exception:
            vcount = 1
        verbosity = "-" + ("v" * vcount)

    # Start building command
    cmd = ["ansible-playbook", verbosity]

    # Attach custom ansible arguments
    if isinstance(ansible_args, dict):
        for key, val in ansible_args.items():
            if not isinstance(key, str):
                continue
            arg = key if key.startswith("-") else f"--{key}"
            if isinstance(val, bool):
                if val:
                    cmd.append(arg)
            elif val is None:
                cmd.append(arg)
            else:
                cmd.extend([arg, str(val)])

    # Attach extra vars if provided
    if isinstance(extra_vars, dict) and extra_vars:
        ev_parts = []
        for k, v in extra_vars.items():
            # use simple formatting; if string contains spaces, let Ansible parse it
            ev_parts.append(f"{k}={v}")
        cmd.extend(["--extra-vars", " ".join(ev_parts)])

    # Append playbook path
    cmd.append(playbook_path)

    logger.debug("Running ansible-playbook: %s", " ".join(cmd))
    try:
        process = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

    if process.returncode != 0:
        msg = (
            f"Ansible playbook failed with return code {process.returncode}\n"
            f"STDOUT:\n{process.stdout}\n"
            f"STDERR:\n{process.stderr}"
        )
        raise RuntimeError(msg)

    return process.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")
    # Retrieve the parser configuration for the given command name.
    parser_cfg = getattr(self, "parsers", {}).get(parser_name)
    if parser_cfg is None:
        raise KeyError(f"Unknown parser '{parser_name}'")
    # Iterate over each option definition in the parser configuration.
    for opt in getattr(parser_cfg, "options", []):
        opt_name = getattr(opt, "name")
        if opt_name is None:
            continue  # Skip malformed option definitions.
        # Convert if the argument is present.
        if opt_name in values_dict:
            try:
                values_dict[opt_name] = opt.convert(values_dict[opt_name])
            except Exception as exc:
                raise ValueError(
                    f"Cannot convert argument '{opt_name}' for parser '{parser_name}': {exc}"
                ) from exc
        # If the argument is missing but a default exists, apply it.
        else:
            if getattr(opt, "default", None) is not None:
                values_dict[opt_name] = opt.convert(opt.default)
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Optional: specific type definitions per parser
    type_map = getattr(self, "_type_map", {})
    options = type_map.get(parser_name, {})

    for key, val in list(values_dict.items()):
        # If the parser supplies an explicit type for this option
        if key in options:
            expected = options[key]
            try:
                if expected == "int":
                    values_dict[key] = int(val)
                elif expected == "float":
                    values_dict[key] = float(val)
                elif expected == "bool":
                    values_dict[key] = str(val).lower() in ("true", "1", "yes", "on")
                elif expected == "list":
                    if isinstance(val, str):
                        values_dict[key] = [v.strip() for v in val.split(",") if v.strip()]
                else:
                    # Keep as string if type is unknown
                    pass
            except Exception:
                # If conversion fails, leave the original string
                pass
        else:
            # Generic heuristic conversion for values that are not explicitly typed
            v = str(val)
            if v.lower() in ("true", "false", "yes", "no", "1", "0"):
                values_dict[key] = v.lower() in ("true", "1", "yes", "on")
            elif v.isdigit() or (v.startswith("-") and v[1:].isdigit()):
                try:
                    values_dict[key] = int(v)
                except Exception:
                    pass
            else:
                try:
                    values_dict[key] = float(v)
                except Exception:
                    # leave as string if no conversion applies
                    pass

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    def _convert_value(val):
        if val is None:
            return None
        if isinstance(val, (int, float, bool)):
            return val
        if isinstance(val, str):
            s = val.strip()
            lower = s.lower()
            if lower in {'true', 'false'}:
                return lower == 'true'
            # Try integer
            try:
                # Reject strings that look like floats
                if '.' not in s and 'e' not in lower and 'E' not in lower:
                    return int(s)
            except ValueError:
                pass
            # Try float
            try:
                return float(s)
            except ValueError:
                pass
            return s
        if isinstance(val, list):
            return [_convert_value(x) for x in val]
        if isinstance(val, tuple):
            return tuple(_convert_value(x) for x in val)
        if isinstance(val, dict):
            return {k: _convert_value(v) for k, v in val.items()}
        return val

    # In-place conversion
    for key in list(values_dict.keys()):
        values_dict[key] = _convert_value(values_dict[key])

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments
    """
    import re
    import json
    import ast

    # First, if a mapping of expected types is available, use it
    type_map = getattr(self, "_parser_arg_type_map", {})
    parser_map = type_map.get(parser_name, {})

    def _cast_value(name, val):
        # If the parser declares a type, use it directly
        if name in parser_map:
            cast_func = parser_map[name]
            try:
                return cast_func(val)
            except Exception:
                # Fall back to heuristic casting if custom cast fails
                pass

        # Heuristic casting
        if isinstance(val, str):
            lower = val.strip().lower()
            # None-like values
            if lower in {"none", "null", ""}:
                return None
            # Booleans
            if lower in {"true", "false"}:
                return lower == "true"
            # Integers
            if re.fullmatch(r"[+-]?\d+", val):
                try:
                    return int(val)
                except Exception:
                    pass
            # Floats
            if re.fullmatch(r"[+-]?\d*\.\d+([eE][+-]?\d+)?", val):
                try:
                    return float(val)
                except Exception:
                    pass
            # JSON-like lists, dicts, or other literals
            try:
                # Protect against unsafe eval
                return json.loads(val)
            except Exception:
                pass
            try:
                return ast.literal_eval(val)
            except Exception:
                pass
        return val

    for key, value in list(values_dict.items()):
        values_dict[key] = _cast_value(key, value)

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(current, parent_key='', result=None):
        if result is None:
            result = {}
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key, result)
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                new_key = f"{parent_key}.{idx}" if parent_key else str(idx)
                _flatten(item, new_key, result)
        else:
            result[parent_key] = current
        return result

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(spec_path):
        # try alternatives if needed
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec_data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in plugin spec: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Error reading plugin spec: {e}") from e

    return _flatten(spec_data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Try to import yaml if available
    try:
        import yaml
    except Exception:  # pragma: no cover
        yaml = None

    # Common spec file names
    spec_filenames = [
        "plugin.json",
        "spec.json",
        "plugin.yaml",
        "spec.yaml",
        "plugin.yml",
        "spec.yml",
    ]

    spec_path = None
    for fname in spec_filenames:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        # No spec file found; return empty dict
        return {}

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception:
        return {}

    # Load the spec content
    data = None
    if spec_path.endswith(".json"):
        try:
            data = json.loads(content)
        except Exception:
            return {}
    elif yaml and (spec_path.endswith(".yaml") or spec_path.endswith(".yml")):
        try:
            data = yaml.safe_load(content)
        except Exception:
            return {}
    else:
        return {}

    if not isinstance(data, dict):
        return {}

    def _flatten(d, parent_key="", sep="."):
        """Recursively flatten a nested dictionary."""
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    flattened = {}

    # Determine spec file
    spec_file = None
    for fname in ['plugin.yaml', 'plugin.yml', 'plugin.json', 'plugin-spec.yaml', 'plugin-spec.yml', 'plugin-spec.json']:
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_file = path
            break
    if not spec_file:
        return flattened  # No spec found

    # Load spec
    try:
        if spec_file.endswith('.json'):
            with open(spec_file, 'r', encoding='utf-8') as f:
                spec = json.load(f)
        else:
            try:
                yaml = __import__('yaml')
            except Exception:
                # yaml module not available
                return flattened
            with open(spec_file, 'r', encoding='utf-8') as f:
                spec = yaml.safe_load(f)
    except Exception:
        # Failed to read or parse spec
        return flattened

    def _flatten(prefix, dic):
        for key, value in dic.items():
            new_key = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                _flatten(new_key, value)
            else:
                flattened[new_key] = value

    if isinstance(spec, dict):
        _flatten('', spec)
