    candidate_filenames = [
        "manifest.json", "spec.json", "plugin.json",
        "manifest.yaml", "spec.yaml", "plugin.yaml",
        "manifest.yml", "spec.yml", "plugin.yml"
    ]

    spec_data = None
    for fname in candidate_filenames:
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            try:
                with open(path, "r", encoding="utf-8") as f:
                    if fname.endswith(".json"):
                        spec_data = json.load(f)
                    elif yaml and fname.lower().endswith((".yaml", ".yml")):
                        spec_data = yaml.safe_load(f)
            except Exception as exc:
                raise ValueError(f"Error reading spec file '{path}': {exc}")
            if spec_data is not None:
                break

    if spec_data is None:
        raise ValueError(f"No valid plugin specification file found in '{plugin_dir}'")

    def _flatten(current, parent_key=""):
        flat = {}
        if isinstance(current, dict):
            for key, value in current.items():
                compound = f"{parent_key}.{key}" if parent_key else key
                flat.update(_flatten(value, compound))
        elif isinstance(current, list):
            for idx, element in enumerate(current):
                compound = f"{parent_key}.{idx}" if parent_key else str(idx)
                flat.update(_flatten(element, compound))
        else:
            flat[parent_key] = current
        return flat

