def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    # Determine the environment variable name; default to 'CONFIG_PATH'
    env_var = getattr(self, 'CONFIG_ENV', 'CONFIG_PATH')

    # If the environment variable is already defined and non-empty, do nothing
    if env_var in os.environ and os.environ[env_var]:
        return

    # Retrieve the configuration path from the instance
    config_path = getattr(self, 'config_path', None)

    # Only attempt to set the environment variable if we have a valid path
    if config_path:
        try:
            os.environ[env_var] = str(config_path)
        except Exception:
            # Silently ignore any failures to modify environment variables
            pass

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param root_subparsers: the subparser object to extend.
    """
    try:
        if not hasattr(root_subparsers, "add_parser"):
            raise AttributeError("Expected an object with 'add_parser' method")
        spec_parser = root_subparsers.add_parser("spec", help="Spec commands")
        spec_parser.add_argument("spec", type=str, help="Target specification path")
        return spec_parser
    except Exception as exc:
        raise RuntimeError("Failed to extend CLI with spec options") from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    path_abs = os.path.abspath(path)
    root_abs = os.path.abspath(root)
    try:
        rel = os.path.relpath(path_abs, root_abs)
    except ValueError as exc:
        # Typically raised when paths are on different drives on Windows
        raise ValueError(f"Cannot compute relative path from root '{root}': {exc}")
    # If the relative path climbs up, the path was not under the root
    if rel == os.pardir or rel.startswith(os.pardir + os.sep) or os.path.isabs(rel):
        raise ValueError(f"Path '{path}' is not under root '{root}'")
    # Treat the root itself as the empty path
    if rel == os.curdir:
        return ''
    return rel

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    norm_path = os.path.normpath(os.path.abspath(path))
    norm_root = os.path.normpath(os.path.abspath(root))

    try:
        common = os.path.commonpath([norm_path, norm_root])
    except ValueError:
        raise ValueError(f"Failed to determine common path between '{path}' and '{root}'")

    if common != norm_root:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    rel = os.path.relpath(norm_path, norm_root)
    return '' if rel == '.' else rel
